# ── Borne de sortie des outils de lecture (LOT 3, Défaut A) ──────────────────
#
# Huit outils rendaient TOUT ce que le pont interne acceptait de transmettre,
# sans `limit`, sans pagination, sans drapeau de troncature — et ça partait
# dans le contexte du modèle. Le motif à suivre existe déjà dans ce fichier :
# `find_needs` transmet un `limit` (défaut 20) jusqu'au pont ; `search_mailbox`
# rend un drapeau `truncated`. Cette borne réutilise le MÊME chiffre (20) pour
# les listes qui n'ont pas de raison métier d'avoir leur propre plafond.
#
# ⚠️ Une sortie tronquée doit le DIRE, explicitement, pour que le modèle ne
# présente jamais un sous-ensemble comme un tout — c'est un enjeu de véracité
# autant que de coût. Garde GA-295 (tests/test_chat_tool_output_bounds.py).
_LIST_TOOL_CAP = 20

# #3866 — les quatre types de relation que Laura distingue (client final · ESN concurrente/interne ·
# partenaire · intermédiaire : portage, cabinet de référencement).
_RELATION_TYPES = tuple(t.value for t in RelationType if t is not RelationType.UNDETERMINED)

_FINANCE_REVENUE_FORBIDDEN = (
    "Je n'ai pas le droit de lire le chiffre d'affaires pour cette personne. Dis-le plutôt que d'annoncer un montant."
)
_FINANCE_PAYMENTS_FORBIDDEN = (
    "Je n'ai pas le droit de lire les encaissements pour cette personne. "
    "Dis-le plutôt que d'annoncer qu'il n'y a aucun impayé."
)


def _capped(items: list[Any], cap: int = _LIST_TOOL_CAP) -> tuple[list[Any], bool]:
    """Borne une liste rendue au modèle et DIT si elle a été coupée.

    Le compte est EXACT, jamais une estimation : la liste complète est déjà en
    mémoire (le pont ne pagine pas), donc comparer sa longueur avant/après la
    coupe ne devine rien."""
    return items[:cap], len(items) > cap


def _named_pipeline_rows(rows: list[Any], names: Any) -> list[Any]:
    """#3904 — « Lequel de mes comptes est à deux doigts de signer ? » : les lignes
    du diagnostic de pipe ne portent que l'identifiant de l'affaire, et Laura
    « ne pouvait pas nommer le compte ». Le pont rend `opportunityNames`
    (identifiant → compte, libellé) ; on les pose sur chaque ligne. Un nom absent
    laisse la ligne telle quelle — jamais un compte deviné."""
    if not isinstance(names, dict):
        return list(rows)
    out: list[Any] = []
    for row in rows:
        known = names.get(row.get("id")) if isinstance(row, dict) else None
        if isinstance(known, dict) and known.get("companyName"):
            out.append(
                {**row, "accountId": known.get("accountId"), "companyName": known.get("companyName"), "label": known.get("label")}
            )
        else:
            out.append(row)
    return out


# #2852.6-53 (lot EP8) — les lectures « état de l'espace » (un enregistrement,
# un pont) : « pont éteint » (`not_covered`) ne se lit jamais « le pont n'a pas
# répondu » (`provider_error`), et aucun des deux n'est « ton espace n'a rien ».
_SNAPSHOT_SOURCE = "bellum_workspace"
_SNAPSHOT_NO_ACCESS = "Je n'ai pas accès à l'état de ton espace depuis ici."
_SNAPSHOT_RESULT_TYPES = {
    "get_user_context": "workspace_user_context",
    "get_workspace_health": "workspace_health",
    "get_feature_adoption": "workspace_feature_adoption",
    "get_blocking_issues": "workspace_blocking_issues",
    "get_weakest_link_diagnosis": "weakest_link_diagnosis",
    "get_routines": "workspace_routines",
    "get_import_overview": "workspace_import_overview",
    "get_settings_overview": "workspace_settings_overview",
    "get_memory": "workspace_memory",
    "get_workspace_vocabulary": "workspace_vocabulary",
}


def _snapshot_error(result_type: str, message: str) -> dict[str, Any]:
    """Le texte d'erreur historique + l'enveloppe NOMMÉE : le statut se déduit
    de l'état réel du pont, jamais deviné par l'outil."""
    from app.models.tool_result_envelope import ToolResultStatus, error_envelope
    from app.services import bellum_api

    if not bellum_api.is_configured():
        return {
            "error": _SNAPSHOT_NO_ACCESS,
            **error_envelope(
                status=ToolResultStatus.NOT_COVERED,
                result_type=result_type,
                error_code="bridge_not_configured",
                suggested_next_step="Ouvre l'écran concerné pour consulter cette information directement.",
            ).to_wire(),
        }
    return {
        "error": message,
        **error_envelope(
            status=ToolResultStatus.PROVIDER_ERROR,
            result_type=result_type,
            error_code="bridge_unavailable",
            suggested_next_step="Réessaie dans un instant : le pont de l'espace n'a pas répondu à temps.",
        ).to_wire(),
    }


def _invalid_input(result_type: str, message: str, error_code: str, next_step: str) -> dict[str, Any]:
    """Un argument requis manquant : le texte historique + `invalid_input`."""
    from app.models.tool_result_envelope import ToolResultStatus, error_envelope

    return {
        "error": message,
        **error_envelope(
            status=ToolResultStatus.INVALID_INPUT,
            result_type=result_type,
            error_code=error_code,
            suggested_next_step=next_step,
        ).to_wire(),
    }


def _list_ok(payload: dict[str, Any], result_type: str, count: int) -> dict[str, Any]:
    """Une liste COMPLÈTE d'une source unique : `empty` si la source a répondu
    zéro ligne, `success` sinon. Le contenu de l'outil gagne sur l'enveloppe."""
    from app.models.tool_result_envelope import db_read_envelope

    envelope = db_read_envelope(
        result_type=result_type, items_count=count, total_found=count, truncated=False, source=_SNAPSHOT_SOURCE
    ).to_wire()
    return {**{k: v for k, v in envelope.items() if k not in payload}, **payload}


def _snapshot_ok(payload: dict[str, Any], result_type: str) -> dict[str, Any]:
    """La charge utile du pont, relayée TELLE QUELLE, + l'enveloppe de succès.
    Le contenu du pont gagne toujours : une clé qu'il porte déjà n'est jamais
    écrasée par un champ d'enveloppe."""
    from app.models.tool_result_envelope import ToolResultEnvelope, ToolResultStatus

    envelope = ToolResultEnvelope(
        status=ToolResultStatus.SUCCESS,
        result_type=result_type,
        sources_consulted=[_SNAPSHOT_SOURCE],
        sources_succeeded=[_SNAPSHOT_SOURCE],
    ).to_wire()
    return {**{k: v for k, v in envelope.items() if k not in payload}, **payload}


def _bridge_read_failure(
    result: Mapping[str, Any] | None,
    result_type: str,
    down_message: str,
    *,
    forbidden: Mapping[str, str] | None = None,
    not_found: Mapping[str, str] | None = None,
) -> dict[str, Any] | None:
    """#2852.6-53 (lot X14) — la porte d'une lecture du pont NestJS, partagée
    par la famille pilotage : `None` = le pont n'a pas répondu (`not_covered` si
    éteint, `provider_error` sinon, jamais « rien à signaler ») ; une erreur
    DROIT (`forbidden` : code → phrase) = `permission_denied`, jamais « zéro » ;
    un objet introuvable (`not_found`) = `empty`, jamais une panne ; toute
    autre erreur du pont = `provider_error`. Rend `None` quand la lecture a
    réellement répondu : l'appelant relaie alors le contenu TEL QUEL."""
    from app.models.tool_result_envelope import ToolResultEnvelope, ToolResultStatus, error_envelope

    if result is None:
        return _snapshot_error(result_type, down_message)
    code = result.get("error")
    if not code:
        return None
    if forbidden and code in forbidden:
        return {
            "error": forbidden[str(code)],
            **error_envelope(
                status=ToolResultStatus.PERMISSION_DENIED,
                result_type=result_type,
                error_code=str(code),
                suggested_next_step="Demande l'accès correspondant, ou continue sans cette information.",
            ).to_wire(),
        }
    if not_found and code in not_found:
        return {
            "error": not_found[str(code)],
            **ToolResultEnvelope(
                status=ToolResultStatus.EMPTY,
                result_type=result_type,
                sources_consulted=[_SNAPSHOT_SOURCE],
                sources_succeeded=[_SNAPSHOT_SOURCE],
            ).to_wire(),
        }
    return _snapshot_error(result_type, down_message)


# #3246.3 / #3246.5 (18/10) — la grille de similarité : 10 dimensions NOMMÉES, calculée ici et non plus
# énumérée de mémoire par le modèle (la prod répondait « 9 dimensions », sans organisation ni relation).
_SIMILARITY_GRID: tuple[tuple[str, str | None], ...] = (
    ("secteur", "sector"),
    ("taille", "size"),
    ("position dans un groupe", None),
    ("territoire", None),
    ("offre", None),
    ("stratégie d'approche", None),
    ("modèle d'achat", None),
    ("organisation de la décision", "organisation"),
    ("stade de relation", "relation"),
    ("position dans le cycle habituel", "timing"),
)


def _similarity_dimensions_grid(result: dict[str, Any]) -> list[dict[str, str]]:
    """Une ligne par dimension : `comparée`, ou `non évaluée` avec sa raison — jamais un 0, jamais une
    dimension passée sous silence."""
    gaps: dict[str, str] = {}
    for gap in result.get("unavailableDimensions") or []:
        if isinstance(gap, dict) and isinstance(gap.get("dimension"), str):
            gaps[gap["dimension"]] = str(gap.get("reason") or "non évaluable pour ce compte")
    known = result.get("targetKnown") if isinstance(result.get("targetKnown"), dict) else {}
    grid: list[dict[str, str]] = []
    for label, key in _SIMILARITY_GRID:
        if key in gaps:
            grid.append({"dimension": label, "status": "non évaluée", "reason": gaps[key]})
        elif key in ("sector", "size") and known.get(key) is False:
            grid.append({"dimension": label, "status": "non évaluée", "reason": "non renseignée sur ce compte"})
        else:
            grid.append({"dimension": label, "status": "comparée"})
    return grid


def _case_memory_sentences(lines: object, target_known: dict[str, Any] | None = None) -> list[str]:
    """#3246 / #3210.1 (lot Q02) — « N gagnés / M perdus de même secteur », une phrase PAR dimension
    (secteur, taille, position de groupe), calculée sur `caseMemory` : le total seul (« 3 gagnés et 2
    perdus ») ne dit pas sur quelle ressemblance il repose. Aucune probabilité ; une dimension sans
    cas (0 des deux côtés) ou illisible n'a AUCUNE phrase — jamais un « 0 / 0 » inventé."""
    # #3246 (décision Louis 10/10) — SECTEUR D'ABORD : le décompte principal est celui du même secteur,
    # la taille vient en second (« dont K … de taille comparable ») ; sans affaire du même secteur on le
    # DIT, puis on donne le décompte par taille. Jamais une probabilité.
    ranked: list[tuple[int, str, str]] = []  # (rang, dimension, phrase)
    for line in lines if isinstance(lines, list) else []:
        if not isinstance(line, dict):
            continue
        won, lost = line.get("won"), line.get("lost")
        if not all(isinstance(n, int) and not isinstance(n, bool) and n >= 0 for n in (won, lost)):
            continue
        if won + lost == 0:
            continue
        dimension = " ".join(str(line.get("dimension") or "").split())
        if not dimension:
            continue
        value = " ".join(str(line.get("value") or "").split())
        suffix = f" ({value})" if value else ""
        count = f"{won} {'gagné' if won < 2 else 'gagnés'} / {lost} {'perdu' if lost < 2 else 'perdus'}"
        if dimension == "secteur et taille":
            ranked.append((1, dimension, f"dont {count} de taille comparable{suffix}"))
        else:
            ranked.append((0 if dimension == "secteur" else 2, dimension, f"{count} de même {dimension}{suffix}"))
    ranked.sort(key=lambda item: item[0])  # tri stable : l'ordre d'origine tient à rang égal
    sentences = [sentence for _, _, sentence in ranked]
    has_sector = any(dimension == "secteur" for _, dimension, _ in ranked)
    if target_known is None:
        if sentences and not has_sector:
            sentences.insert(0, "aucune affaire gagnée ou perdue du même secteur")
        return sentences
    # #3246 (lot RAA 10/10) — le décompte promis (« N gagnés / M perdus de même secteur », « dont K de
    # taille comparable ») ne disparaît plus quand rien n'est partagé : une absence MESURÉE se dit
    # « aucune » ; une dimension NON RENSEIGNÉE sur le compte se nomme — jamais « 0 gagné / 0 perdu ».
    sector_known = target_known.get("sector") is True
    size_known = target_known.get("size") is True
    has_cross = any(dimension == "secteur et taille" for _, dimension, _ in ranked)
    has_size = any(dimension == "taille" for _, dimension, _ in ranked)
    if not has_sector:
        sentences.insert(
            0,
            "aucune affaire gagnée ou perdue du même secteur"
            if sector_known
            else "secteur du compte non renseigné : pas de décompte par secteur",
        )
    if not has_cross:
        if not size_known:
            absent = "taille du compte non renseignée : pas de décompte « de taille comparable »"
        elif has_sector:
            absent = "dont aucune affaire de taille comparable"
        elif not has_size:
            absent = "aucune affaire de taille comparable (la taille du compte est connue, aucun cas ne la partage)"
        else:
            absent = ""
        if absent:
            sentences.insert(min(1, len(sentences)), absent)
    return sentences


def _bridge_read_ok(payload: dict[str, Any], result_type: str, items_key: str | None = None) -> dict[str, Any]:
    """Le contenu du pont, TEL QUEL, + l'enveloppe de succès. Avec `items_key` :
    `empty` quand la liste est vide (la source a répondu zéro ligne) et
    `partial` quand le pont a lui-même dit `truncated`."""
    items = payload.get(items_key) if items_key else None
    if not isinstance(items, list):
        return _snapshot_ok(payload, result_type)
    from app.models.tool_result_envelope import db_read_envelope

    envelope = db_read_envelope(
        result_type=result_type,
        items_count=len(items),
        total_found=len(items),
        truncated=payload.get("truncated") is True,
        source=_SNAPSHOT_SOURCE,
    ).to_wire()
    return {**{k: v for k, v in envelope.items() if k not in payload}, **payload}


def _parse_page_cursor(raw: Any, total: int) -> int | None:
    """#2852.25/.26 — un curseur est le décalage (entier ≥ 0, < total) rendu par
    la page précédente. Illisible ou hors liste → `None` : jamais « la page 1 »
    en silence."""
    text = str(raw or "").strip()
    if not text:
        return 0
    if not text.isdigit():
        return None
    offset = int(text)
    return offset if offset < total else None


def _paginate(items: list[Any], cursor: Any, cap: int = _LIST_TOOL_CAP) -> tuple[list[Any], str | None, bool] | None:
    """Une page de `items` (déjà en mémoire, le pont ne pagine pas) : la page,
    le curseur de la SUIVANTE (absent sur la dernière), et si `items` est plus
    long que la page. `None` quand `cursor` n'est pas un décalage valide."""
    offset = _parse_page_cursor(cursor, len(items))
    if offset is None:
        return None
    page = items[offset : offset + cap]
    more = offset + cap < len(items)
    return page, (str(offset + cap) if more else None), more


