def _years_ago_iso(years: int, *, today: date | None = None) -> str:
    """Même calcul que `yearsAgo` (`discover-query.ts`) : AAAA-MM-JJ, N ans avant
    aujourd'hui (UTC). Le 29 février retombe sur le 28 une année non bissextile —
    `date.replace` lève sinon, et une date de création n'a pas à échouer pour ça.
    """
    base = today or datetime.now(UTC).date()
    try:
        return base.replace(year=base.year - years).isoformat()
    except ValueError:
        return base.replace(year=base.year - years, day=28).isoformat()
