# #4982.3 (prod 03/11, ia d53a8efd) — les jetons de région de l'API (`FRENCH_REGIONS`, packages/contracts
# market-pattern.ts) en libellés lisibles. Un jeton inconnu se rend tel quel, jamais deviné.
_REGION_LABELS: dict[str, str] = {
    "ile_de_france": "Île-de-France",
    "auvergne_rhone_alpes": "Auvergne-Rhône-Alpes",
    "hauts_de_france": "Hauts-de-France",
    "pays_de_la_loire": "Pays de la Loire",
    "nouvelle_aquitaine": "Nouvelle-Aquitaine",
    "occitanie": "Occitanie",
    "provence_alpes_cote_d_azur": "Provence-Alpes-Côte d'Azur",
    "grand_est": "Grand Est",
    "bretagne": "Bretagne",
    "normandie": "Normandie",
    "centre_val_de_loire": "Centre-Val de Loire",
    "bourgogne_franche_comte": "Bourgogne-Franche-Comté",
    "corse": "Corse",
}


def _french_count(value: int) -> str:
    """73545 → « 73 545 » (séparateur de milliers à la française)."""
    return f"{value:,}".replace(",", " ")


def _zone_rows_by_region(zones: list[Any]) -> list[dict[str, Any]]:
    """Somme les lignes région×département de l'API par région, triées par nombre décroissant."""
    by_region: dict[str, dict[str, Any]] = {}
    for row in zones:
        if not isinstance(row, dict) or not isinstance(row.get("count"), int):
            continue
        token = row.get("region")
        if not isinstance(token, str) or not token:
            continue
        label = _REGION_LABELS.get(token, token)
        entry = by_region.setdefault(label, {"region": label, "departments": [], "count": 0})
        entry["count"] += row["count"]
        department = row.get("department")
        if isinstance(department, str) and department and department not in entry["departments"]:
            entry["departments"].append(department)
    for entry in by_region.values():
        entry["departments"].sort()
    return sorted(by_region.values(), key=lambda e: (-e["count"], e["region"]))


def _zone_region_table(regions: list[dict[str, Any]], unknown: int) -> dict[str, Any]:
    """La carte `file_export` de la répartition : les nombres en chaînes (le schéma n'accepte que du texte)."""
    rows = [{"cells": [r["region"], _french_count(r["count"])]} for r in regions]
    if unknown > 0:
        rows.append({"cells": ["Lieu inconnu", _french_count(unknown)]})
    return {
        "type": "file_export",
        "title": "Répartition des contacts par région",
        "filename": "repartition_contacts_par_region.csv",
        "columns": ["Région", "Contacts"],
        "rows": rows,
    }


