# #3289 (#3264.31/.32/.33, lot P09 30/09) — le TIMING appris par l'espace.
# Aucune donnée neuve : `SendTimingService` (NestJS) mesure les gestes FAITS
# (canal, instant réel, issue déclarée, fuseau et séniorité du contact). Cet
# outil est la LECTURE ; il ne recommande jamais un créneau sous le seuil de
# tentatives et ne rend jamais un pourcentage.
SEND_TIMING_TOOL: dict[str, Any] = {
    "name": "get_send_timing",
    "description": (
        "Le créneau d'envoi que l'ESPACE de l'utilisateur a appris : par canal, le jour et la "
        "plage de la journée (heure LOCALE du contact) où ses relances obtiennent des réponses, "
        "mesuré sur ses gestes déjà faits et leurs issues déclarées. À utiliser pour « quand "
        "relancer par e-mail ? », « à quelle heure j'appelle ? », « quel est mon meilleur "
        "créneau ». Cite les COMPTES rendus (« 4 réponses sur 4 tentatives ») — JAMAIS un "
        "pourcentage. Un canal sans `best` n'a pas assez de gestes mesurés (ou aucun créneau ne "
        "fait mieux que les autres) : dis-le, n'invente aucun horaire générique."
    ),
    "input_schema": {
        "type": "object",
        "properties": {
            "seniority": {
                "type": "string",
                "description": (
                    "La séniorité des contacts visés (ex. « director »), SEULEMENT si l'utilisateur "
                    "a précisé le profil à qui il écrit."
                ),
            },
        },
        "required": [],
    },
}

_SEND_TIMING_WEEKDAYS_FR = {
    "monday": "lundi",
    "tuesday": "mardi",
    "wednesday": "mercredi",
    "thursday": "jeudi",
    "friday": "vendredi",
}
_SEND_TIMING_BANDS_FR = {
    "morning": "matin",
    "midday": "midi",
    "afternoon": "après-midi",
    "evening": "fin de journée",
}
_SEND_TIMING_REASONS_FR = {
    "not_enough_attempts": "Pas assez de gestes mesurés sur ce canal pour recommander un créneau.",
    "no_difference": "Aucun créneau ne fait mieux que les autres sur ce canal.",
}


def _send_timing_view(result: dict[str, Any]) -> dict[str, Any]:
    """Met en mots ce que NestJS a mesuré. Un créneau hors vocabulaire n'est
    jamais deviné : il devient `None`, pas un horaire approximatif."""
    channels: list[dict[str, Any]] = []
    for raw in result.get("channels") or []:
        if not isinstance(raw, Mapping):
            continue
        best = raw.get("best")
        label = None
        if isinstance(best, Mapping):
            day = _SEND_TIMING_WEEKDAYS_FR.get(str(best.get("weekday")))
            band = _SEND_TIMING_BANDS_FR.get(str(best.get("band")))
            label = f"{day} {band}" if day and band else None
        view: dict[str, Any] = {
            "channel": raw.get("channel"),
            "attempts": raw.get("attempts"),
            "answered": raw.get("answered"),
            "best": None,
        }
        if label and isinstance(best, Mapping):
            view["best"] = {
                "label": label,
                "answered": best.get("answered"),
                "attempts": best.get("attempts"),
            }
            view["message"] = (
                f"{label} (heure du contact) : {best.get('answered')} réponses sur {best.get('attempts')} tentatives."
            )
        else:
            view["message"] = _SEND_TIMING_REASONS_FR.get(
                str(raw.get("reason")), "Pas assez de gestes mesurés sur ce canal pour recommander un créneau."
            )
        channels.append(view)
    out: dict[str, Any] = {"channels": channels}
    if not channels:
        out["message"] = "Aucun geste daté avec une issue déclarée dans cet espace : il n'y a encore rien à mesurer."
    return out


# #1995 — décision Louis 14/09/2026 : une personne connue du seul CRM devient une
# fiche Bellum sur geste de l'utilisateur, et le rappel devient possible ENSUITE.
#
# Mesuré en production le 14/09 : Sandrine Pata est citée par le CRM connecté sur
# THALES, le compte porte 2 027 fiches Bellum, aucune « Pata ». Laura disait
# « fiche Bellum absente » puis renvoyait vers une fiche qui n'existe pas — les
# quatre outils qui exigent un `contact_id` restaient inatteignables.
#
# ⚠️ AUCUN `contact_id` dans ce schéma, et c'est le point : la fiche n'existe pas
# encore. Cet outil est le SEUL du copilote dont la cible n'est pas déjà une ligne
# du portefeuille — il porte donc les champs BRUTS que le contexte de présence CRM
