#: #4016 L3 — les outils dont le résultat porte un CORPS de message : jamais écrit dans la table de
#: rejeu (lue côté espace), jamais cité. Le corps vit le temps du tour, dans la boîte de l'utilisateur.
_BODY_BEARING_TOOLS: frozenset[str] = frozenset({"read_mail_thread", "read_beeper_conversation"})

_BEEPER_NOT_CONNECTED = (
    "Beeper n'est pas branché à Bellum. L'utilisateur peut le connecter dans Réglages › Intégrations "
    "(accès distant de Beeper Desktop + son tunnel)."
)


def _beeper_state_error(result: Mapping[str, Any] | None) -> dict[str, Any] | None:
    """#4406.5 — un état autre que `connected` est NOMMÉ, jamais rendu comme une liste vide."""
    if result is None:
        return {"error": "Le pont vers Beeper n'a pas répondu. Je ne peux pas lire tes conversations sans lui."}
    state = result.get("state")
    if state == "connected":
        return None
    if state == "unreachable":
        return {"error": f"Beeper ne répond pas : {result.get('reason') or 'application fermée ou tunnel coupé.'}"}
    if state == "pending":
        return {"error": "Le branchement de Beeper n'est pas terminé : il reste à valider l'accès dans Intégrations."}
    return {"error": _BEEPER_NOT_CONNECTED}


async def _read_beeper_conversation(user_id: str, tool_input: Mapping[str, Any]) -> dict[str, Any]:
    """#4406.5 (c96) — `user_id` est celui du tour authentifié : rien de ce que le modèle écrit ne
    choisit la messagerie lue. Lecture seule, bornée ; aucun chemin d'envoi."""
    from app.services import bellum_api

    if not bellum_api.is_configured():
        return {"error": "Je n'ai pas accès à Beeper depuis ici. Vérifie qu'il est branché dans Réglages › Intégrations."}
    chat_id = str(tool_input.get("chat_id") or "").strip()
    if not chat_id:
        listing = await bellum_api.list_beeper_conversations(user_id)
        failure = _beeper_state_error(listing)
        if failure:
            return failure
        conversations = [c for c in ((listing or {}).get("conversations") or []) if isinstance(c, Mapping)]
        return {
            "conversations": [
                {
                    "chat_id": c.get("chatId"),
                    "network": c.get("network"),
                    "title": c.get("title"),
                    "type": c.get("type"),
                    "unread": c.get("unreadCount"),
                    "last_activity": c.get("lastActivity"),
                    # Coordonnées pro en clair (c87) — celles que Beeper rend, rien de deviné.
                    "participants": [
                        {
                            "name": p.get("fullName"),
                            "phone": p.get("phoneNumber"),
                            "email": p.get("email"),
                            "handle": p.get("username"),
                        }
                        for p in (c.get("participants") or [])
                        if isinstance(p, Mapping) and not p.get("isSelf")
                    ],
                    "contact": c.get("contact"),
                }
                for c in conversations
            ]
        }
    chat = await bellum_api.read_beeper_chat(user_id, chat_id=chat_id)
    failure = _beeper_state_error(chat)
    if failure:
        return failure
    raw = [m for m in ((chat or {}).get("messages") or []) if isinstance(m, Mapping)]
    kept = raw[-_BEEPER_MAX_MESSAGES:]
    return {
        "chat_id": chat_id,
        "messages": [
            {
                "direction": "outbound" if m.get("isSender") else "inbound",
                "from": m.get("senderName"),
                "date": m.get("timestamp"),
                "text": str(m.get("text") or "")[:_BEEPER_MAX_CHARS],
            }
            for m in kept
        ],
        "truncated": len(raw) > len(kept) or any(len(str(m.get("text") or "")) > _BEEPER_MAX_CHARS for m in kept),
    }


async def _read_mail_threads(user_id: str, raw_ids: list[Any]) -> dict[str, Any]:
    """#4016.3b — plusieurs fils de LA boîte de l'utilisateur authentifié, pour une synthèse.

    Même doctrine que le fil unique (c96) : jamais la boîte d'un collègue (`user_id` est celui
    du tour), le corps ne sert qu'à ce tour. Bornes : cinq fils, doublons retirés, chaque fil
    plus court ; ce qui dépasse est NOMMÉ (`threads_not_read`), un fil illisible aussi, et une
    messagerie muette pour tout le lot est une erreur — jamais une synthèse de rien."""
    from app.services import bellum_api

    ids: list[str] = []
    for raw in raw_ids:
        thread_id = str(raw or "").strip()
        if thread_id and thread_id not in ids:
            ids.append(thread_id)
    if not ids:
        return {"error": "Il me faut l'identifiant d'au moins un fil (rendu par la recherche de messagerie)."}
    wanted, skipped = ids[:_MAIL_THREADS_MAX], ids[_MAIL_THREADS_MAX:]
    threads: list[dict[str, Any]] = []
    answered = 0
    for thread_id in wanted:
        thread = await bellum_api.read_mail_thread(user_id, thread_id=thread_id)
        if thread is None:
            threads.append({"thread_id": thread_id, "error": "La messagerie n'a pas répondu pour ce fil."})
            continue
        answered += 1
        if thread.get("error"):
            threads.append({"thread_id": thread_id, "error": str(thread["error"])})
            continue
        raw_messages = [m for m in (thread.get("messages") or []) if isinstance(m, Mapping)]
        kept = raw_messages[-_MAIL_THREADS_MAX_MESSAGES:]
        threads.append(
            {
                "thread_id": str(thread.get("threadId") or thread_id),
                "subject": thread.get("subject"),
                "messages": [
                    {
                        "direction": m.get("direction"),
                        "date": m.get("date"),
                        "from": m.get("from"),
                        "text": str(m.get("text") or "")[:_MAIL_THREADS_MAX_CHARS],
                    }
                    for m in kept
                ],
                "truncated": bool(thread.get("truncated")) or len(raw_messages) > len(kept),
            }
        )
    if answered == 0:
        return {
            "error": (
                "Ta messagerie n'a pas répondu ou n'est pas connectée. Je ne peux pas synthétiser ces fils sans elle."
            )
        }
    result: dict[str, Any] = {
        "threads": threads,
        "threads_read": sum(1 for t in threads if "error" not in t),
    }
    if skipped:
        result["threads_not_read"] = skipped
        result["threads_truncated"] = True
    return result


