def _deep_link_screens_digest() -> str:
    lines = []
    for entry in DEEP_LINK_SCREENS:
        params = entry["params"]
        read = ", ".join(f"`{param}`" for param in params) if params else "aucun"
        lines.append(f"- `{entry['route']}` — {entry['description']} Filtres lus : {read}.")
    return "\n".join(lines)


def _deep_link_entry(path: str) -> dict[str, Any] | None:
    """L'écran catalogué que désigne ce chemin, ou `None` s'il n'est pas couvert."""
    import re

    id_segment = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$")
    segments = path.split("/")
    for entry in DEEP_LINK_SCREENS:
        expected = str(entry["route"]).split("/")
        if len(expected) != len(segments):
            continue
        if all(e == s or (e == ":id" and id_segment.match(s)) for e, s in zip(expected, segments, strict=True)):
            return entry
    return None


def _deep_link_refusal(route: str) -> str | None:
    """#1933.9 — la raison de refuser un lien dont un filtre ne serait pas LU, ou `None`."""
    from urllib.parse import parse_qsl

    path, _, query = route.split("#", 1)[0].partition("?")
    if len(path) > 1 and path.endswith("/"):
        path = path[:-1]
    entry = _deep_link_entry(path)
    if entry is None:
        return None
    read = tuple(entry["params"])
    pairs = parse_qsl(query, keep_blank_values=True)
    unknown = sorted({key for key, _value in pairs} - set(read))
    if not unknown:
        # #2162.27 — sur `/search`, chaque clé est lue, mais un champ ne l'est
        # que par SON preset : la cohérence se vérifie ici, pas à l'arrivée.
        return _search_preset_refusal(pairs) if entry["route"] == "/search" else None
    names = ", ".join(f"`{key}`" for key in unknown)
    if read:
        return (
            f"L'écran `{entry['route']}` ne lit pas {names} : ce filtre disparaîtrait à l'arrivée. "
            f"Il ne lit que {', '.join(f'`{param}`' for param in read)}. Retire ce qu'il ne lit pas "
            "et dis le reste dans ta réponse."
        )
    return (
        f"L'écran `{entry['route']}` ne lit aucun filtre dans son lien ({names} disparaîtrait à "
        "l'arrivée). Propose la route sans paramètre et dis le reste dans ta réponse."
    )


# ── Laura compte avant de proposer (décision Louis, 15/09/2026) ─────────────
#
# Le défaut corrigé : un lien profond VALIDE (route connue, filtre LU par
# `_deep_link_refusal` ci-dessus) qui ne ramène AUCUNE ligne atterrit sur un
# écran vide — l'utilisateur le découvre en cliquant, pas nous.
#
# L'OBJECTION ÉCARTÉE, devenue la contrainte de ce qui suit : proposer un lien
# est aujourd'hui gratuit et instantané (aucun appel réseau), dans un tour
# borné à 90 s (`CHAT_TURN_BUDGET_S`) sous un plafond DUR de 105 s
# (`CHAT_TURN_CEILING_S`). Donc le compte a SON PROPRE budget de latence
# (`DEEP_LINK_COUNT_BUDGET_S`, très en dessous des deux), et SON ÉCHEC
# N'EMPÊCHE JAMAIS LA PROPOSITION — la dégradation est le comportement NORMAL,
# jamais un cas d'erreur. Trois cas, et seulement trois (voir `_deep_link_count`
# et son appelant) :
#   > 0       → le lien est proposé, `proposal.count` PEUT le nommer ;
#   = 0 MESURÉ → le lien n'est PAS proposé, une erreur le dit ;
#   non mesuré → le lien est proposé COMME AUJOURD'HUI, sans aucun nombre.
# « Non mesuré » n'est jamais « 0 » : un budget dépassé, une erreur, une
# capacité coupée ne se lisent JAMAIS comme un filtre vide.


def _deep_link_is_countable(entry: dict[str, Any]) -> bool:
    """Un écran de DÉTAIL (route qui porte `:id`) n'est JAMAIS comptable, quel
    que soit le drapeau `countable` du catalogue : compter « combien de fiches
    à cette adresse » n'a pas de sens pour une fiche UNIQUE. Le drapeau ne fait
    qu'AJOUTER une restriction à celles déjà structurelles, il n'en retire
    jamais une — c'est ce qui protège `/consultants/:id/reverse-market` même
    si un catalogue futur le marquait `countable` par erreur."""
    return bool(entry.get("countable")) and ":id" not in str(entry["route"])


#: Les routes du catalogue pour lesquelles « combien de lignes ce filtre
#: ramène-t-il » a une réponse aujourd'hui. Non-vide : `test_the_countable_
#: corpus_is_not_empty` (tests Python) le vérifie — un corpus vide serait une
#: garde qui ne garde rien.
_COUNTABLE_DEEP_LINK_ROUTES: frozenset[str] = frozenset(
    str(entry["route"]) for entry in DEEP_LINK_SCREENS if _deep_link_is_countable(entry)
)

#: Le budget par défaut du compte, EN SECONDES. Ancré sur le tour du copilote :
#: 90 s de budget normal (`CHAT_TURN_BUDGET_S`), 105 s de plafond DUR
#: (`CHAT_TURN_CEILING_S`). Proposer un lien est normalement INSTANTANÉ (aucun
#: appel réseau) ; 3 s laisse un aller-retour réseau bien senti sans jamais
#: devenir, à lui seul, la raison d'un tour qui traîne — même cumulé sur
#: plusieurs outils d'un même tour, il reste un ordre de grandeur sous les 90 s.
_DEEP_LINK_COUNT_DEFAULT_BUDGET_S = 3.0


def _deep_link_count_budget_s() -> float:
    """Le budget, réglable par `DEEP_LINK_COUNT_BUDGET_S` — absent ou illisible
    (pas un nombre, ou <= 0) retombe sur le défaut plutôt que de désactiver le
    budget : un budget à 0 ou négatif ferait toujours échouer le compte, un
    budget infini le ferait ne JAMAIS échouer, et aucun des deux n'est le
    comportement demandé."""
    raw = (os.environ.get("DEEP_LINK_COUNT_BUDGET_S") or "").strip()
    if not raw:
        return _DEEP_LINK_COUNT_DEFAULT_BUDGET_S
    try:
        value = float(raw)
    except ValueError:
        return _DEEP_LINK_COUNT_DEFAULT_BUDGET_S
    return value if value > 0 else _DEEP_LINK_COUNT_DEFAULT_BUDGET_S


#: #2852.36 — le budget de `run_account_search`, EN SECONDES, DISTINCT de
#: `_deep_link_count_budget_s` (3 s) : celui-ci borne un aperçu `limit=1`
#: avant de proposer un LIEN, celui-là borne la recherche RÉELLE que
#: l'utilisateur attend à l'écran — un budget aussi serré y ferait échouer des
#: recherches parfaitement saines. 20 s laisse largement la place à un aller-
#: retour réseau lent tout en restant un ordre de grandeur sous le plafond dur
#: du tour (`CHAT_TURN_CEILING_S`, 105 s) : sans cette borne, une recherche qui
#: bloque tient le tour ENTIER jusqu'à ce plafond, jamais nommé comme un échec
#: distinct — c'est le trou que #2852.36 ferme.
#:
#: #3759.3 (recette prod 09/10, « cartographie de Montpellier », ~70 s puis
#: « recherche interrompue ») — ce budget valait 20,0 s, EXACTEMENT la valeur
#: de `discover.DISCOVER_TIME_BUDGET_S` que `discover_registry` porte lui-même
#: en interne pour rendre un résultat PARTIEL/dégradé plutôt que d'échouer
#: (« Un résultat partiel se dit, il ne se cache pas », `discover.py:101-118`).
#: Deux budgets identiques et IMBRIQUÉS courent la même horloge : l'extérieur
#: coupe à la même seconde que l'intérieur essaie de conclure proprement — au
#: mieux une course perdue à chaque fois, au pire un `asyncio.wait_for` qui
#: annule la coroutine AVANT que sa propre dégradation n'ait eu le temps de
#: construire sa réponse, jetant les candidats déjà trouvés. D'où le résultat
#: observé : jamais de carte partielle, toujours l'échec sec. La marge
#: ci-dessous laisse l'intérieur TERMINER son repli gracieux (candidats déjà
#: en main + `degraded[]`) avant que l'extérieur ne coupe — c'est CE résultat,
#: non vide, que `_search_map`/`_search_ranking` peuvent rendre en carte
#: partielle au lieu de rien.
_ACCOUNT_SEARCH_BUDGET_MARGIN_S = 5.0


def _account_search_default_budget_s() -> float:
    """`discover.DISCOVER_TIME_BUDGET_S` + la marge ci-dessus — jamais un
    second nombre écrit à la main (GA-26) : le budget EXTÉRIEUR doit toujours
    rester strictement au-dessus du budget INTÉRIEUR qu'il enveloppe, sans quoi
    #3759.3 se reproduit à la prochaine modification de l'un des deux."""
    from app.routers.discover import DISCOVER_TIME_BUDGET_S

    return DISCOVER_TIME_BUDGET_S + _ACCOUNT_SEARCH_BUDGET_MARGIN_S


def _account_search_budget_s() -> float:
    """Le budget, réglable par `ACCOUNT_SEARCH_BUDGET_S` — même garde-fou que
    `_deep_link_count_budget_s` : absent, illisible, nul ou négatif retombe
    sur le défaut plutôt que de désactiver le budget."""
    default = _account_search_default_budget_s()
    raw = (os.environ.get("ACCOUNT_SEARCH_BUDGET_S") or "").strip()
    if not raw:
        return default
    try:
        value = float(raw)
    except ValueError:
        return default
    return value if value > 0 else default


#: Traduction des paramètres LUS par `/contacts` (`DEEP_LINK_SCREENS`) vers le
#: contrat PUBLIC que `POST /internal/copilot/contacts/count` attend
#: (`contactListQuerySchema`, `@bellum/contracts`) — la MÊME forme que l'écran
#: envoie, pour ne jamais compter un filtre différent de celui qui sera
#: réellement appliqué au clic.
_CONTACTS_COUNT_PARAM_MAP: dict[str, str] = {
    "q": "q",
    "role": "role",
    "company": "company",
    "channel": "channel",
    "state": "state",
    # #1903.15 — même contrat public que `company` : `accountId` est le nom
    # attendu par `contactListQuerySchema` (`@bellum/contracts`).
    "account_id": "accountId",
}


def _contacts_count_payload(query_pairs: list[tuple[str, str]]) -> dict[str, Any]:
    """Deux traductions, comme `useContactsFilters.ts` côté web : `dormant`
    (le nombre de mois affiché dans l'URL) → `dormantMonths` (le champ typé de
    l'API), et `unassigned` (présence dans l'URL) → un booléen. Tout le reste
    passe tel quel."""
    payload: dict[str, Any] = {}
    for key, value in query_pairs:
        if key == "dormant":
            if value.isdigit():
                payload["dormantMonths"] = int(value)
            continue
        if key == "unassigned":
            if value.strip().lower() in ("1", "true"):
                payload["unassigned"] = True
            continue
        mapped = _CONTACTS_COUNT_PARAM_MAP.get(key)
        if mapped and value:
            payload[mapped] = value
    return payload


async def _count_contacts_deep_link(user_id: str, query: str) -> int | None:
    from urllib.parse import parse_qsl

    from app.services import bellum_api

    payload = _contacts_count_payload(parse_qsl(query, keep_blank_values=True))
    return await bellum_api.count_contacts(user_id, payload, timeout_s=_deep_link_count_budget_s())


#: Un compteur par route COMPTABLE — la seule case à ajouter pour étendre le
#: compte à un nouvel écran (avec son `"countable": True` dans le catalogue).
_DEEP_LINK_COUNTERS: dict[str, Any] = {
    "/contacts": _count_contacts_deep_link,
}


async def _deep_link_count(user_id: str, route: str) -> int | None:
    """Le compte AVANT de proposer, ou `None` — « non mesuré », jamais 0 — dès
    que le compte n'a pas pu aboutir : capacité coupée, écran non comptable,
    budget dépassé, erreur. Réutilise `_deep_link_entry`/le découpage
    route+query de `_deep_link_refusal` juste au-dessus : la MÊME
    interprétation d'une route cataloguée, jamais une seconde (GA-26)."""
    from app.services import kill_switch

    if kill_switch.disabled(kill_switch.DEEP_LINK_COUNT_KILL_SWITCH):
        return None
    path, _, query = route.split("#", 1)[0].partition("?")
    if len(path) > 1 and path.endswith("/"):
        path = path[:-1]
    if path not in _COUNTABLE_DEEP_LINK_ROUTES:
        return None
    counter = _DEEP_LINK_COUNTERS.get(path)
    if counter is None:
        return None
    try:
        return await asyncio.wait_for(counter(user_id, query), timeout=_deep_link_count_budget_s())
    except Exception:
        # Dépassement de budget, erreur réseau, service indisponible : la
        # dégradation est le comportement NORMAL — jamais un cas d'erreur
        # (Louis, 15/09/2026). Le lien continue de se proposer sans compte.
        return None


