def _proposal(payload: dict[str, Any]) -> dict[str, Any]:
    """Enveloppe commune des outils d'écriture : une action PRÊTE, pas faite.

    Le `status` est lu par l'orchestrateur (qui la remonte au panneau
    « à valider ») et par le modèle (qui doit annoncer une proposition, pas un
    fait accompli)."""
    return {
        "status": "pending_confirmation",
        "message": (
            "Action préparée, PAS exécutée. Elle attend la validation explicite de "
            "l'utilisateur dans l'interface. Annonce-la comme une proposition."
        ),
        "proposal": payload,
    }


#: #2391.31/.32 — jamais toute la capacité libre : la part RÉSERVÉE, jamais
#: planifiée, avant même que l'énergie déclarée ne la déplace (voir
#: `_FOCUS_PLAN_ENERGY_RATIO_DELTA`, `chat_tools.py`). `0.7` = au plus 70 % du
#: temps réellement libre est proposé ; le reste est la marge (#2391.30).
_FOCUS_PLAN_CAPACITY_RATIO = 0.7

#: #2391.30/.32 — recette prod du 25/09 : trois blocs proposés bord à bord,
#: aucun tampon entre eux ni marge pour l'imprévu — chaque bloc consommait le
#: créneau libre jusqu'à la seconde où finissait le précédent. Entre deux
#: blocs posés dans le MÊME créneau libre, ce tampon s'intercale désormais
#: avant le second ; il ne s'ajoute jamais entre deux créneaux déjà séparés
#: par un rendez-vous existant (l'écart vient alors de l'agenda, pas d'un
#: ajout de l'outil). Il ne compte pas dans `used_minutes` (le budget reste le
#: temps de travail réel) : il fait partie de la marge (#2391.30), seulement
#: répartie entre les blocs plutôt que bloquée en fin de créneau.
_FOCUS_PLAN_BUFFER_MINUTES = 10

#: #2391.21 — la même borne que `focusPlanBlockSchema.duration_minutes`
#: (`packages/contracts/src/schemas/focus-plan.ts`) : un bloc en dehors de
#: cette fourchette ne peut pas être un temps de travail réel.
_FOCUS_PLAN_MIN_BLOCK_MINUTES = 5
_FOCUS_PLAN_MAX_BLOCK_MINUTES = 240

#: GA-318 — même motif que `_CAMPAIGN_MAX_CONTACTS` : les blocs candidats
#: viennent du MODÈLE, jamais d'une recherche, mais une liste écrite par un
#: modèle n'est pas bornée pour autant. Une journée n'a matériellement pas
#: la place pour plus de vingt blocs de cinq minutes — au-delà, `blocks` ET
#: `deferred_blocks` grandiraient sans plafond.
_FOCUS_PLAN_MAX_CANDIDATE_BLOCKS = 20


def _parse_focus_candidates(
    tool_input: dict[str, Any], period: str = "la journée"
) -> tuple[list[dict[str, Any]] | None, dict[str, Any] | None]:
    """Les blocs CANDIDATS d'un plan (journée ou semaine, #2770.55-.62), validés
    une seule fois : `(candidats, None)` ou `(None, {"error": …})`. Jamais un
    bloc sans raison réelle, hors bornes ou d'un type inconnu."""
    raw_blocks = tool_input.get("blocks")
    if not isinstance(raw_blocks, list) or not raw_blocks:
        return None, {"error": f"Il me faut au moins un bloc à proposer pour organiser {period}."}
    # GA-318 — même motif que `prepare_campaign`/`_CAMPAIGN_MAX_CONTACTS` :
    # une liste écrite par le modèle n'est pas bornée pour autant.
    raw_blocks = raw_blocks[:_FOCUS_PLAN_MAX_CANDIDATE_BLOCKS]
    candidates: list[dict[str, Any]] = []
    for raw in raw_blocks:
        if not isinstance(raw, dict):
            return None, {"error": "Un bloc candidat est mal formé."}
        block_type = str(raw.get("type") or "").strip()
        if block_type not in FOCUS_PLAN_BLOCK_TYPES:
            return None, {
                "error": (
                    f"Type de bloc inconnu : {block_type or '(vide)'}. "
                    f"Les types valables sont : {', '.join(FOCUS_PLAN_BLOCK_TYPES)}."
                )
            }
        title = str(raw.get("title") or "").strip()
        if not title:
            return None, {"error": "Chaque bloc a besoin d'un titre."}
        priority_reason = str(raw.get("priority_reason") or "").strip()
        if not priority_reason:
            return None, {"error": "Chaque bloc a besoin d'une vraie priorité qui le justifie — jamais du remplissage."}
        try:
            duration_minutes = int(raw.get("duration_minutes"))
        except (TypeError, ValueError):
            return None, {"error": "La durée estimée d'un bloc doit être un nombre de minutes."}
        if not (_FOCUS_PLAN_MIN_BLOCK_MINUTES <= duration_minutes <= _FOCUS_PLAN_MAX_BLOCK_MINUTES):
            return None, {
                "error": (
                    f"Durée hors bornes ({duration_minutes} min) : entre "
                    f"{_FOCUS_PLAN_MIN_BLOCK_MINUTES} et {_FOCUS_PLAN_MAX_BLOCK_MINUTES} minutes."
                )
            }
        priority = str(raw.get("priority") or "").strip() or None
        if priority is not None and priority not in FOCUS_PLAN_PRIORITIES:
            return None, {"error": f"Priorité inconnue : {priority}."}
        deadline = str(raw.get("deadline") or "").strip() or None
        context = str(raw.get("context") or "").strip() or None
        candidates.append(
            {
                "type": block_type,
                "title": title,
                "duration_minutes": duration_minutes,
                "priority_reason": priority_reason,
                "priority": priority,
                "deadline": deadline,
                "context": context,
            }
        )
        weekday = str(raw.get("deadline_weekday") or "").strip()
        if weekday:
            candidates[-1]["deadline_weekday"] = weekday
        # #2770.35 — l'outil dont le bloc dépend, DÉCLARÉ par Laura ; absent = le bloc ne dépend d'aucun outil.
        requires_tool = str(raw.get("requires_tool") or "").strip()
        if requires_tool:
            if requires_tool not in FOCUS_PLAN_TOOL_FAMILIES:
                return None, {
                    "error": (
                        f"Outil inconnu : {requires_tool}. "
                        f"Les outils valables sont : {', '.join(FOCUS_PLAN_TOOL_FAMILIES)}."
                    )
                }
            candidates[-1]["requires_tool"] = requires_tool
    return candidates, None


def _focus_tools_split(
    candidates: list[dict[str, Any]], families: tuple[str, ...] | None
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """#2770.35 — pur. Écarte les blocs qui s'appuient sur un outil NON branché (`outil_non_branche`), jamais
    placés ; familles inconnues (`None`) ⇒ aucun écart, comportement d'avant."""
    if families is None:
        return candidates, []
    kept: list[dict[str, Any]] = []
    deferred: list[dict[str, Any]] = []
    for block in candidates:
        required = block.get("requires_tool") or _FOCUS_BLOCK_DEFAULT_TOOL.get(block["type"])
        if required and required not in families:
            deferred.append({"type": block["type"], "title": block["title"], "reason": "outil_non_branche"})
        else:
            kept.append(block)
    return kept, deferred


def _mailbox_unplaced(
    candidates: list[dict[str, Any]], families: tuple[str, ...] | None
) -> list[dict[str, Any]]:
    """#4293.7 (#2770.2) — pur. Sans messagerie branchée, la journée n'a pas pu placer le traitement de la boîte :
    elle le NOMME (« Non placé », raison `outil_non_branche`, la clé existante) au lieu de paraître complète.
    Familles inconnues (`None`) ⇒ rien n'est affirmé ; un bloc mail déjà écarté par Laura n'est pas doublé."""
    if families is None or "email" in families:
        return []
    # Intégration XIV — un bloc qui suppose la messagerie PAR NATURE (`_FOCUS_BLOCK_DEFAULT_TOOL`, ex. des relances)
    # est déjà nommé « Non placé » par `_focus_tools_split` : il ne se double pas d'un « Traiter la messagerie ».
    if any(
        (block.get("requires_tool") or _FOCUS_BLOCK_DEFAULT_TOOL.get(block["type"])) == "email" for block in candidates
    ):
        return []
    return [{"type": "follow_ups", "title": "Traiter la messagerie", "reason": "outil_non_branche"}]


def _focus_connected_tools(families: tuple[str, ...] | None) -> list[str] | None:
    """#2770.35 — les familles branchées que le plan NOMME, dans l'ordre stable du contrat. `None` = non lues."""
    if families is None:
        return None
    return [family for family in FOCUS_PLAN_TOOL_FAMILIES if family in families]


def _team_policy_windows(raw: Any) -> list[dict[str, int]]:
    windows: list[dict[str, int]] = []
    for window in raw if isinstance(raw, list) else []:
        if not isinstance(window, dict):
            continue
        start, end = window.get("startMinute"), window.get("endMinute")
        if not (isinstance(start, int) and isinstance(end, int) and 0 <= start < end <= 1440):
            continue
        entry: dict[str, Any] = {"start_minute": start, "end_minute": end}
        raw_days = window.get("weekdays")
        if raw_days is not None:
            # #2770.37 — des jours illisibles écartent la plage : jamais élargie à « chaque jour » en silence.
            days = (
                sorted(set(raw_days))
                if isinstance(raw_days, list) and raw_days and all(type(d) is int and 1 <= d <= 7 for d in raw_days)
                else None
            )
            if days is None:
                continue
            entry["weekdays"] = days
        windows.append(entry)
    return windows


def _team_policy_for_day(policy: dict[str, Any] | None, day: date) -> dict[str, Any] | None:
    """#2770.37 — pur. La politique réduite aux plages qui valent CE jour (ISO), sans leurs `weekdays`."""
    if not policy:
        return policy
    weekday = day.isoweekday()

    def today(windows: list[dict[str, Any]]) -> list[dict[str, int]]:
        return [
            {"start_minute": w["start_minute"], "end_minute": w["end_minute"]}
            for w in windows
            if weekday in w.get("weekdays", range(1, 8))
        ]

    return {
        **policy,
        "prospecting_windows": today(policy.get("prospecting_windows") or []),
        "forbidden_windows": today(policy.get("forbidden_windows") or []),
    }


def _team_policy_of(read: dict[str, Any] | None) -> tuple[bool, dict[str, Any] | None]:
    """#2770.37 — pur. `(lue, politique)` : pont muet ⇒ `(False, None)` (la source reste NOMMÉE non lue) ;
    rien saisi ⇒ `(True, None)` (« aucune politique d'équipe saisie ») ; sinon la politique, en snake_case."""
    if not isinstance(read, dict):
        return False, None
    raw = read.get("policy")
    if not isinstance(raw, dict):
        return True, None
    max_meetings = raw.get("maxMeetingsPerDay")
    call_target = raw.get("dailyCallTarget")
    policy = {
        "prospecting_windows": _team_policy_windows(raw.get("prospectingWindows")),
        "forbidden_windows": _team_policy_windows(raw.get("forbiddenWindows")),
        "max_meetings_per_day": max_meetings if isinstance(max_meetings, int) and max_meetings > 0 else None,
        "daily_call_target": call_target if isinstance(call_target, int) and call_target > 0 else None,
    }
    if not any(policy.values()):
        return True, None
    return True, policy


def _focus_unread_sources(*, tools_read: bool, policy_read: bool, role_read: bool = False) -> list[str]:
    """#2770.35/.37 — ce que le plan n'a PAS lu, toujours nommé. #5 (recette 13/10) — le rôle y reste tant qu'AUCUN
    rôle n'est déclaré : « Non pris en compte : ton rôle » alors que le Rôle métier est réglé était faux."""
    read = {"tools": tools_read, "team_policy": policy_read, "role": role_read}
    return [source for source in FOCUS_PLAN_UNREAD_SOURCES if not read.get(source, False)]


def _apply_team_policy_windows(
    free_slots: list[dict[str, Any]], day: date, zone: tzinfo | None, policy: dict[str, Any] | None
) -> list[dict[str, Any]]:
    """#2770.37 — pur. Retire des créneaux libres les CRÉNEAUX INTERDITS par la politique d'équipe, et marque
    `prospecting` les morceaux qui tombent dans une plage de prospection protégée (seuls les blocs de
    prospection y seront placés). Heures lues dans le fuseau applicable du jour ; un morceau plus court que
    le plancher d'un bloc disparaît. Aucune politique ⇒ créneaux rendus tels quels."""
    policy = _team_policy_for_day(policy, day)
    if not policy or not (policy.get("forbidden_windows") or policy.get("prospecting_windows")):
        return free_slots
    midnight = datetime(day.year, day.month, day.day, tzinfo=zone)

    def bounds(windows: list[dict[str, int]]) -> list[tuple[datetime, datetime]]:
        return [
            (midnight + timedelta(minutes=w["start_minute"]), midnight + timedelta(minutes=w["end_minute"]))
            for w in windows
        ]

    forbidden = bounds(policy.get("forbidden_windows") or [])
    prospecting = bounds(policy.get("prospecting_windows") or [])
    out: list[dict[str, Any]] = []
    for slot in free_slots:
        try:
            start = datetime.fromisoformat(str(slot.get("start") or ""))
            end = datetime.fromisoformat(str(slot.get("end") or ""))
        except ValueError:
            continue
        pieces = [(start, end)]
        for f_start, f_end in forbidden:
            f_start, f_end = f_start.astimezone(start.tzinfo), f_end.astimezone(start.tzinfo)
            pieces = [
                part
                for p_start, p_end in pieces
                for part in ((p_start, min(p_end, f_start)), (max(p_start, f_end), p_end))
                if part[1] > part[0]
            ]
        cuts = sorted({moment.astimezone(start.tzinfo) for window in prospecting for moment in window})
        for p_start, p_end in pieces:
            edges = [p_start, *[cut for cut in cuts if p_start < cut < p_end], p_end]
            for piece_start, piece_end in zip(edges, edges[1:], strict=False):
                minutes = int((piece_end - piece_start).total_seconds() // 60)
                if minutes < _FOCUS_PLAN_MIN_BLOCK_MINUTES:
                    continue
                middle = piece_start + (piece_end - piece_start) / 2
                reserved = any(w_start <= middle < w_end for w_start, w_end in prospecting)
                piece = {"start": piece_start.isoformat(), "end": piece_end.isoformat(), "minutes": minutes}
                if reserved:
                    piece["prospecting"] = True
                out.append(piece)
    return out


def _attach_plan_inputs(
    plan: dict[str, Any],
    *,
    families: tuple[str, ...] | None,
    policy_read: bool,
    policy: dict[str, Any] | None,
    role_read: bool = False,
) -> None:
    """#2770.35/.37 — ce que le plan a LU, posé une fois sur la carte (jour, ou semaine — jamais jour par jour) :
    les outils branchés nommés, la politique d'équipe (`None` = lue, rien saisi), et ce qui reste non lu."""
    connected = _focus_connected_tools(families)
    if connected is not None:
        plan["connected_tools"] = connected
    if policy_read:
        plan["team_policy"] = policy
    plan["unread_sources"] = _focus_unread_sources(
        tools_read=connected is not None, policy_read=policy_read, role_read=role_read
    )


def _team_policy_notes(
    policy: dict[str, Any] | None, candidates: list[dict[str, Any]], meetings_count: int | None
) -> list[str]:
    """#2770.37 — ce que Laura DIT de la politique d'équipe (la carte la liste déjà). Jamais un chiffre lu ailleurs
    que dans la politique saisie ou l'agenda réel."""
    if not policy:
        return []
    notes = [
        "Une politique d'équipe est appliquée (la carte la liste) : explique-la en une phrase "
        "(« politique d'équipe : … »), sans la recopier en entier."
    ]
    cap = policy.get("max_meetings_per_day")
    if cap is not None and meetings_count is not None and meetings_count >= cap:
        notes.append(
            f"La politique d'équipe fixe {cap} réunions maximum par jour et l'agenda en compte déjà "
            f"{meetings_count} ce jour-là : dis-le, et ne propose pas d'en ajouter."
        )
    target = policy.get("daily_call_target")
    if target is not None and not any(block["type"] == "call_session" for block in candidates):
        notes.append(
            f"La politique d'équipe fixe un objectif de {target} appels par jour et aucune session d'appels "
            "n'est proposée : dis-le et propose d'en ajouter une."
        )
    return notes


#: L'ordre des candidats à placer : priorité haute d'abord, puis une échéance
#: connue avant une échéance inconnue (#2391.27 — « traite les deadlines
#: réelles »), puis le TYPE du bloc (#2391.28/.29, #2770.40/.41 — regroupe les
#: tâches similaires pour limiter les changements de contexte), puis l'ORDRE
#: d'origine (stable) — jamais un ordre recalculé au hasard entre deux tours.
_FOCUS_PLAN_PRIORITY_RANK: dict[str, int] = {"high": 0, "normal": 1, "low": 2}


#: #2770 (recette prod Y20) — « avant jeudi » : le NOM du jour, résolu par l'outil. Une date calculée par le
#: modèle visait le lundi 5 octobre un samedi 3 ; l'outil la dérive de SA date du jour, jamais du modèle.
_WEEKDAY_INDEX: dict[str, int] = {
    **{
        name: index
        for index, name in enumerate(("lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"))
    },
    **{
        name: index
        for index, name in enumerate(("monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"))
    },
}


def _next_weekday_after(name: str, today: Any) -> Any:
    """Le prochain jour de ce nom, STRICTEMENT après `today` (dit un jeudi, « avant jeudi » vise le jeudi
    suivant, jamais aujourd'hui) ; `None` si le nom n'est pas un jour de la semaine."""
    index = _WEEKDAY_INDEX.get(str(name or "").strip().lower())
    if index is None:
        return None
    return today + timedelta(days=(index - today.weekday() - 1) % 7 + 1)


def _monday_of(day: Any) -> Any:
    return day - timedelta(days=day.weekday())


def _build_weekly_plan(
    *,
    week_start: str,
    time_zone: str | None,
    energy: str | None,
    candidates: list[dict[str, Any]],
    free_slots_by_day: list[tuple[str, list[dict[str, Any]]]],
    reserve_minutes: int = 0,
    role: str | None = None,
) -> dict[str, Any]:
    """Pur — aucune I/O. #2770.55-.62 : répartit les blocs candidats sur les jours
    de la semaine, CHAQUE jour passant par `_build_focus_plan` (le moteur du plan
    de journée : créneaux libres seulement, jamais toute la capacité, tampons).

    Un bloc ne va jamais APRÈS son échéance (le jour d'échéance reste permis) ;
    ce qui n'a trouvé aucun jour part dans `deferred_blocks`. Un jour sans bloc
    placé ne fait AUCUNE ligne. `margin_minutes` = le libre de la semaine moins
    ce qui est planifié : jamais négatif, jamais « tout plein ».
    """
    remaining = list(candidates)
    days: list[dict[str, Any]] = []
    total_free = 0
    used = 0
    free_days: list[str] = []
    # Le plus gros bloc qu'un jour libre PEUT accueillir à vide (créneau le plus long, plafonné au budget).
    day_capacities: dict[str, int] = {}
    for day_iso, slots in free_slots_by_day:
        day_free = sum(int(slot.get("minutes") or 0) for slot in slots)
        total_free += day_free
        if day_free > 0:
            free_days.append(day_iso)
            longest = max(int(slot.get("minutes") or 0) for slot in slots)
            day_capacities[day_iso] = min(longest, _focus_budget_minutes(day_free, energy, reserve_minutes))
        eligible = [block for block in remaining if not block.get("deadline") or str(block["deadline"]) >= day_iso]
        if not eligible or day_free <= 0:
            continue
        day_plan = _build_focus_plan(
            plan_date=day_iso,
            time_zone=time_zone,
            energy=energy,
            candidates=eligible,
            free_slots=slots,
            reserve_minutes=reserve_minutes,
            role=role,
        )
        for placed in day_plan["blocks"]:
            for index, block in enumerate(remaining):
                if (block["type"], block["title"], block["duration_minutes"]) == (
                    placed["type"],
                    placed["title"],
                    placed["duration_minutes"],
                ):
                    del remaining[index]
                    break
            used += int(placed["duration_minutes"])
        if day_plan["blocks"]:
            # Les reports d'un jour retombent sur les jours SUIVANTS : seul ce qui
            # reste à la fin de la semaine est dit, au niveau de la semaine.
            day_plan["deferred_blocks"] = []
            days.append(day_plan)
    return {
        "week_start": week_start,
        "time_zone": time_zone,
        "energy": energy,
        "days": days,
        "deferred_blocks": [
            {
                "type": block["type"],
                "title": block["title"],
                "reason": _weekly_deferral_reason(block, day_capacities),
            }
            for block in remaining
        ],
        "margin_minutes": max(0, total_free - used),
    }


def _weekly_deferral_reason(block: dict[str, Any], day_capacities: dict[str, int]) -> str:
    """#2770 (recette prod 02/10) — POURQUOI un bloc n'est pas placé de la semaine. Trois causes, jamais
    mêlées, pour qu'aucune ne contredise « N h laissées libres » :

    - ``echeance_depassee`` : l'échéance précède TOUS les jours libres (les heures libres tombent après) ;
    - ``bloc_trop_long`` : aucun jour permis ne peut l'accueillir, même vide (créneau le plus long ou
      budget du jour plus court que le bloc) — la semaine peut être entièrement libre, le bloc ne tient nulle part ;
    - ``capacite_atteinte`` : il tiendrait, mais d'autres blocs ont pris la place.
    """
    deadline = block.get("deadline")
    allowed = {day: cap for day, cap in day_capacities.items() if not deadline or day <= str(deadline)}
    if not allowed:
        return "echeance_depassee"
    if int(block["duration_minutes"]) > max(allowed.values()):
        return "bloc_trop_long"
    return "capacite_atteinte"


#: #5 (recette 13/10) — c76 : le rôle change l'ORDRE, jamais le CONTENU. Les types de bloc que chaque lecture de
#: poste passe en tête À PRIORITÉ ET ÉCHÉANCE ÉGALES (les deux critères qui restent autoritaires). Un rôle sans
#: lecture dédiée ne réordonne rien — jamais une supposition.
_FOCUS_ROLE_FIRST: dict[str, tuple[str, ...]] = {
    "sales": ("call_session", "meeting_prep", "account_research", "follow_ups"),
    "manager": ("pipeline_review", "manager_review", "consultant_followup"),
    "recruiter": ("matching", "consultant_followup"),
}


def _focus_role_reading(role: str | None) -> str | None:
    text = unicodedata.normalize("NFD", (role or "").lower())
    text = "".join(char for char in text if unicodedata.category(char) != "Mn")
    if any(word in text for word in ("recrut", "staffing")):
        return "recruiter"
    if any(word in text for word in ("business developer", "commercial", "ingenieur d'affaires", "ingenieur d affaires")):
        # « Directeur commercial » est un poste de pilotage, pas de terrain.
        return "manager" if "directeur" in text else "sales"
    if any(word in text for word in ("directeur", "business manager", "manager")):
        return "manager"
    return None


def _focus_plan_sort_key(
    indexed: tuple[int, dict[str, Any]], role: str | None = None
) -> tuple[int, int, str, int, str, int]:
    index, block = indexed
    first = _FOCUS_ROLE_FIRST.get(_focus_role_reading(role) or "", ())
    role_rank = first.index(str(block.get("type"))) if str(block.get("type")) in first else len(first)
    priority = block.get("priority")
    rank = _FOCUS_PLAN_PRIORITY_RANK.get(str(priority), 1)
    deadline = str(block.get("deadline") or "")
    # #2391.28/.29 (#2770.40/.41) — « regroupe les tâches similaires » / « limite
    # les changements de contexte » : à priorité et échéance égales (les deux
    # critères qui restent AUTORITAIRES, jamais dépassés), le TYPE du bloc
    # départage avant l'ordre brut donné par Laura — deux blocs du même type
    # atterrissent adjacents plutôt qu'en alternance.
    block_type = str(block.get("type") or "")
    # Une échéance CONNUE passe avant une échéance inconnue (`""` trie après
    # toute date AAAA-MM-JJ) — jamais l'inverse.
    return (rank, 0 if deadline else 1, deadline, role_rank, block_type, index)


#: #2770.28 — copiés de `AGENDA_CAPACITY_MINUTES_PER_DOSSIER` / `AGENDA_CAPACITY_RESERVE_SLOTS`
#: (`apps/web/src/features/briefing/agenda-compact.ts`), même raison de duplication que
#: `FOCUS_PLAN_BLOCK_TYPES` : le défaut d'un champ NON réglé quand l'autre l'est (« champ par champ »).
_AGENDA_MINUTES_PER_DOSSIER_DEFAULT = 45
_AGENDA_RESERVE_SLOTS_DEFAULT = 1


def _focus_plan_reserve_minutes(preferences: dict[str, Any] | None) -> int:
    """#2770.28 — la réserve PERSONNELLE (durée d'un dossier × créneaux de réserve, `agenda-preferences.ts`),
    en minutes. Rien réglé (`{}`) ou pont en panne (`None`) ⇒ 0 : plan inchangé, jamais une réserve devinée."""
    if not preferences:
        return 0
    minutes = preferences.get("dossierDurationMinutes")
    slots = preferences.get("reserveSlots")
    minutes = minutes if isinstance(minutes, int) else _AGENDA_MINUTES_PER_DOSSIER_DEFAULT
    slots = slots if isinstance(slots, int) else _AGENDA_RESERVE_SLOTS_DEFAULT
    return max(0, minutes * slots)


def _focus_budget_minutes(total_free_minutes: int, energy: str | None, reserve_minutes: int = 0) -> int:
    """Le budget d'une journée : la part du libre qu'on accepte de planifier (jamais tout), selon l'énergie.

    #2770.28 — la réserve personnelle s'AJOUTE au plancher du ratio, jamais à sa place : le plus petit des
    deux budgets gagne, une réserve réglée plus petite que celle du ratio ne le desserre pas."""
    ratio = _FOCUS_PLAN_CAPACITY_RATIO + _FOCUS_PLAN_ENERGY_RATIO_DELTA.get(energy or "normal", 0.0)
    ratio_budget = int(total_free_minutes * max(0.1, min(0.95, ratio)))
    return max(0, min(ratio_budget, total_free_minutes - reserve_minutes))


def _build_focus_plan(
    *,
    plan_date: str,
    time_zone: str | None,
    energy: str | None,
    candidates: list[dict[str, Any]],
    free_slots: list[dict[str, Any]],
    reserve_minutes: int = 0,
    role: str | None = None,
) -> dict[str, Any]:
    """Pur — aucune I/O. Place chaque bloc CANDIDAT dans un créneau RÉELLEMENT

    libre (`free_slots`, rendu par `bellum_api.find_free_slots`, même calcul
    que l'outil `find_free_slots`), dans l'ordre de `_focus_plan_sort_key`, sans
    jamais dépasser le budget de capacité (#2391.31). Le reste part dans
    `deferred_blocks` (#2391.33) ; ce qui n'a pas été consommé du budget est la
    marge (#2391.30/.32), en partie répartie en tampons entre deux blocs
    consécutifs du même créneau (`_FOCUS_PLAN_BUFFER_MINUTES`) plutôt que
    laissée entière en fin de journée.

    Un bloc placé automatiquement n'est JAMAIS en collision : il n'est posé que
    dans un créneau que `free_slots` a déjà rendu libre (#2391.26 — protège les
    engagements déjà pris).
    """
    total_free_minutes = sum(int(slot.get("minutes") or 0) for slot in free_slots)
    budget_minutes = _focus_budget_minutes(total_free_minutes, energy, reserve_minutes)
    # #2770 (recette prod 08/10) — « Aucun bloc placé — pas assez de temps libre »
    # ET « N h laissées libres » dans la même carte : CE bloc, seul sur une journée
    # VIDE, tiendrait-il ? Même calcul que `_weekly_deferral_reason` (jour le plus
    # long, plafonné au budget) — si NON, c'est `bloc_trop_long` (la marge affichée
    # ne contredit personne) ; si OUI, c'est `capacite_atteinte` SEULEMENT si
    # d'autres blocs ont réellement pris la place.
    longest_free_minutes = max((int(slot.get("minutes") or 0) for slot in free_slots), default=0)
    day_capacity_minutes = min(longest_free_minutes, budget_minutes)

    # Copie mutable des créneaux, triés par début : chaque placement CONSOMME
    # le créneau qu'il occupe, jamais le même minutage rendu deux fois.
    # `has_block` distingue un créneau encore vierge (premier bloc posé bord à
    # bord avec son début réel, jamais retardé) d'un créneau qui porte déjà un
    # bloc (le suivant y est précédé d'un tampon, #2391.30/.32).
    cursors = [
        {
            "start": str(slot.get("start") or ""),
            "end": str(slot.get("end") or ""),
            "minutes": int(slot.get("minutes") or 0),
            "has_block": False,
            # #2770.37 — plage de prospection protégée par la politique d'équipe.
            "prospecting": bool(slot.get("prospecting")),
        }
        for slot in sorted(free_slots, key=lambda slot: str(slot.get("start") or ""))
    ]

    placed: list[dict[str, Any]] = []
    deferred: list[dict[str, Any]] = []
    used_minutes = 0

    order = sorted(enumerate(candidates), key=lambda indexed: _focus_plan_sort_key(indexed, role))
    for _index, block in order:
        duration = block["duration_minutes"]
        deferred_reason = "bloc_trop_long" if duration > day_capacity_minutes else "capacite_atteinte"
        if used_minutes + duration > budget_minutes:
            deferred.append({"type": block["type"], "title": block["title"], "reason": deferred_reason})
            continue
        cursor = next(
            (
                c
                for c in cursors
                if c["minutes"] >= duration + (_FOCUS_PLAN_BUFFER_MINUTES if c["has_block"] else 0)
                and (not c["prospecting"] or block["type"] in _TEAM_POLICY_PROSPECTING_BLOCK_TYPES)
            ),
            None,
        )
        if cursor is None:
            deferred.append({"type": block["type"], "title": block["title"], "reason": deferred_reason})
            continue
        if cursor["has_block"]:
            buffered_start = datetime.fromisoformat(cursor["start"]) + timedelta(minutes=_FOCUS_PLAN_BUFFER_MINUTES)
            cursor["start"] = buffered_start.isoformat()
            cursor["minutes"] -= _FOCUS_PLAN_BUFFER_MINUTES
        start = cursor["start"]
        start_dt = datetime.fromisoformat(start)
        end_dt = start_dt + timedelta(minutes=duration)
        end = end_dt.isoformat()
        # Consomme le créneau : ce qu'il en reste commence où ce bloc finit.
        cursor["start"] = end
        cursor["minutes"] -= duration
        cursor["has_block"] = True
        used_minutes += duration
        placed.append(
            {
                "type": block["type"],
                "title": block["title"],
                "duration_minutes": duration,
                "start_iso": start,
                "end_iso": end,
                "priority_reason": block["priority_reason"],
                "priority": block.get("priority"),
                "deadline": block.get("deadline"),
                "context": block.get("context"),
                "collision": None,
            }
        )

    margin_minutes = max(0, total_free_minutes - used_minutes)
    # La carte affiche une JOURNÉE, donc un ordre chronologique — jamais
    # l'ordre de priorité qui a servi à PLACER les blocs.
    placed.sort(key=lambda block: str(block["start_iso"] or ""))
    return {
        "date": plan_date,
        "time_zone": time_zone,
        "energy": energy,
        "blocks": placed,
        "deferred_blocks": deferred,
        "margin_minutes": margin_minutes,
    }


# D1 — décision Louis 14/09/2026 : proposer une analyse = une carte à valider, le clic est la décision
#
# Mesuré en prod le 14/09 à 15:56 : « propose seulement » rendait de la PROSE —
# « Proposition d'analyse — THALES », deux options, 8 crédits, statut du compte.
# Tout y était sauf le geste. La carte porte les mêmes faits et un bouton.
#
# ⚠️ RENVERSÉE le 22/09/2026 — décision Louis, #2723 (call bêta, Loïc Inacio) :
# « Laura ne demande plus si on doit consommer des crédits et tout […] Si un
# utilisateur demande quelque chose, Laura le fait, point. » D1 ne disparaît
# pas — elle se lit ci-dessus — mais `execute_chat_tool` n'appelle PLUS
# `_proposal()` sur son résultat : plus de `status: pending_confirmation`, plus
# de bouton à cliquer. Le filet passe en AVAL (`c78_remboursement_credits_
# nocturne`, remboursement nocturne sans geste humain), plus en amont (un
# clic) — voir `c84_analyse_recherche_enrichissement_partent_sans_carte`
# (`packages/contracts/src/schemas/doctrine-registry.ts`). Cette fonction reste
# le calcul honnête des CHIFFRES ci-dessous (GA-18/GA-19) : ce n'est plus une
# carte, mais le modèle en a toujours besoin pour annoncer un coût vrai avant
# d'enchaîner sur `start_account_analysis`.
#
# ⚠️ Les chiffres viennent du PONT (`/internal/copilot/analysis/plan`), jamais du
# modèle : un coût écrit par un LLM n'est pas un prix. Et un chiffre que le pont
# ne dit pas est ABSENT, jamais `0` — « non mesuré » n'est pas « mesuré à zéro »
# (GA-18/GA-19). L'écran, lui, n'a aucune soustraction à faire : le solde après
# se calcule ici, sur les deux chiffres du pont.
_SCOPE_REQUIRED_INSTRUCTION = (
    "Ce groupe est TROP LARGE pour une seule analyse : dis-le en une phrase, puis demande sur "
    "quelle ENTITÉ, quel PROGRAMME ou quelle DIRECTION cadrer, en t'appuyant sur "
    "`scope_guardrail.reason`. Les deux ou trois périmètres possibles passent par "
    "`offer_reply_options` dans ce même tour, et ton texte ne les énumère pas : ils sont déjà "
    "sous ta phrase, les répéter en texte ou en puces est une redite. Rien n'est "
    "débité avant ce choix : n'annonce aucun coût, n'appelle PAS `start_account_analysis`. Dès que "
    "l'utilisateur nomme le périmètre, rappelle `plan_account_analysis` avec ce périmètre dans "
    "`company` (« Michelin — direction Data/IA France »)."
)

_SCOPE_REQUIRED_EXISTING_SUFFIX = (
    " Un dossier existe DÉJÀ sur ce groupe (`analysed_at`) sans périmètre précisé : dis-le en une "
    "phrase avec sa date avant la question — relancer une analyse payante se décide sur un périmètre."
)


# #3218 (recette NB 10/10) — acquiescement court après la question de périmètre.
_SCOPE_ACCEPTED_INSTRUCTION = (
    "La question de périmètre a DÉJÀ été posée dans ce fil et la personne vient d'acquiescer : "
    "ne la repose PAS. Le périmètre retenu est le premier périmètre que tu as proposé (le périmètre par défaut). "
    "Ne rappelle pas `plan_account_analysis` : appelle IMMÉDIATEMENT `start_account_analysis` dans "
    "ce même tour, avec le `plan_token` et le `company` de CETTE réponse, puis dis le périmètre "
    "retenu, le coût et que l'analyse est LANCÉE."
)
_SCOPE_QUESTION_RE = re.compile(r"périmètre|entité|direction|programme", re.IGNORECASE)
_SHORT_ACCEPTANCE_RE = re.compile(
    r"^\W*(?:ok(?:ay)?|oui|yes|go|d'accord|dacc|vas-?y|allez|fais(?:-le)?|lance(?:-la|-le|z-la)?|c'est parti|parfait|exact(?:ement)?|carrément)\b",
    re.IGNORECASE,
)


def _scope_question_already_answered_by_acceptance() -> bool:
    thread = current_turn_thread()
    if thread is None:
        return False
    message, history = thread
    if len(message.split()) > 6 or not _SHORT_ACCEPTANCE_RE.match(message.strip()):
        return False
    last_assistant = next(
        (str(turn.get("content") or "") for turn in reversed(history) if turn.get("role") == "assistant"),
        "",
    )
    # #3218 (RAT, recette NF 10/10) — plus d'exigence de « ? » : le texte persisté du tour
    # précédent est celui RÉPARÉ par le vérificateur (journal 19:52:22, REPAIR), et les pistes
    # de périmètre passent par `offer_reply_options` — la question peut ne pas finir par « ? ».
    return bool(_SCOPE_QUESTION_RE.search(last_assistant))


def scope_question_answered_by_acceptance() -> bool:
    """#3218 (RAT) — lu par l'orchestrateur pour FORCER l'outil : en prod, sur « lance-la »,
    le modèle n'appelait AUCUN outil (`tools_called: ()`), la branche ci-dessus ne tournait jamais.

    Plus strict que la lecture de l'outil, parce que FORCER un outil est un geste : le tour
    précédent de la personne demandait une ANALYSE (« Lance maintenant l'analyse… »). Un « oui »
    à « veux-tu un message pour la direction ? » ne force rien."""
    if not _scope_question_already_answered_by_acceptance():
        return False
    thread = current_turn_thread()
    history = thread[1] if thread is not None else ()
    last_user = next(
        (str(turn.get("content") or "") for turn in reversed(history) if turn.get("role") == "user"),
        "",
    )
    return bool(re.search(r"analys", last_user, re.IGNORECASE))


# #3218 — consigne quand le mode Approfondi est posé sur un dossier existant.
_DEEPEN_EXISTING_INSTRUCTION = (
    "MODE APPROFONDI sur un dossier DÉJÀ analysé (`analysed_at`, à dire en une phrase avec sa "
    "date) : la personne a choisi d'approfondir, tu ne lui redemandes PAS l'entité. Enchaîne tout "
    "de suite avec `start_account_analysis` (jeton et coût de cette réponse) sur le nom du dossier. "
    "Seule une ambiguïté RÉELLE entre entités distinctes se pose, et alors uniquement par "
    "`offer_reply_options` (2 ou 3 entités cliquables, chacune relance directement), jamais par "
    "une question ouverte."
)


def _analysis_card(plan: dict[str, Any], *, company: str, reason: str = "") -> dict[str, Any]:
    account = plan.get("account") if isinstance(plan.get("account"), dict) else None
    payload: dict[str, Any] = {
        "action": "start_account_analysis",
        # Le nom CANONIQUE du dossier existant prime sur la graphie tapée dans la
        # conversation : c'est celui que l'écran Comptes affiche.
        "company": str((account or {}).get("companyName") or company).strip() or company,
        "account_id": (account or {}).get("id"),
        # « déjà analysé le <date> » ou « jamais analysé » — jamais une date devinée.
        "analysed_at": (account or {}).get("analysedAt"),
        # #2148.11 — la PROVENANCE, DANS L'ESPACE : le prénom du collègue qui a
        # produit ce dossier réutilisé, jamais soi-même, jamais deviné (le pont
        # le rend déjà `null` dans ces deux cas — voir
        # `CopilotBridgeController.analysisPlan`). Jamais une lecture
        # cross-workspace : `agent_docs/doctrine.md:35-36`, GA-43.
        "analysed_by_name": (account or {}).get("analysedByName"),
        "plan_token": plan.get("planToken"),
        "preset": plan.get("preset"),
    }
    # #4464 — crédits implicites : ni coût ni solde sur la carte d'analyse (le pont ne les émet plus).
    # #1957.3 — le nombre de sources/objets visés, sur la MÊME carte que le
    # coût. Le pont ne l'émet que mesuré (contacts déjà en portefeuille d'un
    # compte CONNU) — un `0` ou une absence ne posent jamais la clé : « non
    # mesuré » n'est pas « mesuré à zéro » (GA-18/GA-19).
    objects_count = plan.get("objectsCount")
    if isinstance(objects_count, (int, float)) and not isinstance(objects_count, bool) and objects_count > 0:
        payload["objects_count"] = int(objects_count)
    # #2263.1 — « réutiliser tout ce que Bellum sait avant une analyse
    # payante » : le pont agrège désormais le CRM et Market Memory dans
    # `knownFrom`, en plus du cache d'analyse (`account` ci-dessus). Relayé
    # tel quel — jamais deviné, jamais une liste vide (GA-18/GA-19).
    known_from = plan.get("knownFrom")
    if isinstance(known_from, list) and known_from:
        payload["known_from"] = list(known_from)
    # #3260.8/.9 (BEL-SC-231) — « Analyse Société Générale », sans plus de
    # précision, ne part jamais en silence sur le groupe entier quand le
    # registre classe l'entité GRANDE ENTREPRISE. Relayé tel quel, jamais
    # deviné ici : un `scopeGuardrail` absent ne pose aucune clé (GA-18/GA-19).
    # Ne BLOQUE rien (`c84_analyse_recherche_enrichissement_partent_sans_carte`
    # reste en vigueur) : c'est au MODÈLE de le nommer dans la même phrase que
    # le coût, jamais une carte à valider.
    scope_guardrail = plan.get("scopeGuardrail")
    if isinstance(scope_guardrail, dict):
        suggested = scope_guardrail.get("suggestedScopeMode")
        reason_text = scope_guardrail.get("reason")
        if isinstance(suggested, str) and suggested and isinstance(reason_text, str) and reason_text:
            payload["scope_guardrail"] = {"suggested_scope_mode": suggested, "reason": reason_text}
            # #3218 (lot RBJ) — retenu pour que `start_account_analysis` le transmette au run si la
            # personne acquiesce à la question de périmètre (le modèle ne le nomme pas à coup sûr).
            if suggested in _ANALYSIS_SCOPE_MODES:
                note_planned_scope_mode(suggested)
            # #3434 (recette prod 02/10, « Analyse Michelin. ») — un groupe trop
            # large, jamais analysé, ne part pas : le prompt le disait déjà
            # (`_BLOCK_ANALYSIS_SCOPE`) et le modèle l'ignorait. La règle vit donc
            # dans la FORME du chemin : ni jeton, ni coût à annoncer — seulement la
            # question de périmètre, qui CHANGE réellement l'analyse (ce que
            # c84 autorise déjà de poser). Un périmètre nommé relance la
            # préparation sur ce nom et rend, lui, jeton et coût. Un dossier déjà
            # analysé porte son périmètre : pas de question (le pont n'émet de
            # garde-fou que sur le chemin froid).
            #
            # #3434.3 (recette prod 03/10) — la question vaut AUSSI pour un dossier
            # déjà analysé SANS périmètre : le pont n'émet le garde-fou sur un
            # dossier existant que s'il porte le groupe entier (ou aucun run
            # lisible) ; un dossier déjà cadré n'a pas de garde-fou. Le dossier
            # existant reste DIT (`analysed_at`), la question passe avant l'offre.
            # #3218 (recette Z7 05/10) — le mode « Approfondi » EST la décision de
            # la personne : sur un dossier DÉJÀ analysé, on garde jeton et coût et
            # on lance, au lieu de redemander l'entité (la question de périmètre
            # reste pour un groupe jamais analysé et pour les autres modes).
            if account is not None and current_requested_mode() == "approfondi":
                payload["instruction"] = _DEEPEN_EXISTING_INSTRUCTION
                if reason.strip():
                    payload["reason"] = reason.strip()
                return payload
            # #3218 (recette NB 10/10) — « lance-la » après la question de périmètre :
            # elle est DÉJÀ posée dans ce fil, l'acquiescement vaut le premier
            # périmètre proposé. L'outil ne la repose pas (le prompt le disait, le
            # modèle rappelait l'outil et retombait sur `scope_required`).
            # RAN #3218 (recette ND 10/10, prod) — RAL avait RETIRÉ le jeton et le
            # coût ici, et la consigne demandait un SECOND appel de préparation
            # avant le lancement : le modèle s'arrêtait là (« j'ai seulement préparé
            # le périmètre »). L'acquiescement garde donc jeton et coût : un seul
            # geste reste à faire, `start_account_analysis`.
            if _scope_question_already_answered_by_acceptance():
                payload["status"] = "scope_accepted_default"
                payload["instruction"] = _SCOPE_ACCEPTED_INSTRUCTION
            else:
                for key in ("plan_token",):
                    payload.pop(key, None)
                payload["status"] = "scope_required"
                payload["scope_required"] = True
                payload["instruction"] = _SCOPE_REQUIRED_INSTRUCTION + (
                    _SCOPE_REQUIRED_EXISTING_SUFFIX if account is not None else ""
                )
    if reason.strip():
        payload["reason"] = reason.strip()
    return payload


# #2892 (27/09) — recette prod, /chat : un refus du pont NestJS
# (`copilot-bridge.controller.ts`, ex. `analysisStart`) porte parfois un CODE
# technique dans `error` (`plan_required`, `analysis_forbidden`,
# `records_write_forbidden`, …) et la phrase à DIRE dans `message` — « le
# message est lu par le modèle », dit le contrôleur lui-même. Vu en recette :
# le code brut, exposé texte pour texte dans la réponse (« erreur outil
# « plan_required » »), au lieu de la phrase.
#
# `error` DOIT rester ce qu'on peut dire à voix haute, comme sur chaque site
# de ce fichier qui rend `{"error": "<phrase>"}`. Le code survit sous
# `error_code`, pour qui trace, jamais pour qui lit.
_TECHNICAL_ERROR_CODE = re.compile(r"^[a-z][a-z0-9]*(?:_[a-z0-9]+)+$")


def _business_refusal(result: dict[str, Any]) -> dict[str, Any]:
    """Réécrit un refus `{error: <code>, message: <phrase>}` en
    `{error: <phrase>, error_code: <code>}` — jamais l'inverse, et jamais
    touché quand `error` est déjà une phrase (aucun `message` séparé, ou
    `error` ne ressemble pas à un code)."""
    error = result.get("error")
    message = result.get("message")
    if (
        isinstance(error, str)
        and isinstance(message, str)
        and message.strip()
        and _TECHNICAL_ERROR_CODE.fullmatch(error)
    ):
        return {**result, "error": message, "error_code": error}
    return result


# ── #2470 / #2471 — LES DEUX GESTES NOMMÉS ──────────────────────────────────
#
# Le retour #2471 dit exactement ce qui manquait : « ça aurait été intéressant de
# proposer découvrir pour un tour d'horizon MAIS AUSSI ET SURTOUT une vraie
# analyse pour aller au fond de free et de ses filiales ». Une réponse qui
# n'offre qu'un lien vers un écran laisse le second geste invisible.
#
# Ces deux entrées voyagent DANS le résultat de l'outil : c'est ce que le modèle
# lit avant de rédiger, et ce que la garde GA-348 relit. Les écrire dans le seul
# prompt les rendrait invérifiables.
#
# ⚠️ Le coût du SECOND geste n'est pas ici, et c'est délibéré : il vient du pont
# (`plan_account_analysis` → `_analysis_card`), qui lit la grille et le solde. Un
# chiffre que le pont ne dit pas est ABSENT, jamais `0` (GA-18/GA-19).
GESTURE_TOUR = "tour_horizon"
GESTURE_DEEP_ANALYSIS = "analyse_de_fond"

#: Les deux gestes que TOUTE réponse de recherche de comptes doit porter, dans
#: l'ordre où on les propose. Lu par la garde GA-348.
REQUIRED_GESTURES: tuple[tuple[str, str], ...] = (
    (GESTURE_TOUR, "le tour d'horizon"),
    (GESTURE_DEEP_ANALYSIS, "l'analyse de fond"),
)


def _requested_count(tool_input: Mapping[str, Any]) -> int | None:
    """Le volume que la personne a DEMANDÉ (``requested_count``), tel que le
    modèle l'a relevé — jamais deviné. ``None`` sans entier strictement positif.
    Retombe sur ``limit`` pour les appels d'avant ce champ."""
    for key in ("requested_count", "limit"):
        raw = tool_input.get(key)
        if isinstance(raw, int) and not isinstance(raw, bool) and raw > 0:
            return raw
    return None


def _discover_full_list_href(criteria: Mapping[str, Any]) -> str | None:
    """Le lien Découvrir qui ouvre la liste COMPLÈTE : mêmes critères, mêmes clés
    que ``discoverSearch`` (apps/web), marqué ``laura=1``. ``None`` sans critère —
    jamais un ``/discover?`` vide qui a l'air d'un préremplissage."""
    pairs: list[tuple[str, str]] = []
    # Recette 21/10 B.4 — la VILLE et la compétence voyagent aussi (le rail lit `city` et `keywords`).
    for key in ("sectors", "signals", "department", "city", "region", "headcount", "keywords"):
        value = criteria.get(key)
        if key == "keywords" and not value:
            value = criteria.get("technologies")
        if isinstance(value, (list, tuple)):
            text = ",".join(str(v) for v in value if str(v).strip())
        else:
            text = str(value or "").strip()
        if text:
            pairs.append((key, text))
    if not pairs:
        return None
    pairs.append(("laura", "1"))
    return "/discover?" + urlencode(pairs, safe=",")


def volume_sprint_handoff(
    *, requested_count: int | None, criteria: Mapping[str, Any], returned_count: int | None
) -> dict[str, Any] | None:
    """#3428 / #3392 (recette prod 01/10) — ce que le RÉSULTAT d'une recherche dit
    de faire quand le volume demandé dépasse ce qu'une recherche rend exploitable.

    Sans lui, la réponse s'arrêtait à « Ouvrir Découvrir » (tour d'horizon limité
    à 20) : ni « je peux te sortir les 100 », ni la carte Sprint. ``None`` quand le
    volume tient dans le plafond — additif, byte-identique à avant.
    ``returned_count`` est le nombre de comptes RÉELLEMENT en main : il devient
    ``full_list_count`` de la carte, jamais le volume demandé (non mesuré)."""
    if requested_count is None or requested_count <= _ACCOUNT_SEARCH_MAX_ITEMS:
        return None
    out: dict[str, Any] = {
        "requested_count": requested_count,
        "render_as": "account_volume_sprint",
    }
    href = _discover_full_list_href(criteria)
    if href:
        out["full_list_href"] = href
    if returned_count is None:
        out["next_tool"] = "run_account_search"
        out["instruction"] = (
            f"{requested_count} comptes demandés : ouvre par « Je peux te sortir les {requested_count} », "
            "puis ne t'arrête PAS au simple renvoi vers l'écran de découverte (tour d'horizon limité à "
            f"{_ACCOUNT_SEARCH_MAX_ITEMS}) : appelle `run_account_search` avec les mêmes critères pour avoir de "
            "vrais comptes, et rends la carte `account_volume_sprint`. Territoire et profil déjà connus : "
            "UNE seule question au plus, jamais deux tours de clarification."
        )
    else:
        out["returned_count"] = returned_count
        # #3422.1 (recette prod 03/10) — le nombre DEMANDÉ n'est pas le nombre
        # TROUVÉ : promettre « les 100 » quand la recherche n'en rend que 20
        # est une promesse que l'écran dément à la ligne suivante.
        opening = (
            f"Ouvre par « Je peux te sortir les {requested_count} »"
            if returned_count >= requested_count
            else (
                f"Ouvre par le constat : {returned_count} comptes en main sur les {requested_count} demandés "
                f"(jamais « les {requested_count} » : seuls {returned_count} sont réellement rendus)"
            )
        )
        out["instruction"] = (
            f"{requested_count} comptes demandés, {returned_count} en main : rends la carte "
            f"`account_volume_sprint` — full_list_count = {returned_count} (les comptes réellement rendus, jamais "
            f"{requested_count}, non mesuré), sans `title` qui porte un nombre autre que {returned_count}, "
            "`full_list_href` copié TEL QUEL depuis ce résultat, `sprint` = les "
            "10 premiers `items` dans l'ordre rendu, `focus` ≤ 3 comptes SEULEMENT s'ils ont une porte d'entrée "
            f"vérifiée (sinon focus vide, dit). {opening} et propose de commencer par le sprint."
        )
    return out


def next_gestures(*, company: str = "") -> list[dict[str, Any]]:
    """Les deux gestes NOMMÉS qu'une réponse de recherche de comptes propose.

    `company` est l'entreprise ou le groupe que la demande nomme, quand elle en
    nomme un — il n'est jamais deviné, et son absence ne retire pas le geste :
    Laura demande alors sur QUI porter l'analyse.
    """
    target = company.strip()
    return [
        {
            "gesture": GESTURE_TOUR,
            "label": "le tour d'horizon",
            "tool": "run_account_search",
            "does": (
                "cherche les comptes qui répondent à ces critères et rend la liste ICI, dans la "
                "conversation — sans quitter l'écran."
            ),
            # Mesuré : la route du registre ne débite rien (aucun `credits.consume`
            # sur `discover/registry`). Ce qui la borne est nommé juste en dessous.
            "cost_credits": 0,
            "cost_label": "inclus",
            "bounded_by": (
                f"le plafond quotidien de messages du copilote et les {_ACCOUNT_SEARCH_MAX_ITEMS} "
                "comptes rendus au plus"
            ),
        },
        {
            "gesture": GESTURE_DEEP_ANALYSIS,
            "label": "l'analyse de fond",
            "tool": "plan_account_analysis",
            "company": target,
            "does": (
                "ouvre le dossier complet d'une entreprise et de son groupe — filiales, "
                "décideurs, angles d'attaque" + (f" — ici : {target}." if target else ".")
            ),
            # Aucun `cost_credits` : le prix vient du pont, pas d'ici.
            "cost_label": (
                "analyse de fond — `plan_account_analysis` prépare le dossier ; "
                "n'annonce aucun chiffre de coût ni de solde"
            ),
        },
    ]


