#: #3983.3 — ce que la source ne publie pas, dit une fois, au même endroit.
_SITE_HEADCOUNT_UNMEASURED = "effectif de l'équipe sur place : la source ne publie pas l'effectif d'un établissement"


_DEMAND_SIGNAL_TYPES = ("tender", "hiring")


def _hiring_demand_matches_trade(
    signal: Mapping[str, Any], *, terms: tuple[str, ...], domain_filter: Any
) -> bool:
    """LUD.5 — une offre d'emploi datée touche-t-elle le MÉTIER demandé ? Le métier nommé gagne ; à défaut,
    le pack de l'espace (même tri que les sources d'offres). Ni l'un ni l'autre : rien à filtrer, tout passe."""
    if terms:
        return _signal_touches_offer(signal, terms)
    if domain_filter is not None:
        title = str(signal.get("label") or "").split("—", 1)[-1].strip()
        return bool(domain_filter.matches({"intitule": title}))
    return True


def _attach_current_demands(
    result: dict[str, Any],
    listed: list[dict[str, Any]],
    *,
    trade_terms: tuple[str, ...] = (),
    domain_filter: Any = None,
    recruiting_intent: bool = False,
) -> None:
    """#3704.6 — par entreprise, ses demandes actuelles CONNUES (appel d'offres, recrutement : des
    signaux DATÉS déjà cherchés par le registre, `signals_searched`). Une absence ne fait aucune ligne
    dans la liste (doctrine) : elle se DIT une fois, en tête, avec la distinction « pas cherché » ≠
    « cherché, rien trouvé ». Aucune entreprise n'est retirée faute de demande."""
    with_demand = searched_none = not_searched = 0
    recruiting: list[str] = []
    for item in listed:
        if not item.get("signals_searched"):
            not_searched += 1
            continue
        # LUD.5 — « qui recrutent en méthodes / qualité » : une offre d'un AUTRE métier n'est pas une demande
        # pour cette recherche. Sans intention de recrutement, sans métier nommé ni pack filtré : tout passe.
        trade_filter = recruiting_intent and bool(trade_terms or domain_filter is not None)
        demands = [
            {key: signal[key] for key in ("type", "label", "date", "detail") if signal.get(key)}
            for signal in item.get("signals") or []
            if isinstance(signal, Mapping)
            and signal.get("type") in _DEMAND_SIGNAL_TYPES
            and (
                not trade_filter
                or signal.get("type") != "hiring"
                or _hiring_demand_matches_trade(signal, terms=trade_terms, domain_filter=domain_filter)
            )
            # LUD.5 — « recrute » porte toujours une offre DATÉE.
            and (signal.get("type") != "hiring" or str(signal.get("date") or "").strip())
        ]
        if demands:
            item["current_demands"] = demands
            with_demand += 1
            if recruiting_intent and any(d["type"] == "hiring" for d in demands):
                recruiting.append(str(item.get("name") or ""))
        else:
            searched_none += 1
    if recruiting_intent:
        # LUD.5 — la SEULE liste des entreprises qui « recrutent » : chacune porte une offre datée du métier.
        result["recruiting_companies"] = [name for name in recruiting if name]
        result["recruiting_note"] = (
            "Seules les entreprises de `recruiting_companies` « recrutent » : chacune porte, dans "
            "`current_demands`, une offre d'emploi DATÉE du métier demandé — cite l'intitulé et la date. "
            "Ne présente jamais une autre entreprise comme « qui recrute » : sans offre datée du métier, "
            "dis qu'aucune offre n'est connue, ou qu'elle n'a pas été cherchée."
        )
    result["current_demands_summary"] = {
        "with_known_demand": with_demand,
        "searched_none_known": searched_none,
        "not_searched": not_searched,
    }
    result["current_demands_note"] = (
        "« Aucune demande connue » veut dire que les sources publiques consultées n'en montrent pas — "
        "pas l'absence de potentiel ; « pas cherché » veut dire que cette entreprise n'a pas été "
        "interrogée sur ses demandes. Aucune entreprise n'est retirée faute de demande."
    )


def _skill_widening_fields(query: object) -> dict[str, Any]:
    """#4434.3 — l'élargissement par compétence que le moteur a APPLIQUÉ (``widening_steps``, nommé) ou seulement
    TENTÉ sans rien trouver (``widening_tried``) : Laura le DIT en une ligne (``laura_acts.widening_line_from_output``),
    elle ne rend jamais un zéro sec ni « recherche élargie par thème » sans voisin nommé. Absent : aucune clé."""
    from app.services.criteria_referential import widened_label_fr

    if not isinstance(query, Mapping):
        return {}
    out: dict[str, Any] = {}
    applied = query.get("widening")
    steps: list[str] = []
    for step in applied.get("steps") or [] if isinstance(applied, Mapping) else []:
        if not isinstance(step, Mapping) or step.get("axis") != "skill":
            continue
        names = [
            name.removeprefix("proche : ")
            for code in step.get("codes") or []
            if (name := widened_label_fr({"axis": "skill", "tier": step.get("tier"), "code": code}))
        ]
        if names:
            steps.append(", ".join(dict.fromkeys(names)))
    if steps:
        out["widening_steps"] = steps
    tried = query.get("wideningTried")
    terms = [
        str(t) for step in tried or [] if isinstance(step, Mapping) for t in step.get("terms") or [] if str(t).strip()
    ]
    if terms and not steps:
        out["widening_tried"] = list(dict.fromkeys(terms))
    return out


def _siren_or_none(value: Any) -> str | None:
    """#3704.5 — un SIREN, ou rien : 9 chiffres exactement, sinon on ne transmet pas (le serveur est strict)."""
    text = str(value or "").strip()
    return text if re.fullmatch(r"\d{9}", text) else None


def _analysis_handoff(item: Mapping[str, Any], criteria: Mapping[str, Any]) -> dict[str, Any]:
    """#3704.5 — de quoi faire REJOINDRE l'analyse à une cible neuve : son identité légale et ce
    des contraintes de la demande que le cadrage d'analyse sait porter (l'effectif). Le reste
    (zone, secteur) est NOMMÉ comme non transmissible — jamais promis. Aucun compte n'est créé ici :
    l'analyse part par `plan_account_analysis` puis `start_account_analysis`, geste de l'utilisateur."""
    handoff: dict[str, Any] = {
        "company": item.get("name"),
        "siren": item.get("siren"),
        "next": "plan_account_analysis puis start_account_analysis (avec ce `siren` et ce `scope`)",
    }
    bounds = _HEADCOUNT_BOUNDS.get(str(criteria.get("headcount") or ""))
    if bounds:
        scope = {
            key: value for key, value in (("headcount_min", bounds[0]), ("headcount_max", bounds[1])) if value is not None
        }
        if scope:
            handoff["scope"] = scope
    not_transferable = [key for key in ("department", "region", "sectors") if criteria.get(key)]
    if not_transferable:
        handoff["not_transferable"] = not_transferable
    return handoff


# #3866 — le domaine d'une offre se reconnaît à ses racines ; « Data/BI » couvre aussi ses voisins
# courants. Une offre hors de ce vocabulaire garde ses propres mots (jamais un domaine deviné).
_OFFER_DOMAIN_STEMS: dict[str, tuple[str, ...]] = {
    "data": (
        "data", "donnee", "bi", "business intelligence", "analytics", "dataviz", "etl", "big data",
        "machine learning", "power bi", "sql", "datalake", "data lake", "dba", "reporting",
    ),
    "bi": ("data", "donnee", "bi", "business intelligence", "analytics", "dataviz", "etl", "power bi", "reporting"),
}
_OFFER_STOPWORDS = frozenset({"des", "les", "une", "pour", "chez", "avec", "et", "de", "du", "la", "le", "en", "offre"})


def _offer_terms(offer: str) -> tuple[str, ...]:
    """#3866 — les racines qui disent « ce signal touche le domaine de l'offre ». Vide = pas d'offre
    déclarée = aucune règle appliquée (on n'invente pas un périmètre)."""
    import re as _re

    from app.services.domain_job_filters import fold

    terms: list[str] = []
    for word in _re.split(r"[^a-z0-9#+]+", fold(offer)):
        if (len(word) >= 3 or word == "bi") and word not in _OFFER_STOPWORDS:
            for stem in (word, *_OFFER_DOMAIN_STEMS.get(word, ())):
                if stem not in terms:
                    terms.append(stem)
    return tuple(terms)


def _signal_touches_offer(signal: Mapping[str, Any], terms: tuple[str, ...]) -> bool:
    import re as _re

    from app.services.domain_job_filters import fold

    blob = fold(f"{signal.get('label') or ''} {signal.get('detail') or ''}")
    # DEC-4036 Q14 (Louis 19/10) — l'adéquation exige une COMPÉTENCE NOMMÉE : une racine courte
    # (« bi », « etl », « sql », « dba ») est un MOT ENTIER, jamais un préfixe — « bien-être »,
    # « bilingue », « biologiste » ne prouvent pas une adéquation Data/BI.
    return (
        bool(
            _re.search(
                "|".join(rf"(?<![a-z0-9]){_re.escape(t)}{'(?![a-z0-9])' if len(t) <= 3 else ''}" for t in terms),
                blob,
            )
        )
        if terms
        else True
    )


def _skill_evidence_signal(evidence: object) -> dict[str, str] | None:
    """#4421.3 — l'offre la plus récente qui a fait trouver le compte (moteur compétence), en signal de recrutement
    DATÉ ; ``None`` sans intitulé ou sans date ISO (une offre non datée ne se cite pas)."""
    if not isinstance(evidence, Mapping) or not isinstance(evidence.get("latestOffer"), Mapping):
        return None
    latest = evidence["latestOffer"]
    title = " ".join(str(latest.get("title") or "").split())[:200]
    date = str(latest.get("date") or "").strip()[:10]
    if not title or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date):
        return None
    city = " ".join(str(latest.get("city") or "").split())[:120]
    # #4977.1 — la ville de l'offre voyage avec elle ; inconnue, aucune clé (jamais une ville devinée).
    return {"type": "hiring", "label": title, "date": date, **({"location": city} if city else {})}


def _access_fields(candidate: Mapping[str, Any]) -> dict[str, Any] | None:
    """#5013 — la classe d'accès A-D de Découvrir (`barrier.access_class`), avec sa raison FACTUELLE
    (les preuves des proxies mesurés). Même calcul que l'écran (`barrier_for_company`) ; ``None`` quand
    la barrière n'est pas estimable : une classe absente se NOMME, elle ne devient jamais « D » ni « 0 »."""
    from app.services.access_scoring import barrier_for_company

    barrier = candidate.get("barrier")
    if not isinstance(barrier, Mapping):
        signals = candidate.get("signals")
        barrier = barrier_for_company(dict(candidate), signals=signals if isinstance(signals, list) else [])
    klass = str(barrier.get("access_class") or "")
    if not barrier.get("measurable") or klass not in _ACCESS_CLASS_ORDER:
        return None
    reasons = [
        evidence
        for proxy in barrier.get("proxies") or []
        if isinstance(proxy, Mapping) and proxy.get("measurable") and (evidence := str(proxy.get("evidence") or "").strip())
    ]
    out: dict[str, Any] = {"access_class": klass}
    label = str(barrier.get("label") or "").strip()
    if label:
        out["access_label"] = label
    if reasons:
        out["access_reason"] = reasons[:3]
    return out


#: #5013 — A (ouvert) → D (verrouillé) ; le tri « les plus faciles d'abord » suit cet ordre.
_ACCESS_CLASS_ORDER: dict[str, int] = {"A": 0, "B": 1, "C": 2, "D": 3}


def _access_summary_of(items: Sequence[Mapping[str, Any]]) -> tuple[dict[str, int], str]:
    """#5013 — le compte par classe d'accès des comptes RENDUS (jamais d'un autre ensemble) et sa phrase.
    Vide quand aucun compte ne porte d'information d'accès : on n'invente pas une répartition."""
    counts = {klass: 0 for klass in _ACCESS_CLASS_ORDER}
    unmeasured = 0
    for item in items:
        klass = str(item.get("access_class") or "")
        if klass in counts:
            counts[klass] += 1
        else:
            unmeasured += 1
    if not any(counts.values()):
        return {}, ""
    parts = [f"{n} en {klass}" for klass, n in counts.items() if n]
    if unmeasured:
        parts.append(f"{unmeasured} non estimable{'s' if unmeasured > 1 else ''}")
    return {**counts, "non_estimable": unmeasured}, "Classe d'accès des comptes listés : " + ", ".join(parts) + "."


def _search_item(
    candidate: Mapping[str, Any], *, offer: str = "", offer_terms: tuple[str, ...] = ()
) -> dict[str, Any] | None:
    """Projette UN candidat du registre sur ce que la carte `account_ranking`
    saura poser. `None` écarte la ligne — un candidat sans identité est un nom
    sorti d'un modèle, pas une entreprise.

    ⚠️ Rien n'est comblé : un score non mesuré est ABSENT de la sortie, jamais
    rendu `0` (GA-18/GA-19), et ce qui n'a pas pu être évalué est NOMMÉ.
    """
    # R22 VU.5 — « HEXANET (NOZICAA;OLM;…) » : les entités concaténées par le registre ne s'affichent pas.
    name = display_company_name(candidate.get("name"))
    siren = str(candidate.get("siren") or "").strip()
    if not name or not siren:
        return None

    item: dict[str, Any] = {"name": name, "siren": siren}
    for key, field in (("city", "city"), ("department", "department"), ("nafLabel", "activity")):
        value = str(candidate.get(key) or "").strip()
        if value:
            item[field] = value

    headcount = candidate.get("headcount")
    if isinstance(headcount, int) and not isinstance(headcount, bool):
        item["headcount"] = headcount

    # #3705.5 — rattachement probable à un groupe : une personne MORALE dirige la société
    # (publié au registre). Un indice, pas une preuve ; son ABSENCE ne dit pas « indépendante ».
    officers = [str(n).strip() for n in candidate.get("corporateOfficers") or [] if str(n).strip()]
    if officers:
        item["group_link"] = {"observed_entities": officers[:3], "kind": "legal_entity_officer"}

    # #3983.3 — la BASE de la géographie, dite : « siège à Paris (75), 3
    # établissements en Auvergne-Rhône-Alpes ». Absente quand le registre ne
    # prouve rien sur la zone (on n'affiche pas ce qu'on n'a pas).
    location = describe_geography(candidate.get("geography"))
    if location:
        item["location"] = location

    # #5013.1 — la classe d'accès A-D (comme Découvrir) ; non estimable → absente et nommée plus bas.
    access = _access_fields(candidate)
    if access:
        item.update(access)

    score = candidate.get("score")
    score_max = candidate.get("scoreMax")
    if isinstance(score, (int, float)) and not isinstance(score, bool):
        item["score"] = score
        if isinstance(score_max, (int, float)) and not isinstance(score_max, bool):
            item["score_max"] = score_max

    factors = [
        label
        for factor in candidate.get("scoreFactors") or []
        if isinstance(factor, Mapping)
        and (
            label := " — ".join(
                p for p in (str(factor.get("label") or "").strip(), str(factor.get("detail") or "").strip()) if p
            )
        )
    ]
    if factors:
        item["why"] = factors[:5]

    unmeasured = [str(x).strip() for x in candidate.get("scoreUnmeasured") or [] if str(x).strip()]
    if unmeasured:
        item["not_evaluated"] = [_NOT_EVALUATED_LABELS.get(key, key) for key in unmeasured[:6]]
    if not access:
        # Champ à part (pas dans `not_evaluated`, dont le contrat est tenu par #3707) : la classe absente se NOMME.
        item["access_class_unmeasured"] = "classe d'accès non estimable (proxies publics insuffisants)"
    if location:
        # #3983.3 — « équipe » (l'effectif d'un SITE) n'est pas dans la source : le
        # registre ne publie qu'une tranche d'effectif de l'ENTREPRISE.
        item["not_evaluated"] = [*item.get("not_evaluated", []), _SITE_HEADCOUNT_UNMEASURED]

    qualification = candidate.get("qualification")
    if isinstance(qualification, Mapping):
        verdict = str(qualification.get("verdict") or "").strip()
        if verdict:
            # #3707 — un code brut ("recommended") ne s'affiche jamais : traduit
            # avec le MÊME vocabulaire que Découvrir (GA-26).
            item["verdict"] = _QUALIFICATION_VERDICT_LABELS.get(verdict, verdict)
        reasons = [str(x).strip() for x in qualification.get("reasons") or [] if str(x).strip()]
        if reasons:
            item["verdict_reasons"] = [_QUALIFICATION_REASON_LABELS.get(code, code) for code in reasons[:5]]

    angle = str(candidate.get("angle") or "").strip()
    if angle:
        item["why_now"] = angle

    # #4433 — un compte remonté par ÉLARGISSEMENT (moins de 10 exacts) porte son étiquette, jamais confondu.
    from app.services.criteria_referential import widened_label_fr

    widened = widened_label_fr(candidate.get("widenedBy"))
    if widened:
        item["widened"] = widened

    sources = candidate.get("sources")
    if isinstance(sources, list) and sources and isinstance(sources[0], Mapping):
        as_of = str(sources[0].get("fetchedAt") or "").strip()
        if as_of:
            item["as_of"] = as_of

    # #2547.1 (suite, 18/09) — trois états, jamais deux (GA-18/GA-19) :
    # `signalsSearched` (posé par `discover.py::_start_signal_tasks` /
    # `_finish_signal_tasks`, même motif que le lot voisin dans Découvrir)
    # distingue « jamais cherché » (absent/False — hors des premiers rangs
    # interrogés, ou tâche pas terminée sous le budget de temps) de
    # « cherché, rien trouvé » (True, `signals` vide) et « cherché, trouvé »
    # (True, `signals` non vide). Toujours rendu — un booléen n'est pas un
    # zéro déguisé, c'est la mesure elle-même.
    signals_searched = bool(candidate.get("signalsSearched"))
    # #4421.3 / #4430.9 — un compte trouvé par le moteur compétence porte SON offre (intitulé + date) : elle est
    # un signal de recrutement daté comme les autres — citée, datée par le code, et porteuse du geste « mail ».
    skill_offer = _skill_evidence_signal(candidate.get("skillEvidence"))
    if skill_offer is not None:
        signals_searched = True
    item["signals_searched"] = signals_searched
    # #4430 — d'où viennent les offres : lues dans le cache commun (Laura dit leur DATE), ou trouvées par
    # une collecte fraîche. Absent sinon — jamais une date devinée.
    jobs_as_of = str(candidate.get("jobsAsOf") or "").strip()
    if jobs_as_of:
        item["jobs_as_of"] = jobs_as_of
    if candidate.get("skillFreshFill") is True:
        item["fresh_collection"] = True
    if signals_searched:
        found = [
            s
            for s in candidate.get("signals") or []
            if isinstance(s, Mapping) and str(s.get("date") or "").strip() and str(s.get("label") or "").strip()
        ]
        if found:

            def _delivery_fit_note(s: Mapping[str, Any]) -> dict[str, Any]:
                # #3226 (#3203.7) — LA FORMULATION du § RÉPONSE, seulement
                # quand un jugement a une base (jamais sur `unknown` — voir le
                # docblock de `delivery_fit_response_hint`). DISTINCT de
                # `remoteWorkPolicy` (politique de télétravail des salariés),
                # que la phrase peut CONTRASTER mais jamais recalculer.
                level = s.get("deliveryFit")
                if not isinstance(level, str) or level == "unknown":
                    return {}
                hint = delivery_fit_response_hint(level, remote_work_policy=s.get("remoteWorkPolicy"))
                return {"delivery_fit_note": hint} if hint else {}

            item["signals"] = [
                {
                    "type": s.get("type"),
                    "label": s.get("label"),
                    "date": s.get("date"),
                    **({"detail": s["detail"]} if s.get("detail") else {}),
                    # #4977.1 — le lieu d'une offre, quel que soit le champ source (``location`` ou ``city``).
                    **({"location": place} if (place := str(s.get("location") or s.get("city") or "").strip()) else {}),
                    **_delivery_fit_note(s),
                }
                for s in found[:5]
            ]
        if skill_offer is not None and not any(
            sig.get("label") == skill_offer["label"] and sig.get("date") == skill_offer["date"]
            for sig in item.get("signals") or []
        ):
            item["signals"] = [skill_offer, *(item.get("signals") or [])][:5]
            item.setdefault("current_demands", [dict(skill_offer)])

    # #3866 (recette prod 10/10, conv 3a9866ff) — « Recommandé » (verdict de QUALIFICATION : une
    # organisation à laquelle on peut vendre) se lisait « adéquation prouvée » : 3 cartes
    # « Recommandé » sur secteur/siège/effectif/ancienneté seuls. Sans preuve d'adéquation (ni
    # signal daté, ni angle), le candidat sort « À qualifier », raison nommée.
    # #3866 (décision Louis 10/10 soir) — avec une offre déclarée, un signal de RECRUTEMENT hors de son
    # domaine ne prouve pas l'adéquation : seul un signal qui touche le domaine compte.
    proving_signals = [
        sig
        for sig in item.get("signals") or []
        if not offer_terms or sig.get("type") != "hiring" or _signal_touches_offer(sig, offer_terms)
    ]
    if item.get("verdict") == _QUALIFICATION_VERDICT_LABELS["recommended"] and not (
        item.get("why_now") or proving_signals
    ):
        item["verdict"] = _QUALIFICATION_VERDICT_NO_FIT_PROOF
        item["verdict_reasons"] = [
            *item.get("verdict_reasons", []),
            (
                f"recrutement hors {offer} : ne prouve pas l'adéquation"
                if item.get("signals")
                else "adéquation à ta demande non prouvée : critères du registre seuls (secteur, zone, effectif, ancienneté)"
            ),
        ]

    # #2299.4 — une hypothèse de doublon posée par `blend_accounts` (nom
    # proche, aucun identifiant canonique commun) devient une LIMITE de la
    # carte `account_ranking` (`RankedAccount.limits`, déjà rendue par
    # `AccountRankingCard.tsx`) : un raisonnement consultable, jamais un
    # chiffre de confiance, et les deux candidats restent deux lignes
    # distinctes — l'hypothèse ne fusionne rien (2299.5).
    hypotheses = candidate.get("duplicate_hypothesis")
    if isinstance(hypotheses, list) and hypotheses:
        reasons = [
            str(h.get("reasoning") or "").strip()
            for h in hypotheses
            if isinstance(h, Mapping) and str(h.get("reasoning") or "").strip()
        ]
        if reasons:
            item["limits"] = reasons[:2]

    # #3202 — l'archétype (ESN, cabinet de recrutement…) sur le SEUL signal
    # NAF déjà résolu par `actor_typology.classify_actor_type` (GA-26 : jamais
    # recalculé ici). `archetype_from_actor_type` rend `None` pour NON_CLASSE
    # et pour les archétypes que ce signal ne sait pas établir (startup,
    # scale-up…) — un champ absent, jamais un archétype deviné.
    naf_code = candidate.get("nafCode")
    if naf_code:
        item["naf_code"] = str(naf_code)
        verdict = archetype_from_actor_type(classify_actor_type(naf=naf_code, name=name))
        if verdict is not None:
            item["archetype"] = verdict.archetype.value
            item["archetype_confidence"] = verdict.confidence.value
    # #3866.1 — le type de relation (client final · ESN concurrente · partenaire · intermédiaire),
    # déduit de la forme juridique ET de l'activité (`relation_type.py`, jamais le NAF seul).
    # « Non déterminé » est NOMMÉ avec sa raison, jamais deviné.
    relation = relation_type_of(
        naf=naf_code, name=name, legal_category=candidate.get("legalCategory") or candidate.get("legal_category")
    )
    item["relation_type"] = relation.type.value
    item["relation_label"] = relation.label
    if relation.reason:
        item["relation_type_reason"] = RELATION_REASON_LABELS.get(relation.reason, relation.reason)
    # #3202.3 — STARTUP se décide sur des signaux COMBINÉS via `classify_startup`
    # (jamais un indice seul). Seul signal réel de ce chemin : un recrutement daté
    # (`signals[].type == "hiring"`, posé quand `signalsSearched`). Effectif, secteur
    # IT et date de création sont passés pour le contexte mais ne comptent jamais.
    # #3202.7 — NO-GO : « peu d'information = startup » est interdit : un verdict
    # `not_established` ne produit AUCUNE clé (on n'affiche pas ce qu'on n'a pas).
    hiring = signals_searched and any(
        isinstance(s, Mapping) and s.get("type") == "hiring" and str(s.get("date") or "").strip()
        for s in candidate.get("signals") or []
    )
    startup = classify_startup(
        StartupSignals(
            headcount=headcount if isinstance(headcount, int) and not isinstance(headcount, bool) else None,
            sector_is_it=str(naf_code or "").startswith(("62", "63")) or None,
            creation_date=str(candidate.get("creationDate") or "").strip() or None,
            hiring_detected=True if hiring else None,
        )
    )
    if startup.confidence is not ArchetypeConfidence.NOT_ESTABLISHED:
        item["startup_verdict"] = {
            "confidence": startup.confidence.value,
            "evidence": startup.evidence,
        }
    return item


def _degraded_without_vendors(degraded: list[Any]) -> list[dict[str, Any]]:
    """Ce qui a dégradé la recherche, SANS le nom de la source.

    ⚠️ Les entrées `degraded` du registre portent `{"source": "pappers", ...}` —
    le nom d'un de NOS fournisseurs. La sortie d'un outil entre dans le contexte
    du modèle : la laisser passer mettrait ce nom dans un prompt, et de là dans
    une phrase lue devant un client. La doctrine ne fait pas d'exception (« nos
    fournisseurs ne se nomment JAMAIS — ni à l'écran, ni dans un prompt »).

    La RAISON survit, et c'est elle qui compte : sans elle, une liste courte se
    lirait comme « le marché est petit », ce qui est faux. L'écran Découvrir a
    son propre chemin et garde la source — ce n'est pas la même question.
    """
    out: list[dict[str, Any]] = []
    for entry in degraded:
        if not isinstance(entry, Mapping):
            continue
        kept = {key: value for key, value in entry.items() if key in ("reason", "kind", "fields")}
        if kept.get("reason"):
            out.append(kept)
    return out


async def _attach_owned_account_ids(items: Any, user_id: str) -> None:
    """#3227 — pose `account_id` sur les items du registre qui SONT déjà un
    compte de l'espace appelant, rapprochés par SIREN (identifiant légal), la
    requête scopée `user_id` : un compte d'un autre espace ne sort jamais, et un
    item sans compte n'a pas la clé (« pas d'id » ne se lit pas « id vide »).
    Échec de la lecture ⇒ aucun id posé, jamais un id deviné."""
    if not isinstance(items, list) or not user_id:
        return
    sirens = [str(i.get("siren")) for i in items if isinstance(i, dict) and i.get("siren")]
    if not sirens:
        return
    try:
        from app.services.supabase_client import get_supabase

        res = (
            await get_supabase()
            .table("accounts")
            .select("id, siren")
            .in_("siren", sirens)
            .eq("user_id", user_id)
            # #4009 — une fiche supprimée ne prête jamais son id.
            .neq("status", "deleted")
            .aexecute()
        )
        rows = getattr(res, "data", None) or []
    except Exception as exc:  # noqa: BLE001 — l'id est un bonus, jamais un bloqueur
        logger.warning("Rapprochement des comptes du portefeuille indisponible: %s", exc)
        return
    owned: dict[str, str] = {}
    for row in rows:
        if isinstance(row, dict) and row.get("id") and row.get("siren"):
            owned.setdefault(str(row["siren"]), str(row["id"]))
    for item in items:
        if isinstance(item, dict) and str(item.get("siren") or "") in owned:
            item["account_id"] = owned[str(item["siren"])]


async def _known_people_by_account(items: Any, user_id: str) -> dict[str, list[dict[str, str]]]:
    """LUDOVIC-D LC.6 — les personnes CONNUES (contacts actifs, non écartés) des comptes de l'espace
    rendus par la recherche, par `account_id`, les mieux classées d'abord. Échec de lecture ⇒ `{}` :
    l'item dira « personne connue : à trouver », jamais un nom deviné."""
    ids = [str(i["account_id"]) for i in items or [] if isinstance(i, dict) and i.get("account_id")]
    if not ids or not user_id:
        return {}
    try:
        from app.services.supabase_client import get_supabase

        res = (
            await get_supabase()
            .table("contacts")
            .select("id, account_id, full_name, title, email, phone, priority")
            .in_("account_id", ids)
            .is_("deleted_at", "null")
            .is_("excluded_at", "null")
            .order("priority")
            .limit(len(ids) * 10)
            .aexecute()
        )
        rows = getattr(res, "data", None) or []
    except Exception as exc:  # noqa: BLE001 — les personnes sont un bonus, jamais un bloqueur
        logger.warning("Personnes connues des comptes trouvés indisponibles: %s", exc)
        return {}
    people: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        name = str((row or {}).get("full_name") or "").strip() if isinstance(row, dict) else ""
        if not name:
            continue
        # #4421.3 — l'identifiant (le geste « Préparer le mail à … ») et les coordonnées pro EN CLAIR (c87).
        entry = {
            "name": name,
            **{
                key: str(row[field]).strip()
                for key, field in (("title", "title"), ("contact_id", "id"), ("email", "email"), ("phone", "phone"))
                if str(row.get(field) or "").strip()
            },
        }
        people.setdefault(str(row.get("account_id")), []).append(entry)
    return people


async def _attach_workspace_partner_relation(items: Any, user_id: str) -> None:
    """#3866 (reste) — un résultat dont le SIREN est celui d'un partenaire DÉCLARÉ de l'espace (relation
    d'espace, pont #3247 `access_by_siren`) est typé « partenaire », pas seulement sur déclaration à la main.
    Les autres lignes gardent le type calculé (forme juridique + activité). Pont éteint ou en échec ⇒ rien
    n'est posé : un type n'est jamais deviné. Ne nomme aucune source."""
    if not isinstance(items, list) or not user_id:
        return
    sirens = list(
        dict.fromkeys(str(i.get("siren")) for i in items if isinstance(i, dict) and str(i.get("siren") or "").isdigit())
    )
    if not sirens:
        return
    from app.services import bellum_api

    access: dict[str, Any] = {}
    try:
        # Le pont plafonne à 20 SIREN par appel : on lit par paquets.
        for start in range(0, len(sirens), 20):
            part = await bellum_api.access_by_siren(user_id, sirens=sirens[start : start + 20])
            if isinstance(part, dict):
                access.update(part)
    except Exception as exc:  # noqa: BLE001 — le type d'espace est un bonus, jamais un bloqueur
        logger.warning("Lecture des partenaires de l'espace indisponible: %s", exc)
        return
    for item in items:
        if not isinstance(item, dict):
            continue
        entry = access.get(str(item.get("siren") or ""))
        partner = entry.get("is_workspace_partner") if isinstance(entry, dict) else None
        if isinstance(partner, dict) and partner.get("name"):
            item["relation_type"] = RelationType.PARTNER.value
            item["relation_label"] = RELATION_LABELS[RelationType.PARTNER]
            item.pop("relation_type_reason", None)


_LEGAL_NAME_TOKENS =frozenset({"sas", "sasu", "sa", "se", "sarl", "eurl", "snc", "sca", "group", "groupe", "france"})


def _match_key(name: object) -> str:
    """#4055 — la clé d'un nom d'entreprise pour le rapprochement : sans accent, sans casse, sans forme juridique."""
    from app.services.text_norm import normalize_name

    tokens = [t for t in "".join(c if c.isalnum() else " " for c in normalize_name(name)).split() if t not in _LEGAL_NAME_TOKENS]
    return " ".join(tokens)


def _prefix_name_match(key: str, by_name: dict[str, dict[str, Any]]) -> dict[str, Any] | None:
    """#4055 (recette prod 13/10, lot W-C) — « CAPGEMINI TECHNOLOGY SERVICES » sortait « Nouvelle cible » alors
    que l'espace porte « CAPGEMINI » : le nom connu est le DÉBUT du nom de la ligne (ou l'inverse), en MOTS
    ENTIERS (« capgeminius » ≠ « capgemini »). Toujours « à vérifier », jamais une fusion ; une clé de moins de
    trois lettres ne rapproche rien (trop générique). Le nom connu le plus long gagne (le plus précis)."""
    tokens = key.split()
    best: dict[str, Any] | None = None
    best_len = 0
    for known, row in by_name.items():
        if len(known) < 3:
            continue
        known_tokens = known.split()
        shorter, longer = (known_tokens, tokens) if len(known_tokens) <= len(tokens) else (tokens, known_tokens)
        if len(" ".join(shorter)) < 3 or longer[: len(shorter)] != shorter:
            continue
        if len(known) > best_len:
            best, best_len = row, len(known)
    return best


async def _attach_workspace_match_levels(items: Any, user_id: str) -> None:
    """#4055 (BEL-AM-1210-004) — trois niveaux, jamais deux : « déjà dans votre base » (SIREN, `account_id` posé
    ailleurs), « filiale/groupe d'un compte connu » (`group_known`) et « rapprochement à vérifier » (`to_verify`,
    même nom sans SIREN commun). Pose `workspace_match` {level, account_id, name} sur les lignes SANS `account_id`,
    la requête scopée `user_id`. Rien n'est fusionné ni écrit : le rapprochement PROPOSE, l'humain tranche. Échec
    de lecture ⇒ aucune clé posée (l'absence de vérification se nomme par l'absence du champ)."""
    if not isinstance(items, list) or not user_id:
        return
    candidates = [i for i in items if isinstance(i, dict) and not i.get("account_id")]
    if not candidates:
        return
    try:
        from app.services.supabase_client import get_supabase

        res = (
            await get_supabase()
            .table("accounts")
            .select("id, company_name, siren, group_head_siren")
            .eq("user_id", user_id)
            .neq("status", "deleted")
            .limit(2000)
            .aexecute()
        )
        rows = [r for r in (getattr(res, "data", None) or []) if isinstance(r, dict) and r.get("id")]
    except Exception as exc:  # noqa: BLE001 — le niveau est un bonus, jamais un bloqueur
        logger.warning("Rapprochement par niveaux des comptes indisponible: %s", exc)
        return
    by_group_head: dict[str, dict[str, Any]] = {}
    by_name: dict[str, dict[str, Any]] = {}
    for row in rows:
        head = str(row.get("group_head_siren") or "")
        if head:
            by_group_head.setdefault(head, row)
        key = _match_key(row.get("company_name"))
        if key:
            by_name.setdefault(key, row)
    for item in candidates:
        siren = str(item.get("siren") or "")
        group_row = by_group_head.get(siren) if siren else None
        if group_row is not None:
            level, other = "group_known", group_row
        else:
            key = _match_key(item.get("name"))
            other = (by_name.get(key) or _prefix_name_match(key, by_name)) if key else None
            level = "to_verify"
        if other is not None:
            item["workspace_match"] = {
                "level": level,
                "account_id": str(other["id"]),
                "name": str(other.get("company_name") or ""),
            }


async def _run_account_search(
    tool_input: dict[str, Any], *, profile_data: dict | None, space_key: str | None = None
) -> dict[str, Any]:
    """#2470 — le tour d'horizon EXÉCUTÉ, dans la conversation.

    #4430 (Louis 21/10) — ``space_key`` : l'espace de la personne, seul sésame des offres FRAÎCHES
    du moteur (plafond quotidien par espace) ; absent, le moteur reste au cache seul.

    Import local du routeur, comme `compare_accounts` juste au-dessus : il évite
    le cycle `routers → services → routers` au chargement.
    """
    # #2852.6-53 (lot V22, suite) — même enveloppe canonique, câblée ici pour
    # la première fois sur un outil MULTI-SOURCES (le registre public).
    # `evidence`/`freshness`/`confidence` restent HORS de ce lot (doctrine : un
    # score sans second axe serait nu) — `status`/`result_type`/
    # `sources_consulted`/`coverage`/`caveats`/`unknowns`/`duration_ms`/
    # `timeout` s'appuient tous sur le signal de couverture qui existe déjà ici
    # (`degraded`/`kind`, #2264.43) et sur l'appel déjà chronométré.
    from app.models.tool_result_envelope import (
        ToolResultEnvelope,
        ToolResultStatus,
        coverage_from_degraded,
        error_envelope,
    )
    from app.routers.discover import (
        REGISTRY_SOURCE_NAMES,
        DiscoverFilters,
        DiscoverRegistryRequest,
        discover_registry,
        source_resume_token,
    )

    sectors = _pick_known(tool_input.get("sectors"), (*_DISCOVER_SECTORS, *_SEARCH_NAF_SECTORS))
    department = str(tool_input.get("department") or "").strip().upper()
    # #3392 / #3705 — la région est exposée par le schéma de l'outil (« Île-de-France » était
    # inexprimable) ; GA-26 : un seul vocabulaire de région, `_DISCOVER_REGIONS`.
    region = _pick_known(tool_input.get("region"), _DISCOVER_REGIONS)
    headcount = str(tool_input.get("headcount") or "").strip()
    keywords = str(tool_input.get("keywords") or "").strip()
    # #3707 (R2 07/10) — LA TECHNO N'EST PAS UN NOM. Le registre lit `keywords` comme une raison
    # sociale (secteur ET nom filtrés) : « Java » y rendait 0 banque, et Laura concluait « pas de
    # compte bancaire clair ». La techno a sa propre porte, nommée non appliquée ; une techno qui
    # arrive quand même dans `keywords` est REPRISE là (jamais utilisée pour filtrer un nom).
    # #4437 — un libellé libre (« recrutement React ») est rattaché au signal le plus proche et le dit.
    signal_attachment = attach_signals(tool_input.get("signals"), _DISCOVER_SIGNALS)
    signals = signal_attachment.signals
    technologies, keywords = _split_technologies(
        tool_input.get("technologies"),
        keywords,
        reclassify=bool(sectors or department or region or tool_input.get("city")),
        # #4438.1 — « qui recrutent en data » : le mot est une compétence lue dans les offres, jamais un nom.
        hiring="hiring" in signals,
    )
    # #4438.1 / #4408.1 — « qui recrutent <métier> » (« data », « des développeurs ») : le métier devient un FILTRE
    # d'offres réel (intitulés lus par le moteur de Découvrir), plus un simple réordonnancement du registre.
    hiring_trade, hiring_trade_terms = (
        trade_offer_terms([*demand_trades(tool_input.get("trades")), *technologies])
        if "hiring" in signals
        else (None, [])
    )
    if hiring_trade_terms:
        others = [tech for tech in technologies if trade_offer_terms([tech])[0] is None]
        technologies = [*hiring_trade_terms, *others][:HIRING_TRADE_MAX_TERMS]
    exclude_sectors = [
        sector
        for sector in _pick_known(tool_input.get("exclude_sectors"), (*_DISCOVER_SECTORS, *_SEARCH_NAF_SECTORS))
        if sector not in sectors
    ]
    # #3983.3 — la base de la zone. `presence` est le défaut du registre : elle ne
    # pose aucun filtre. Sans zone, `headquarters` n'a rien à baser : NOMMÉ.
    site_basis = str(tool_input.get("site_basis") or "").strip()
    if site_basis not in ("headquarters", "presence"):
        site_basis = ""
    if not (2 <= len(department) <= 3):
        department = ""
    # #3762 — une ville n'est JAMAIS devinée par le modèle : résolue ici par la
    # source officielle, jamais par sa mémoire d'un numéro de département.
    city = str(tool_input.get("city") or "").strip()
    city_not_resolved = ""
    # #3876.5 — la commune RÉSOLUE, passée telle quelle au registre (`DiscoverFilters.city`),
    # comme le champ « Ville » de Découvrir : jamais élargie à son département.
    resolved_city = ""
    place_note: dict[str, Any] = {}  # #4429.6 — corrigée / homonyme, dit par `place_line`
    if city and not department:
        # #3759.3 — journalisé : cette étape précède le budget de la recherche
        # (`started_at` plus bas) et n'avait aucune mesure propre. `geo-communes`
        # borne déjà SON appel réseau à 6 s (`_fetch`, `data_sources/geo_communes.py`) ;
        # ce log confirme que cette étape reste bien en deçà, plutôt que de le supposer.
        city_resolution_started_at = time.monotonic()
        resolved_city = await _resolve_city_commune_name(city, place_note) or ""
        logger.info(
            "run_account_search: ville « %s » résolue en %s ms (commune %s)",
            city,
            round((time.monotonic() - city_resolution_started_at) * 1000),
            resolved_city or "—",
        )
        if not resolved_city:
            city_not_resolved = city
    if headcount not in _HEADCOUNT_BOUNDS:
        headcount = ""
    # #4429.3 — un rayon demandé, sur les seuls paliers partagés ; une autre valeur ne se devine pas. #4641 (Louis
    # 27/10) — sans rayon (ou un rayon hors liste, ignoré), une ville seule part à 25 km, comme à Découvrir.
    raw_radius = tool_input.get("radius_km")
    if isinstance(raw_radius, (int, float)) and not isinstance(raw_radius, bool) and int(raw_radius) in LAURA_RADIUS_KM:
        radius_km = int(raw_radius)
    elif "radius_km" in tool_input and raw_radius is None:
        # Un rayon RETIRÉ (« finalement Toulouse seule », `None` posé par l'affinage) : la ville seule, sans défaut.
        radius_km = 0
    else:
        radius_km = DEFAULT_CITY_RADIUS_KM
    # #3941.1 — « startup », « jeune entreprise » : le même préréglage que le chip
    # « Startup » de Découvrir (GA-26, une seule définition). Un mot inconnu de
    # `_DISCOVER_COMPANY_PROFILES` n'est jamais deviné : il reste vide.
    company_profile = str(tool_input.get("company_profile") or "").strip()
    if company_profile not in _DISCOVER_COMPANY_PROFILES:
        company_profile = ""
    # #4408 — « pas de gros process achat » : valeur hors liste fermée = non posée (jamais devinée).
    purchasing_process = str(tool_input.get("purchasing_process") or "").strip()
    if purchasing_process not in PURCHASING_PROCESS_VALUES:
        purchasing_process = ""
    # #4408.1 — recette prod 25/10 : le modèle oubliait le paramètre ; la consigne dite par la personne est lue en code.
    if not purchasing_process and (turn := current_turn_thread()) is not None and light_purchasing_asked(*turn):
        purchasing_process = "light"

    # #4438.1 — « qui recrutent en data » sans zone ni secteur : la compétence EST le critère (moteur d'offres).
    hiring_skill = bool(technologies) and "hiring" in signals
    # #4408.1 (recette prod 26/10) — « petites structures sans gros process achat » SANS territoire ni secteur : Laura
    # AGIT. Le périmètre le plus large qu'elle sait servir (toute la France, tranche de départ posée) part et se DIT
    # (`default_scope`), au lieu de l'erreur « il manque une tranche d'effectif… » (0 compte sur 10).
    default_scope: dict[str, str] | None = None
    if purchasing_process == "light" and not (
        sectors or department or resolved_city or region or keywords or headcount or company_profile or hiring_skill
        or signals
    ):
        headcount = DEFAULT_LIGHT_HEADCOUNT
        default_scope = {
            "headcount": headcount,
            "message": (
                f"Aucun territoire ni secteur donné : périmètre posé = toute la France, structures de {headcount} "
                "salariés (les groupes et ETI à process d'achat lourd sont écartés et listés). Dis-le en une ligne "
                "en tête de réponse ; ne demande rien."
            ),
        }
    if not (sectors or department or resolved_city or region or keywords or headcount or company_profile or hiring_skill):
        if signals:
            # #2892 — recette 26/09 : un signal seul n'a rien d'autre à
            # interroger ICI (le registre ne le sait pas faire) — rediriger
            # plutôt que de rendre un faux zéro après avoir cherché sans lui.
            return {
                "error": (
                    "Ce tour d'horizon en conversation ne sait pas filtrer par signal "
                    "d'intention (recrutement, appel d'offres public en cours, marché public remporté) : il interroge "
                    "le registre public, pas le moteur de signaux. Utilise `find_accounts` pour "
                    "ouvrir Découvrir avec ce signal actif, ou précise un secteur, un "
                    "département ou un effectif pour un tour d'horizon ici."
                ),
                **error_envelope(
                    status=ToolResultStatus.NOT_COVERED,
                    result_type="account_list",
                    error_code="signals_not_supported",
                    suggested_next_step="Utilise find_accounts pour ouvrir Découvrir avec ce signal actif.",
                ).to_wire(),
            }
        city_reason = (
            f"« {city_not_resolved} » n'a pas été reconnue comme une commune (source "
            "indisponible, ou aucune correspondance exacte) : précise le département. "
        ) if city_not_resolved else ""
        return {
            "error": (
                city_reason
                + "Aucun critère exploitable. Précise au moins un secteur, un département, une "
                "tranche d'effectif ou une raison sociale avant de lancer le tour d'horizon."
            ),
            **error_envelope(
                status=ToolResultStatus.INVALID_INPUT,
                result_type="account_list",
                error_code="missing_search_criteria",
                suggested_next_step="Ajoute un secteur, un département, un effectif ou une raison sociale.",
            ).to_wire(),
        }

    raw_limit = tool_input.get("limit")
    limit = (
        raw_limit if isinstance(raw_limit, int) and not isinstance(raw_limit, bool) else _ACCOUNT_SEARCH_DEFAULT_ITEMS
    )
    limit = max(1, min(limit, _ACCOUNT_SEARCH_MAX_ITEMS))
    # #4408.2 — le volume DEMANDÉ (« 10 comptes ») gagne sur le défaut de 8 : rendre moins puis dire « seules 8
    # sur 10 » serait un manque fabriqué par le défaut, pas par le marché.
    asked_volume = _requested_count(tool_input)
    if asked_volume is not None:
        limit = max(limit, min(asked_volume, _ACCOUNT_SEARCH_MAX_ITEMS))
    # #4408.1 — des comptes seront RETIRÉS après la lecture (process d'achat lourd, secteurs exclus, comptes déjà
    # écartés) : le registre est lu plus loin dans son classement, sinon le volume demandé fond (10 → 1). Le
    # rendu reste coupé à ``limit`` ; les retirés restent à part et ne comptent jamais pour l'atteindre.
    fetch_limit = limit
    if purchasing_process or tool_input.get("exclude_sectors") or tool_input.get("excluded_sirens"):
        fetch_limit = min(limit * _ACCOUNT_SEARCH_OVERFETCH, _ACCOUNT_SEARCH_OVERFETCH_MAX)

    # #2299.63 — les SIREN que la personne a déjà écartés PLUS TÔT dans cette
    # conversation. Un filtre sur CE rendu, jamais une écriture : le registre
    # et son classement restent intacts, seule la LISTE REMISE au modèle change.
    raw_excluded = tool_input.get("excluded_sirens")
    excluded_sirens = (
        {str(value).strip() for value in raw_excluded if isinstance(value, str) and str(value).strip()}
        if isinstance(raw_excluded, list)
        else set()
    )

    # #3704.4 — la reprise ciblée d'une source : des jetons opaques, re-dérivés ici en sources
    # réelles (un jeton inconnu est ignoré, jamais deviné — le résultat le dit).
    from app.routers.discover import sources_from_resume_tokens

    raw_resume = tool_input.get("resume_sources")
    resume_tokens = [str(v) for v in raw_resume if isinstance(v, str)] if isinstance(raw_resume, list) else []
    only_sources = sources_from_resume_tokens(resume_tokens) if resume_tokens else ()

    # #3705 — les secteurs d'écran passent par `sectors` (section NAF) ; ceux de
    # `_SEARCH_NAF_SECTORS` par leur LISTE de codes NAF. Les deux ensemble : deux
    # sous-recherches fusionnées, jamais un secteur perdu.
    rail_sectors = [sector for sector in sectors if sector in _DISCOVER_SECTORS]
    naf_sectors = [sector for sector in sectors if sector in _SEARCH_NAF_SECTORS]

    # #3983.3 — la base de la zone n'a d'effet que sur une zone (département ou région).
    site_basis_applied = site_basis if site_basis and (department or region) else ""

    # Recette 21/10 B.4 — sans SECTEUR, une compétence est une recherche par les offres (moteur de Découvrir).
    # Avec un secteur, le comportement #3707 reste : le secteur filtre, la techno est nommée non appliquée
    # (le moteur par compétence ignore le secteur : l'y envoyer ferait perdre « dans la banque »).
    skill_engine = bool(technologies) and not (rail_sectors or naf_sectors)
    if skill_engine:
        # #4421.3 — RÉFUTÉ en prod le 23/10 (« comptes qui recrutent des développeurs Java en IDF » → 2 comptes) : le
        # moteur était lu pour 8, AVANT les retraits (ESN connues, hors demande). Une dizaine au moins, lue plus loin.
        from app.services.criteria_referential import CRITERIA_WIDEN_MIN_RESULTS

        limit = max(limit, min(CRITERIA_WIDEN_MIN_RESULTS, _ACCOUNT_SEARCH_MAX_ITEMS))
        fetch_limit = max(fetch_limit, min(limit * 2, _ACCOUNT_SEARCH_OVERFETCH_MAX))

    def _base_filters() -> Any:
        base = DiscoverFilters()
        if department:
            base.department = department
        if resolved_city:
            base.city = resolved_city
            if radius_km:
                base.radiusKm = float(radius_km)
        if region:
            base.regions = region
        if keywords:
            # Le registre lit ce champ comme une RAISON SOCIALE (`discover.py:250-258`) :
            # l'outil le dit à sa manière dans sa description, pour qu'aucune activité
            # n'y soit routée.
            base.freetext = keywords
        if skill_engine:
            # Recette 21/10 B.4 (K.6, Kevin) — « qui recrute des développeurs Java à Lille » passe par le MÊME
            # moteur que Découvrir : la compétence TROUVE les comptes par leurs offres (COMPETENCE-TROUVE),
            # au lieu de lister le secteur en avouant qu'aucun n'a d'offre Java confirmée.
            base.technologiesObserved = list(technologies)
        if headcount:
            low, high = _HEADCOUNT_BOUNDS[headcount]
            base.headcountMin = low
            base.headcountMax = high
        if site_basis_applied == "headquarters":
            base.siteBasis = "headquarters"
        if company_profile == "startup":
            base.createdAfter = _years_ago_iso(_STARTUP_PROFILE_AGE_YEARS)
            base.legalCategory = _STARTUP_PROFILE_LEGAL_CATEGORY
            base.companyCategory = [_STARTUP_PROFILE_COMPANY_CATEGORY]
        return base

    from app.services.application_sector_naf import naf_codes_for_sectors

    filter_groups: list[Any] = []
    if hiring_trade_terms and skill_engine:
        # #4438.1 — une lecture du moteur par paire d'intitulés (sa borne d'appels), fusionnées par SIREN.
        from app.services.discover_skill_offers import SKILL_MAX_TERMS

        for start in range(0, len(technologies), SKILL_MAX_TERMS):
            group = _base_filters()
            group.technologiesObserved = technologies[start : start + SKILL_MAX_TERMS]
            filter_groups.append(group)
    elif rail_sectors or not naf_sectors:
        group = _base_filters()
        if rail_sectors:
            group.sectors = rail_sectors
        filter_groups.append(group)
    if naf_sectors:
        group = _base_filters()
        group.nafCode = ",".join(naf_codes_for_sectors(naf_sectors))
        filter_groups.append(group)

    # #4429.3 (recette 25/10) — un rayon demandé ne rend JAMAIS moins que la ville seule : le cercle du registre
    # écarte des comptes que la ville seule rendait (« 50 km autour d'Albi » → 1 compte, « Albi » → 7). Chaque groupe
    # part donc aussi sans rayon, SANS paliers (`zoneStrict` : le rayon est déjà l'élargissement demandé), et les
    # résultats se fusionnent par SIREN. Le cercle reste en tête de groupe : ses comptes gardent leur place.
    if resolved_city and radius_km:
        filter_groups += [group.model_copy(update={"radiusKm": None, "zoneStrict": True}) for group in filter_groups]

    # LUDOVIC-D LC.6 — les métiers de la DEMANDE affinent ceux du profil : le moteur de Découvrir ne
    # garde alors que les offres dans ces métiers (même contrat que le cadrage d'un run).
    trades = demand_trades(tool_input.get("trades"))
    search_profile = profile_for_demand(profile_data, trades)

    # #2852.24/.36 — chronométré, et borné : au-delà du budget, un statut
    # `timeout` NOMMÉ, distinct d'une vraie panne (`provider_error`) — les deux
    # se confondaient avant (`except Exception` seul), et Laura ne pouvait
    # jamais dire « le registre est juste LENT » à « le registre est CASSÉ ».
    started_at = time.monotonic()
    try:
        response = await asyncio.wait_for(
            _registry_for_groups(
                discover_registry,
                DiscoverRegistryRequest,
                filter_groups,
                fetch_limit,
                search_profile,
                only_sources,
                space_key=space_key,
                # #4438.1 — les intitulés du métier SONT déjà sa famille : jamais élargis au web.
                strict=bool(hiring_trade_terms and skill_engine),
            ),
            timeout=_account_search_budget_s(),
        )
    except TimeoutError:
        duration_ms = round((time.monotonic() - started_at) * 1000)
        logger.warning("run_account_search: registre au-delà du budget (%s ms)", duration_ms)
        return {
            "error": (
                "Le registre des entreprises n'a pas répondu à temps. Je n'ai donc aucun compte "
                "à te montrer — je n'en invente pas. On peut réessayer, ou passer par l'écran "
                "Découvrir."
            ),
            **ToolResultEnvelope(
                status=ToolResultStatus.TIMEOUT,
                result_type="account_list",
                error_code="registry_timeout",
                suggested_next_step="Réessaie dans un instant, ou passe par l'écran Découvrir.",
                duration_ms=duration_ms,
            ).to_wire(),
        }
    except Exception as exc:  # noqa: BLE001 — la raison est remontée telle quelle
        # JAMAIS de résultat inventé : le registre n'a pas répondu, on le DIT.
        logger.warning("run_account_search: registre injoignable: %s", exc)
        return {
            "error": (
                "Le registre des entreprises n'a pas répondu. Je n'ai donc aucun compte à te "
                "montrer — je n'en invente pas. On peut réessayer, ou passer par l'écran "
                "Découvrir."
            ),
            **error_envelope(
                status=ToolResultStatus.PROVIDER_ERROR,
                result_type="account_list",
                error_code="registry_unavailable",
                suggested_next_step="Réessaie dans un instant, ou passe par l'écran Découvrir.",
            ).to_wire(),
        }

    if department and not resolved_city and not region and not only_sources:
        # #4408.1 — le département ne s'arrête plus à lui-même : sa région est parcourue dans ce tour, puis STOP.
        response = await _widen_department_to_region(
            response,
            department=department,
            filter_groups=filter_groups,
            registry_args=(discover_registry, DiscoverRegistryRequest),
            fetch_limit=fetch_limit,
            search_profile=search_profile,
            only_sources=only_sources,
            space_key=space_key,
            strict=bool(hiring_trade_terms and skill_engine),
        )
    candidates = getattr(response, "candidates", None) or []
    if excluded_sirens:
        candidates = [
            row
            for row in candidates
            if not (isinstance(row, Mapping) and str(row.get("siren") or "").strip() in excluded_sirens)
        ]
    # #3983 (reste, Louis 11/10) — une holding hors zone écartée au profit de sa filiale SOURCÉE
    # dans la zone (`holding_subsidiary.redirect_holdings`, posé par le registre) : elle sort de la
    # sélection AVANT le contrôle de la demande (jamais rangée « hors demande »), NOMMÉE à part ;
    # la filiale garde la place et dit son groupe.
    candidates, holdings_redirected, subsidiary_of = _split_redirected_holdings(
        [row for row in candidates if isinstance(row, Mapping)]
    )
    # LUDOVIC-D LC.6 — un secteur demandé DANS la cible du profil l'affine, il ne la lève pas : « des
    # industrielles » pour Stelya garde le filtre cible de Découvrir (l'agroalimentaire hors profil sort).
    out_of_profile: list[str] = []
    if demand_refines_profile(sectors, profile_data):
        candidates, out_of_profile = keep_profile_target(candidates, profile_data)
    # #3705 — chaque résultat est CONTRÔLÉ contre la demande (secteur, taille) avant
    # d'entrer dans la sélection : un voisin hors demande se range à part, il ne
    # complète jamais le nombre demandé. Inconnu ≠ conforme : gardé, nommé non vérifié.
    candidates, out_of_scope, activity_unverified, headcount_unverified = _split_by_scope(
        [row for row in candidates if isinstance(row, Mapping)], sectors=sectors, headcount=headcount
    )
    # #3706 — les secteurs EXCLUS se retirent de la sélection (jamais proposés « à part » :
    # la personne les a refusés), et le retrait est compté, pas silencieux.
    candidates, excluded_by_sector = _drop_excluded_sectors(candidates, exclude_sectors)
    # #4055.1 — une ESN du référentiel connu n'est jamais une cible de ce tour d'horizon
    # (partenaire potentiel, pas un client final) : retirée avant la sélection finale, comptée.
    candidates, esn_excluded = _drop_known_esn(candidates)
    # #4408 — la contrainte « petite structure » est APPLIQUÉE ici, par le code : les comptes à process
    # d'achat lourd probable sortent de la sélection (et ne comptent jamais pour atteindre le nombre
    # demandé), rendus à part avec leur raison. Sans aucune donnée de taille, le compte reste, et on le dit.
    heavy_purchasing: list[dict[str, str]] = []
    purchasing_unverified = 0
    if purchasing_process == "light":
        candidates, heavy_purchasing = split_heavy_purchasing(candidates)
        purchasing_unverified = sum(1 for row in candidates if not has_size_data(row))
    # #4421.3 / #4408.1 (recette prod 25/10) — « des comptes qui recrutent X » : un compte listé porte l'OFFRE datée qui
    # le justifie. Sans elle il se range à part (nommé, raison dite) et ne compte jamais dans le nombre demandé.
    without_matching_offer: list[dict[str, str]] = []
    if hiring_skill and skill_engine:
        candidates, without_matching_offer = _split_by_dated_offer(candidates)
    # #2299.3/.4/.6/.7 — mélange de sources et dédoublonnage : un candidat
    # partagé par deux entrées du registre (même identifiant canonique) est
    # fusionné SANS perdre de preuve ; deux candidats seulement proches par
    # le nom restent séparés et portent une hypothèse de doublon nommée —
    # jamais fusionnée automatiquement (2299.5, doctrine « on ne fusionne
    # jamais »). L'ordre (déjà classé par score) survit.
    from app.services.compilers.blending import blend_accounts

    candidates = blend_accounts([row for row in candidates if isinstance(row, Mapping)])
    offer = str(tool_input.get("offer") or "").strip()[:80]
    offer_terms = _offer_terms(offer)
    items = [
        item
        for row in candidates
        if isinstance(row, Mapping) and (item := _search_item(row, offer=offer, offer_terms=offer_terms))
    ]
    # #4434.3 — une ESN n'est JAMAIS un compte cible : « des comptes qui cherchent du React » rendait deux
    # ESN concurrentes. Elles sortent de la liste et sont rangées à part, nommées concurrentes. Une recherche par
    # NOM (`keywords`) garde l'entreprise demandée : l'utilisateur l'a nommée.
    competitors_aside: list[dict[str, Any]] = []
    if not keywords:
        competitors_aside = [item for item in items if item.get("relation_type") == "competing_esn"]
        if competitors_aside:
            items = [item for item in items if item.get("relation_type") != "competing_esn"]
    for item in items:
        holding_name = subsidiary_of.get(item["siren"])
        if holding_name:
            # Lien capitalistique SOURCÉ (arête registre) : un fait, pas un indice de mandataire.
            item["group_link"] = {"observed_entities": [holding_name], "kind": "capital_link"}
            item["group_label"] = "Filiale de " + holding_name
    # LUDOVIC-D LC.6 — l'ordre de « Comptes qui recrutent » : une offre datée dans les métiers demandés (ou
    # ceux du profil) d'abord, puis un autre signal daté, puis le reste. Tri stable, rien n'est retiré.
    if trades or (search_profile or {}).get("placedRoles"):
        items = order_for_call(items, trades)
    # #3705.5 — liens capitalistiques (Pappers) pour les lignes AFFICHÉES seulement.
    await attach_group_links(items[:limit])
    # #4408.2 — « petite structure sans gros process achat » : un compte rattaché à un groupe (personne morale
    # dirigeante ou lien capitalistique) n'en est pas une. Mis à part, sa barrière achats NOMMÉE, il ne compte
    # jamais pour atteindre le nombre demandé (même règle que les « gros process achat » ci-dessus).
    group_attached: list[dict[str, str]] = []
    if purchasing_process == "light":
        kept_items = []
        for item in items:
            entities = [str(e) for e in (item.get("group_link") or {}).get("observed_entities") or [] if str(e)]
            if not entities:
                kept_items.append(item)
                continue
            group_attached.append(
                {
                    "name": item["name"],
                    "siren": item["siren"],
                    "reason": "Rattaché au groupe " + ", ".join(entities[:3]) + " : ses achats peuvent passer par "
                    "le référencement du groupe (barrière achats du groupe, pas d'une petite structure).",
                }
            )
        items = kept_items
        # #4408.1 (re-recette 26/10) — le critère PÈSE en sélection : les petites structures dont la taille est
        # établie passent d'abord (ordre stable), les comptes sans donnée de taille suivent, étiquetés non vérifiés.
        size_known = {str(row.get("siren") or ""): has_size_data(row) for row in candidates if isinstance(row, Mapping)}
        for item in items:
            item["purchasing_verified"] = size_known.get(str(item.get("siren") or ""), False)
        items = sorted(items, key=lambda item: not item["purchasing_verified"])
    # #5013.2 — « les comptes les plus faciles où entrer » : tri stable par classe d'accès A→D, les classes
    # non estimables à la FIN (jamais rangées au hasard dans l'une des quatre).
    sorted_by_access = str(tool_input.get("sort_by") or "").strip() == "access"
    if sorted_by_access:
        items = sorted(items, key=lambda item: _ACCESS_CLASS_ORDER.get(str(item.get("access_class") or ""), 4))
    # #5013 (issue rouverte) — « 8 comptes en classe A » alors que les cartes montraient A, C, B : le texte de Laura
    # et les cartes viennent désormais de la MÊME donnée — le compte par classe est calculé sur les comptes RENDUS.
    access_summary, access_line = _access_summary_of(items[:limit])
    # #4429.3 — le palier de zone appliqué par le registre (mêmes paliers que Découvrir), dit en une
    # ligne, et chaque compte élargi étiqueté. Absent quand rien n'a été élargi.
    zone_widening = getattr(response, "zoneWidening", None)
    zone_widening = dict(zone_widening) if isinstance(zone_widening, Mapping) and zone_widening else None
    zone_line = ""
    if zone_widening:
        zones = {str(row.get("siren") or ""): row.get("zone") for row in candidates if isinstance(row, Mapping)}
        for item in items:
            if label := candidate_zone_label(zones.get(item["siren"]), str(zone_widening.get("place") or "")):
                item["zone_label"] = label
        # #4429.3 (recette 23/10) — les nombres de la ligne sont ceux de la liste RENDUE (après les filtres).
        around = sum(1 for item in items if zones.get(item["siren"]))
        # #4429.3 (recette 25/10) — un palier TENTÉ se dit même quand rien d'élargi ne survit aux retraits.
        zone_line = laura_zone_line(zone_widening, len(items) - around, around)
    # #4429.3 (re-recette prod 26/10) — rien d'élargi : la zone CHERCHÉE se dit pourtant quand l'utilisateur a posé un
    # rayon (ou la ville seule), ou quand la liste est courte — « 7 comptes sur 10 » sans rayon ni palier nommés.
    reach_line = ""
    if resolved_city and not zone_widening and ("radius_km" in tool_input or len(items) < limit):
        reach_line = laura_reach_line(resolved_city, radius_km, len(items[:limit]))

    out: dict[str, Any] = {
        **({"zone_widening": zone_widening, "zone_line": zone_line} if zone_widening else {}),
        **({"reach_line": reach_line} if reach_line else {}),
        **_skill_widening_fields(getattr(response, "query", None)),
        # #4429.6 — « Toulouse (corrigé depuis « Tolouse ») » : la correction ou l'homonyme se DIT.
        **({"place_resolution": place_note, "place_line": place_resolution_line(place_note)} if place_note else {}),
        "items": items[:limit],
        **({"access_summary": access_summary, "access_line": access_line} if access_line else {}),
        **({"competitors_aside": competitors_aside[:limit]} if competitors_aside else {}),
        # Un rang n'est jamais nu : les critères qui l'ORDONNENT sont rendus avec
        # lui, et la carte `account_ranking` les exige (`axes`, min 1).
        "axes": _search_axes(sectors, department, headcount, keywords, region, city=resolved_city, offer=offer),
        "criteria": {
            **({"sectors": sectors} if sectors else {}),
            **({"department": department} if department else {}),
            **({"city": resolved_city} if resolved_city else {}),
            **({"radius_km": radius_km} if resolved_city and radius_km else {}),
            **({"exclude_sectors": exclude_sectors} if exclude_sectors else {}),
            **({"region": region} if region else {}),
            **({"headcount": headcount} if headcount else {}),
            **({"keywords": keywords} if keywords else {}),
            **({"purchasing_process": purchasing_process} if purchasing_process else {}),
            **({"technologies": technologies} if technologies and skill_engine else {}),
            # #3866 — l'offre qui sert de lentille à l'adéquation, échoée comme tout critère.
            **({"offer": offer} if offer else {}),
            **({"site_basis": site_basis_applied} if site_basis_applied == "headquarters" else {}),
        },
        # Mesuré, pas deviné : la route ne débite rien (voir RUN_ACCOUNT_SEARCH_TOOL).
        **({"default_scope": default_scope} if default_scope else {}),
        "cost_credits": 0,
        "next_gestures": next_gestures(company=keywords),
        # #3866.1 (BEL-LAU-1008-015, recette bêta 08/10) — « L'adresse, l'ancienneté ou
        # l'existence juridique d'une société ne suffisent pas à la recommander ». Les `axes`
        # ci-dessus (`_search_axes`) sont les CRITÈRES de la recherche, pas une preuve d'intérêt :
        # ce tour d'horizon interroge le registre public (secteur, zone, effectif, raison
        # sociale), jamais un signal de demande précis. Toujours posée, jamais seulement sur
        # erreur : un critère démographique se confond avec une raison métier dès le premier
        # tour si rien ne le nomme.
        "commercial_fit_note": (
            "Ces critères (secteur, zone, effectif, raison sociale, établissement actif au "
            "registre) ont SÉLECTIONNÉ les comptes ci-dessus ; ils ne prouvent pas qu'un compte "
            "précis correspond à une demande métier donnée (ex. une offre Data/BI, du staffing "
            "bancaire). Avant de présenter un compte comme une priorité pour CETTE demande, "
            "nomme l'élément qui la justifie réellement (signal observé, projet, demande, "
            "relation, organisation documentée) — un simple secteur partagé ne suffit pas. Sans "
            "cet élément, dis-le plutôt que d'inventer l'adéquation, et ne compte pas ce compte "
            "pour atteindre le nombre demandé."
        ),
        # #3866 (décision Louis 10/10) — la taxonomie de relation, posée au modèle : le registre
        # public ne la porte pas, donc l'adéquation se vérifie AVANT de recommander.
        "relation_types": list(_RELATION_TYPES),
        "relation_type_note": (
            "Chaque ligne porte `relation_type` (calculé sur la forme juridique et l'activité) : reprends-le "
            "tel quel, sans le corriger de mémoire. Un compte « undetermined » se dit à confirmer. Chaque compte relève d'UN de quatre types de relation : client final "
            "(achète la prestation), ESN concurrente ou interne (vend la même chose, ou entité "
            "informatique interne d'un groupe), partenaire (sous-traitance, co-traitance, "
            "alliance), intermédiaire (portage salarial, cabinet de référencement). Le registre ne "
            "dit pas lequel : AVANT de recommander un compte, vérifie l'adéquation commerciale "
            "avec son type (une ESN concurrente ou un intermédiaire n'est pas un client final) ; "
            "sans élément qui le prouve, dis que le type est à confirmer, ne le devine pas, et ne "
            "range jamais deux types dans la même liste sans les nommer."
        ),
    }
    if size_line := _size_line(candidates, {item["siren"] for item in out["items"]}):
        # #4408.1 — la taille des comptes rendus est ANNONCÉE (c'était l'autre moitié du point).
        out["size_line"] = size_line
    if any(item.get("widened") for item in out["items"]):
        # #4433 (Louis 21/10) — l'élargissement est fait dans le CODE ; Laura le DIT, elle ne le propose pas.
        out["widening_note"] = (
            "Moins de 10 comptes répondaient exactement : la recherche s'est élargie d'elle-même au palier voisin "
            "(compétence proche, secteur voisin ou taille voisine). Dis-le en une ligne au-dessus de la liste, "
            "garde l'étiquette `widened` de chaque compte élargi, présente les comptes exacts d'abord, et ne demande "
            "jamais s'il faut élargir."
        )
    if excluded_by_sector:
        out["excluded_by_sector_count"] = excluded_by_sector
    if without_matching_offer:
        out["without_matching_offer"] = without_matching_offer[:_OUT_OF_SCOPE_MAX]
        out["without_matching_offer_note"] = (
            "Ces comptes ne montrent aucune offre datée correspondant à la demande : ils ne figurent pas dans la liste "
            "principale et ne comptent pas dans le nombre demandé. Dis-le en une ligne, sans les présenter comme "
            "recrutant."
        )
    if heavy_purchasing:
        # #4408 — second bloc « Écartés : gros process achat », chaque compte avec sa raison NOMMÉE.
        out["heavy_purchasing_excluded"] = heavy_purchasing[:_OUT_OF_SCOPE_MAX]
        out["heavy_purchasing_excluded_count"] = len(heavy_purchasing)
        out["heavy_purchasing_excluded_note"] = (
            "Écartés : gros process achat. Ces comptes sont sortis de la sélection (contrainte « petite "
            "structure ») et ne comptent PAS pour atteindre le nombre demandé : présente-les dans un bloc à "
            "part « Écartés : gros process achat », chacun avec sa raison, sans les recommander."
        )
    if group_attached:
        out["group_attached_excluded"] = group_attached[:_OUT_OF_SCOPE_MAX]
        out["group_attached_excluded_count"] = len(group_attached)
        out["group_attached_excluded_note"] = (
            "Mis à part : rattachés à un groupe. Ces comptes ne sont pas des petites structures autonomes : ils "
            "sortent de la sélection et ne comptent PAS pour atteindre le nombre demandé. Présente-les dans un "
            "bloc à part « Rattachés à un groupe », chacun avec sa barrière achats (`reason`), sans les recommander."
        )
    if purchasing_unverified:
        out["purchasing_process_unverified_count"] = purchasing_unverified
        out["purchasing_process_unverified_note"] = (
            f"{purchasing_unverified} compte(s) de la sélection n'ont aucune donnée de taille au registre : "
            "gardés, mais leur process d'achat n'est PAS vérifié. Dis-le, sans les présenter comme légers."
        )
    if sorted_by_access:
        out["sorted_by"] = "access"
        out["sorted_by_note"] = (
            "Classés du plus accessible (A) au plus verrouillé (D), les comptes dont la classe n'est pas estimable "
            "en dernier. Cite la classe et sa raison (`access_reason`) : ne dis jamais « facile » sans elle."
        )
    if trades:
        out["criteria"]["trades"] = trades
    if out_of_profile:
        # LUDOVIC-D LC.6 — jamais silencieux : le retrait hors cible du profil se compte et se nomme.
        out["out_of_profile_count"] = len(out_of_profile)
        out["out_of_profile_note"] = (
            f"{len(out_of_profile)} entreprise(s) hors des secteurs cibles de ton profil écartée(s) "
            "(ex. " + ", ".join(sorted(set(out_of_profile))[:3]) + ") : dis-le en une ligne."
        )
    if esn_excluded:
        # #4055.1 — jamais silencieux : le retrait se nomme, comme les autres écarts ci-dessous.
        out["esn_excluded_count"] = esn_excluded
        out["esn_excluded_note"] = (
            f"{esn_excluded} entreprise(s) du registre public reconnue(s) comme ESN ont été écartées de "
            "cette sélection : un concurrent potentiel (co-traitance, sous-traitance) n'est jamais une "
            "cible de ce tour d'horizon."
        )
    if region or department or resolved_city:
        # #3983 (Louis 11/10) revient sur F21/3db6babee4, délibérément : la zone filtre
        # l'IMPLANTATION par défaut, le siège seulement sur demande (`site_basis`).
        # « Ça dépend du type de boîte : une holding à Paris dont les boîtes sont dans
        # le Sud, ce sont les boîtes du Sud qui comptent, là où les gens recrutent. »
        # La note dit la base RÉELLEMENT appliquée, jamais « siège » quand c'est l'implantation.
        if site_basis_applied == "headquarters":
            out["geography_basis"] = "headquarters"
            out["geography_note"] = (
                "La zone filtre sur l'adresse du SIÈGE enregistré au registre (demandé : `site_basis`) : "
                "une entreprise qui n'a qu'un établissement dans la zone en est écartée. Elle ne dit rien de "
                "l'équipe locale ni du périmètre de mission : si la demande porte sur l'équipe, dis que ce "
                "n'est pas mesuré ici."
            )
        else:
            out["geography_basis"] = "presence"
            out["geography_note"] = (
                "La zone filtre sur l'IMPLANTATION : une entreprise y entre dès qu'elle a un établissement "
                "actif dans la zone, que son siège y soit ou non (`location` dit, par compte, ce que le "
                "registre prouve). Pour ne garder que les entreprises dont le siège est dans la zone, "
                "relance avec `site_basis: \"headquarters\"`. L'effectif de l'équipe sur place n'est pas "
                "mesuré : si la demande porte sur l'équipe, dis-le."
            )
    if holdings_redirected:
        out["holdings_redirected"] = holdings_redirected
        out["holdings_redirected_note"] = (
            "Écartées de la sélection : "
            + ", ".join(entry["holding"] for entry in holdings_redirected[:5])
            + ". Ce sont des holdings dont le siège est hors de la zone ; leur filiale implantée dans la "
            "zone (lien capitalistique sourcé) est proposée à leur place, parce que c'est elle qui recrute "
            "et achète sur place. Dis-le en une ligne, avec la filiale en face de sa holding."
        )
    group_linked = [item for item in items if item.get("group_link")]
    if group_linked:
        out["group_link_count"] = len(group_linked)
    if out_of_scope:
        out["out_of_scope"] = out_of_scope[:_OUT_OF_SCOPE_MAX]
        out["out_of_scope_count"] = len(out_of_scope)
        out["out_of_scope_note"] = (
            "Ces entreprises ont répondu au registre mais sortent de la demande (secteur ou effectif) : "
            "elles ne sont PAS dans la sélection et ne servent pas à atteindre le nombre demandé. "
            "Propose-les à part seulement si la personne veut élargir."
        )
    # #3905.4 (recette R37) — « 5 écartés, 0 retenu » ne se dit jamais en silence : le critère qui a TOUT
    # écarté est nommé en une phrase, sans proposition autour.
    if not items and (out_of_scope or esn_excluded or excluded_by_sector):
        out["no_retained_reason"] = _no_retained_reason(
            out_of_scope, esn_excluded=esn_excluded, excluded_by_sector=excluded_by_sector
        )
        out["no_retained_note"] = (
            "Aucune entreprise n'est retenue : dis `no_retained_reason` en UNE phrase (le critère qui a tout "
            "écarté), sans liste ni proposition autour (ni « Relancer… » ni « Élargir… »)."
        )
    if activity_unverified:
        out["activity_unverified_count"] = activity_unverified
    if headcount_unverified:
        out["headcount_unverified_count"] = headcount_unverified
    if headcount in ("1-9", "10-49", "50-249") and items:
        # #3705.5 (lot RBC) — un lien capitalistique SOURCÉ se dit comme un fait : « Filiale de <groupe> ».
        for item in items[:limit]:
            link = item.get("group_link") or {}
            if link.get("kind") == "capital_link" and link.get("observed_entities"):
                item["group_label"] = "Filiale de " + ", ".join(link["observed_entities"][:3])
        grouped = [item["name"] for item in items[:limit] if item.get("group_link")]
        if grouped:
            out["subsidiary_warning"] = (
                "Rattachement probable à un groupe (une personne morale dirige la société, d'après le "
                "registre) : " + ", ".join(grouped[:5]) + ". Ce ne sont pas des petites entreprises "
                "autonomes : ne les présente pas comme libres de barrières achats sans preuve, et dis que "
                "le groupe n'est pas confirmé."
            )
        out["purchasing_barrier_note"] = (
            "Le registre ne dit pas si une entreprise appartient à un grand groupe : une filiale n'est pas "
            "une petite entreprise autonome, ses achats peuvent passer par le groupe. Explique ces barrières "
            "d'accès sans promettre de contournement, et vérifie le rattachement avant de la présenter "
            "comme libre de barrières."
        )
    if technologies and skill_engine:
        # Recette 21/10 B.4 — la compétence est APPLIQUÉE (moteur de Découvrir : offres datées → employeurs).
        # Chaque compte porte sa preuve (`skillEvidence`) ; une liste vide se dit, elle ne se complète pas.
        out["technologies_applied"] = technologies
        out["technologies_applied_note"] = (
            "La compétence (" + ", ".join(technologies) + ") filtre par les OFFRES récentes qui la citent, comme "
            "Découvrir : ne présente que les comptes rendus, ne dis jamais « aucun n'a d'offre confirmée » pour "
            "une liste qui en porte, et donne le lien `discover_href` pour trier et filtrer sur l'écran."
        )
        discover_href = _discover_full_list_href(out["criteria"]) if isinstance(out.get("criteria"), dict) else None
        if discover_href:
            out["discover_href"] = discover_href
    elif technologies:
        # #3707 — nommé plutôt que silencieusement perdu (même doctrine que `signals_not_applied`).
        out["technologies_not_applied"] = technologies
        out["technologies_not_applied_reason"] = (
            "Le registre public ne lit pas les technologies : la liste est celle du SECTEUR demandé, pas "
            "des entreprises qui utilisent " + ", ".join(technologies) + ". Rends la liste, dis-le en une "
            "ligne, et propose `search_market_memory` (technologie observée dans les offres) pour "
            "resserrer sur la techno."
        )
    if site_basis and not site_basis_applied:
        # #3983.3 — nommé plutôt que silencieusement perdu.
        out["site_basis_not_applied_reason"] = (
            "La base siège/implantation n'a pas été appliquée : elle s'attache à une zone "
            "(département) et aucune n'a été donnée. Dis-le, et demande la zone."
        )
    if signal_attachment.attached:
        out["signals_attached"] = signal_attachment.attached
        out["signals_attached_line"] = signal_attachment.line
    if signal_attachment.unmatched:
        out["signals_unmatched"] = signal_attachment.unmatched
    if signals:
        # #3704 — « donne-moi aussi des besoins » n'est JAMAIS un filtre.
        out["needs_note"] = (
            "Les besoins demandés ne filtrent pas la liste : une entreprise sans besoin ouvert documenté "
            "reste proposée — l'absence de besoin connu n'est pas l'absence de potentiel. Dis, pour "
            "chacune qui en porte, ses demandes actuelles CONNUES (`current_demands`, appels d'offres et "
            "recrutements datés, déjà cherchés sur les premiers rangs) ; pour les autres, UNE phrase "
            "d'ensemble (`current_demands_summary`), jamais une ligne par entreprise."
        )
    # #4438.1 — le recrutement est APPLIQUÉ quand la compétence ou le métier passe par les offres : jamais
    # « non appliqué » pour une liste choisie par ses offres datées.
    unapplied_signals = [s for s in signals if not (s == "hiring" and technologies and skill_engine)]
    if hiring_trade_terms and skill_engine:
        out["hiring_trade_filter"] = {"trade": hiring_trade, "offer_titles": hiring_trade_terms}
        out["hiring_trade_note"] = (
            f"Filtre recrutement APPLIQUÉ : seuls les comptes qui publient des offres récentes en {hiring_trade} ("
            + ", ".join(hiring_trade_terms)
            + ") sont retenus, choisis par leurs offres. Dis-le en une ligne, cite l'offre datée de chaque compte, "
            "et ne dis jamais que le filtre recrutement n'a pas été appliqué."
        )
    if unapplied_signals:
        # #2892 — recette 26/09 : nommé plutôt que silencieusement perdu, même
        # doctrine que `keywords_not_applied` sur `find_accounts` ci-dessus.
        out["signals_not_applied"] = unapplied_signals
        out["signals_not_applied_reason"] = (
            "Les signaux d'intention demandés n'ont pas été appliqués comme FILTRE : ce tour d'horizon "
            "interroge le registre public, pas le moteur de signaux. Les demandes actuelles connues "
            "sont néanmoins INDIQUÉES par entreprise (`current_demands`). Dis-le, et propose "
            "`find_accounts` pour les appliquer réellement comme filtre sur Découvrir."
        )
    if city_not_resolved:
        # #3762 — nommé plutôt que silencieusement perdu, même doctrine que
        # `signals_not_applied`/`technologies_not_applied` ci-dessus.
        out["city_not_resolved"] = city_not_resolved
        out["city_not_resolved_reason"] = (
            f"« {city_not_resolved} » n'a pas été reconnue comme une commune (source indisponible, "
            "ou aucune correspondance exacte) : le département n'a pas été filtré sur cette ville. "
            "Dis-le, et demande le département si la zone est nécessaire."
        )
    raw_degraded = list(getattr(response, "degraded", None) or [])
    degraded = _degraded_without_vendors(raw_degraded)
    if only_sources:
        # #3704.4 — la reprise est DITE : quelles parties ont été relancées, pas lesquelles ont répondu avant.
        out["resumed"] = {
            "sources_count": len(only_sources),
            "message": "Reprise ciblée : seule la partie qui n'avait pas répondu a été réinterrogée.",
        }
    elif resume_tokens:
        out["resume_tokens_unknown"] = "Aucun de ces jetons de reprise n'est connu : la recherche complète a été relancée."
    if degraded:
        # Ce qui a dégradé la recherche est NOMMÉ. Une liste courte sans sa raison
        # se lit comme « le marché est petit », ce qui est faux.
        out["degraded"] = degraded
    # #2852.20 — ce qu'on NE SAIT PAS, jamais le nom d'une source : une limite
    # de capacité (la source n'a rien cherché sur ce critère) et une panne
    # réelle (aucun `kind`) sont deux « inconnues » distinctes, dues même quand
    # d'autres sources ont répondu — pas seulement sur une liste vide.
    unknowns: list[str] = []
    if any(entry.get("kind") == KIND_CAPABILITY for entry in degraded):
        unknowns.append(
            "Au moins une source du registre ne sait pas exprimer ce critère : elle n'a rien "
            "cherché sur ce point, ce n'est pas mesuré."
        )
    if any(entry.get("kind") is None for entry in degraded):
        unknowns.append(
            "Au moins une source du registre n'a pas répondu (panne ou clé absente) : les "
            "résultats peuvent être incomplets sans qu'on sache de combien."
        )
        if items:
            # #3704 — une source en panne n'empêche pas de rendre le reste ; la reprise
            # de la partie manquante est un geste nommé, sans relancer ce qui a répondu.
            # #3704.4 — ET elle vise la source qui n'a pas répondu : des jetons OPAQUES
            # (jamais le nom d'un fournisseur), repris dans `resume_sources`.
            down_tokens = sorted(
                {
                    source_resume_token(str(entry["source"]))
                    for entry in raw_degraded
                    if isinstance(entry, Mapping)
                    and entry.get("kind") is None
                    and entry.get("source") in REGISTRY_SOURCE_NAMES
                }
            )
            out["resume"] = {
                "tool": "run_account_search",
                "refine": True,
                **({"resume_sources": down_tokens} if down_tokens else {}),
                "message": (
                    "Une source n'a pas répondu : le reste est rendu ci-dessus. Pour reprendre la partie "
                    "manquante, relance `run_account_search` avec `refine: true`"
                    + (" et `resume_sources` (les jetons ci-dessus, tels quels)" if down_tokens else "")
                    + " SANS autre changement : seule la source en panne est réinterrogée, celles qui ont "
                    "répondu ne sont pas relancées, les mêmes critères sont gardés et les entreprises déjà "
                    "vues ne reviennent pas (`excluded_sirens`)."
                ),
            }
    caveats: list[str] = []
    has_capability_gap = False
    # #3201 COMPORTEMENT — « réduisent fortement » : un résultat mince mais NON
    # vide se dit et continue, distinct de la relaxation ci-dessous (zéro
    # résultat). `criteria` ne porte que ce qui est réellement posé.
    if items:
        # #3202.5 — French Tech n'est pas « IT de moins de 10 personnes » : aucune source
        # French Tech/levées n'est branchée sur ce chemin, Laura le DIT (jamais un « non »
        # deviné, jamais un remplacement silencieux par des TPE IT).
        gap = french_tech_coverage_gap(False)
        if gap:
            out["french_tech_coverage_gap"] = gap
        warning = narrow_result_warning(out["criteria"], len(items[:limit]))
        if warning:
            out["narrow_result_note"] = warning
    if not items:
        out["no_match_note"] = (
            "Aucune entreprise du registre ne répond à ces critères. C'est un fait sur CE que "
            "nous savons, pas sur le marché : dis-le ainsi, puis relance toi-même un second passage "
            "élargi dans le même tour (#3343), sans demander la permission."
        )
        # #2264.43 — SOURCE NON COUVERTE, distincte d'un zéro réellement trouvé :
        # une source qui ne sait pas EXPRIMER ce critère (kind capability) n'a
        # rien cherché, elle a refusé la question — jamais confondu avec une
        # source qui a cherché et n'a rien trouvé (kind no-match).
        has_capability_gap = any(entry.get("kind") == KIND_CAPABILITY for entry in degraded)
        if has_capability_gap:
            out["source_not_covered_note"] = (
                "Au moins une source du registre ne couvre pas ce critère : ce n'est pas qu'elle "
                "a cherché et n'a rien trouvé, c'est qu'elle ne sait pas chercher là-dessus."
            )
        # #2264.45 / #2852.19 — CRITÈRES TROP ÉTROITS, nommé : trois filtres ou
        # plus combinés peuvent ne laisser aucune entreprise sans que le marché
        # soit en cause. Même texte porté par `narrow_criteria_note` (compat)
        # ET `caveats` (#2852.19) — jamais recalculé deux fois (GA-26).
        active_criteria = sum(1 for value in (sectors, department, headcount, keywords) if value)
        if active_criteria >= 3:
            note = (
                "Plusieurs critères combinés peuvent être trop étroits : élargir l'un d'eux "
                "vaut la peine avant de conclure que rien n'existe."
            )
            out["narrow_criteria_note"] = note
            caveats.append(note)
        # #3201.6 — RELAXATION CONTRÔLÉE : LE critère le plus restrictif, nommé,
        # avec ce qui changerait — jamais un « élargis l'un d'eux » sans cible,
        # et jamais une exécution silencieuse (Laura relance seule et le dit, #4438).
        if active_criteria >= 2:
            suggestion = relaxation_suggestion(out["criteria"])
            if suggestion:
                out["relaxation_suggestion"] = suggestion
    # #2852.6-53 — même NO-GO que le reste du catalogue : `empty` (mesuré) et
    # `not_covered` (une source n'a pas su exprimer le critère) ne se
    # confondent jamais. `truncated` est MESURÉ (plus de candidats blendés que
    # la limite demandée), jamais deviné.
    truncated = len(items) > limit
    target = _requested_count(tool_input)
    if items and target is not None and target <= _ACCOUNT_SEARCH_MAX_ITEMS and len(items[:limit]) < min(target, limit):
        # #3704 — le nombre demandé est une CIBLE de restitution, pas une obligation d'inventer :
        # on dit combien répondent, et on propose un élargissement précis SANS l'appliquer.
        # #4421.3 / #4408.1 (épopée #4433, Louis 21/10) — Laura élargit SEULE par paliers et DIT le palier atteint en
        # une ligne ; le manque restant se dit AVEC ce palier, jamais un « je ne complète pas » nu, jamais une demande
        # de permission. Les comptes élargis portent déjà leur étiquette (`widened`) dans la sélection.
        reached = list(dict.fromkeys(str(it["widened"]) for it in items[:limit] if it.get("widened")))
        found = len(items[:limit])
        if reached:
            palier = (
                f"Seules {found} entreprises sur {target} demandées répondent, même après l'élargissement automatique "
                f"({', '.join(reached)})."
            )
        else:
            palier = (
                f"Seules {found} entreprises sur {target} demandées répondent, et l'élargissement automatique "
                "n'a trouvé aucun voisin à nommer."
            )
        out["shortfall"] = {
            "requested": target,
            "found": found,
            "applied": bool(reached),
            "message": (
                f"{palier} Dis-le en une ligne avec le palier atteint (« {found} comptes ; élargi à <palier> sans en "
                "trouver d'autres »), sans demander la permission d'élargir : aucune entreprise hors critères n'est ajoutée."
            ),
            "widening_proposal": _widening_proposal(out["criteria"]),
        }
    if not items:
        status = ToolResultStatus.NOT_COVERED if has_capability_gap else ToolResultStatus.EMPTY
    elif truncated:
        status = ToolResultStatus.PARTIAL
    else:
        status = ToolResultStatus.SUCCESS
    out.update(
        ToolResultEnvelope(
            status=status,
            result_type="account_list",
            returned_count=len(out["items"]),
            sources_consulted=["registre_entreprises"],
            sources_succeeded=["registre_entreprises"],
            partial_reason=(
                "Résultat tronqué : plus de correspondances existent que la limite demandée." if truncated else None
            ),
            # #2852.11 — la couverture UNIFIÉE, comptée sur la MÊME liste
            # `degraded` déjà anonymisée juste au-dessus (jamais une seconde
            # lecture).
            coverage=coverage_from_degraded(degraded),
            caveats=caveats,
            unknowns=unknowns,
            duration_ms=round((time.monotonic() - started_at) * 1000),
        ).to_wire()
    )
    return out


# ── #3181.1 (LAU-FINAL-187) — LA RELAXATION DÉTERMINISTE ────────────────────
#
# `_DISCOVER_HEADCOUNTS` est déjà l'échelle CANONIQUE, du plus petit au plus
# grand (§ vocabulaire de Découvrir, tout en haut de ce fichier) — la réutiliser
# ici évite une seconde échelle qui pourrait diverger (GA-26).
_ALTERNATIVES_POOL_SIZE = 8
_ALTERNATIVES_MAX = 5


def _relaxed_headcount(headcount: str) -> str:
    """La tranche d'effectif UN CRAN EN DESSOUS — jamais devinée hors du
    vocabulaire fermé de Découvrir. Absente, ou déjà la plus petite tranche :
    rien à relâcher, chaîne vide (même convention que `_run_account_search`,
    où une tranche vide ne contraint rien)."""
    if headcount not in _DISCOVER_HEADCOUNTS:
        return ""
    index = _DISCOVER_HEADCOUNTS.index(headcount)
    return _DISCOVER_HEADCOUNTS[index - 1] if index > 0 else ""


def _alternative_easier_facts(
    candidate: Mapping[str, Any],
    *,
    original_department: str,
    original_headcount: str,
    market_memory_ex_esn_observed: bool = False,
    crm_relation_matched: bool = False,
    original_registry_country: str = "",
    autonomous_subsidiary: bool = False,
    partner_access_names: Sequence[str] = (),
    proof_sector_match: bool = False,
    community_open_sources: int = 0,
    target_group_head: bool = False,
) -> list[str]:
    """#3181.5 — les faits RÉELS qui rendent CE candidat plus accessible que
    le compte visé. Une alternative n'est jamais qu'une liste du même
    secteur : sans au moins un de ces faits, l'appelant l'écarte.

    Chaque fait vient d'une donnée déjà mesurée par le registre
    (`_search_item`) — rien n'est recalculé ni deviné ici. `market_memory_ex_esn_observed`
    — #3181.2/.3 (épopée #3247) — vient du croisement Market Memory PAR
    CANDIDAT (`_pool_market_memory_signal`), la famille « compte où des
    externes ont été historiquement observés » de la spec LAU-FINAL-187.
    `crm_relation_matched` — #3181.2 (épopée #3247) — vient du croisement CRM
    PAR CANDIDAT (`_pool_crm_relation_signal`), la famille « compte où le
    workspace possède une relation (CRM) »."""
    facts: list[str] = []
    candidate_department = str(candidate.get("department") or "").strip()
    if original_department and candidate_department and candidate_department != original_department:
        facts.append(f"hors du département {original_department} du compte visé — accès non limité à cette seule zone")
    low, _high = _HEADCOUNT_BOUNDS.get(original_headcount, (None, None))
    candidate_headcount = candidate.get("headcount")
    if (
        isinstance(low, int)
        and isinstance(candidate_headcount, int)
        and not isinstance(candidate_headcount, bool)
        and candidate_headcount < low
    ):
        facts.append(f"effectif plus réduit ({candidate_headcount} salariés) — généralement moins de strates d'accès")
    if candidate.get("signals_searched") and candidate.get("signals"):
        facts.append("signal actuel identifié au registre")
    if str(candidate.get("verdict") or "").strip() == "recommended":
        facts.append("déjà qualifié « recommandé » par le registre")
    if market_memory_ex_esn_observed:
        facts.append("externes déjà observés dans cette entreprise (observation du marché)")
    if crm_relation_matched:
        facts.append("le CRM branché porte déjà une relation avec cette entreprise")
    # #3247 / #3181.2 (décision Louis 10/10) — « filiale plus autonome du même groupe » :
    # SIREN propre ET dirigeant propre, établis sur la cartographie Pappers.
    if autonomous_subsidiary:
        facts.append("filiale du même groupe (entité française à SIREN propre), avec sa direction propre — plus autonome")
    # #3181.4 (épopée #3247) — « accessible via un partenaire » : le lien SIREN partenaire↔client
    # (`bellum_api.access_by_siren`), un compte POSSÉDÉ sous ce SIREN où l'espace déclare une ESN.
    if partner_access_names:
        facts.append("accessible via un partenaire déclaré de l'espace : " + ", ".join(partner_access_names[:2]))
    # #3247 (décision Louis 15/10/2026) — un compte HORS portefeuille dont le verrou est CONFIRMÉ ouvert
    # par la communauté (trois espaces distincts, partage réciproque) : un fait, jamais une probabilité.
    if community_open_sources:
        facts.append(f"accès ouvert, confirmé par {community_open_sources} espaces de la communauté")
    # #3181.2 (épopée #3247) — « compte similaire où l'ESN possède déjà une preuve » : le secteur
    # du candidat (NAF → groupe fermé) recoupe un secteur de preuve de l'espace.
    if proof_sector_match:
        facts.append("ton espace possède déjà une preuve dans ce secteur")
    # #3181.2 (épopée #3247) — « entité française plutôt que mondiale » : le candidat
    # sort du registre national (il porte un SIREN) ; le compte visé n'est connu
    # immatriculé HORS de France que par `accounts.registry_country`. Pays inconnu
    # ou « FR » : aucun fait, jamais deviné.
    if (
        original_registry_country
        and original_registry_country.upper() != "FR"
        and str(candidate.get("siren") or "").strip()
    ):
        facts.append("entité française immatriculée au registre national — le compte visé est immatriculé à l'étranger")
    # #4289.4 — le compte visé est une TÊTE DE GROUPE (« Thales ») : une entité française à SIREN propre,
    # lue au registre, est plus directement joignable que le groupe — un fait de la cartographie, jamais deviné.
    elif target_group_head and str(candidate.get("siren") or "").strip():
        facts.append("entité française à SIREN propre — le compte visé est une tête de groupe")
    return facts


def _executive_name_keys(profile: Any) -> set[str]:
    """Les dirigeants d'un profil Pappers, repliés en clés `prénom nom` minuscules
    (une entrée sans aucun nom n'est pas un dirigeant)."""
    keys: set[str] = set()
    for executive in getattr(profile, "executives", None) or []:
        parts = [str(getattr(executive, "first_name", "") or "").strip(), str(getattr(executive, "last_name", "") or "").strip()]
        key = " ".join(part.lower() for part in parts if part)
        if key:
            keys.add(key)
    return keys


def _group_head_siren(profile: Any, own_siren: str) -> str | None:
    """La TÊTE du groupe d'un profil : lui-même s'il est tête, sa tête sinon ;
    `None` quand la cartographie ne tranche pas (jamais un groupe deviné)."""
    affiliation = getattr(profile, "group_affiliation", None)
    if affiliation is None:
        return None
    if affiliation.role == "groupe":
        return own_siren or None
    return affiliation.head_siren or None


def _is_autonomous_subsidiary(profile: Any, *, candidate_siren: str, target_siren: str, target: Any) -> bool:
    """#3247 / #3181.2 (décision Louis 10/10) — « filiale plus AUTONOME du même
    groupe », définition FERMÉE : même groupe que le compte visé (même tête, lue
    sur la cartographie) ET SIREN propre (une autre entité juridique) ET dirigeant
    propre (au moins un dirigeant, aucun en commun avec le compte visé). Tout
    doute — groupe inconnu, aucun dirigeant lisible — rend `False` : on n'affirme
    pas une autonomie qu'on n'a pas établie."""
    candidate_siren = candidate_siren.strip()
    target_siren = target_siren.strip()
    if not candidate_siren or candidate_siren == target_siren:
        return False
    target_head = _group_head_siren(target, target_siren)
    if target_head is None:
        return False
    candidate_affiliation = getattr(profile, "group_affiliation", None)
    if candidate_affiliation is None or candidate_affiliation.role != "filiale":
        return False
    if candidate_affiliation.head_siren != target_head:
        return False
    candidate_executives = _executive_name_keys(profile)
    return bool(candidate_executives) and candidate_executives.isdisjoint(_executive_name_keys(target))


async def _pool_group_autonomy_signal(
    candidate: Mapping[str, Any], *, target_siren: str, target: Any
) -> dict[str, Any] | None:
    """#3247 / #3181.2 — lit la cartographie Pappers de CE candidat (cache 30 j,
    aucun appel sur un hit) et dit s'il est une filiale autonome du groupe du
    compte visé. Best-effort et jamais bloquant, même contrat que les autres
    signaux du pool : sans SIREN ou sur échec Pappers → `None`, DÉCLARÉ à
    l'appelant (`missing_check`), jamais un fait deviné."""
    siren = str(candidate.get("siren") or "").strip()
    if not siren:
        return None
    from app.services import pappers

    try:
        profile = await pappers.get_company(siren)
    except Exception:  # noqa: BLE001 — une alternative ne tombe jamais pour ce signal
        return None
    return {
        "checked": True,
        "autonomous": _is_autonomous_subsidiary(
            profile, candidate_siren=siren, target_siren=target_siren, target=target
        ),
    }


async def _pool_market_memory_signal(user_id: str, candidate: Mapping[str, Any]) -> dict[str, Any] | None:
    """#3181.2/.3/.4 (partiel, épopée #3247) — croise CE candidat du pool avec
    l'observation du marché, LE SEUL point d'entrée déjà branché
    (`bellum_api.market_memory_context_for`, GA-258, la même porte que
    `phase4_plan._market_memory_reinforced_expertises`) : aucun second
    moteur, aucune identité devinée (`ref` = SIREN du candidat, déjà son
    identité stable au registre).

    Best-effort et jamais bloquant, comme son unique autre appelant : un
    candidat sans lecture exploitable (pont éteint, réseau en échec, entité
    ambiguë ou sous le seuil côté corpus) rend `None` — DÉCLARÉ à l'appelant
    via `missing_check`, jamais un fait deviné à sa place (GA-18/GA-19).
    `None` recouvre aussi bien « je n'ai rien vu » que « je n'ai pas pu
    lire » côté RETOUR de cette fonction ; c'est `_suggest_account_alternatives`
    qui les redistingue pour `missing_check` en comparant au statut brut."""
    name = str(candidate.get("name") or "").strip()
    if not name:
        return None
    siren = str(candidate.get("siren") or "").strip()
    from app.services import bellum_api

    try:
        context = await bellum_api.market_memory_context_for(user_id, ref=siren or name, company_name=name)
    except Exception:  # noqa: BLE001 — une alternative ne tombe jamais pour ce signal
        return None
    if not isinstance(context, dict) or context.get("status") != "ok":
        return None
    coverage = context.get("coverage")
    if not isinstance(coverage, dict):
        return None
    ex_esn_present = coverage.get("exEsnPresent")
    ex_esn_observed = isinstance(ex_esn_present, int) and not isinstance(ex_esn_present, bool) and ex_esn_present > 0
    return {"checked": True, "ex_esn_observed": bool(coverage.get("covered")) and ex_esn_observed}


async def _pool_crm_relation_signal(user_id: str, candidate: Mapping[str, Any]) -> dict[str, Any] | None:
    """#3181.2 (épopée #3247) — croise CE candidat du pool avec le CRM branché
    de l'espace, PAR IDENTITÉ (nom/domaine/siren) — jamais un `account_id`, ce
    candidat n'en a pas : `bellum_api.crm_company_presence` relaie
    `CrmReadService.findAccountPresence`, le MÊME service que `crm_presence`
    (`get_esn_on_account`), sans son exigence d'ownership (déjà prouvée
    superflue par `describeAccountHistory`, appelé côté API à l'analyse d'un
    compte pas encore créé) — aucun second moteur CRM.

    Best-effort et jamais bloquant, même contrat que `_pool_market_memory_signal` :
    un candidat sans lecture exploitable (pont éteint, droit manquant, réseau
    en échec) rend `None`, DÉCLARÉ à l'appelant via `missing_check`, jamais un
    fait deviné à sa place (GA-18/GA-19)."""
    name = str(candidate.get("name") or "").strip()
    if not name:
        return None
    siren = str(candidate.get("siren") or "").strip()
    from app.services import bellum_api

    try:
        result = await bellum_api.crm_company_presence(user_id, company_name=name, siren=siren or None)
    except Exception:  # noqa: BLE001 — une alternative ne tombe jamais pour ce signal
        return None
    if not isinstance(result, dict) or result.get("error"):
        return None
    return {"checked": True, "matched": bool(result.get("matched"))}


def _pool_in_target_sector(pool: list[dict[str, Any]], target_naf: str) -> list[dict[str, Any]]:
    """#3247.2 (18/10) — une alternative reste dans l'activité du groupe visé : même DIVISION NAF
    (deux premiers chiffres). Un candidat dont le NAF est INCONNU n'est pas écarté (on n'écarte pas
    sur une absence) ; un groupe dont le NAF est inconnu ne filtre rien."""
    division = "".join(ch for ch in target_naf if ch.isalnum())[:2]
    if len(division) != 2 or not division.isdigit():
        return pool
    kept: list[dict[str, Any]] = []
    for item in pool:
        candidate = "".join(ch for ch in str(item.get("naf_code") or "") if ch.isalnum())[:2]
        if candidate.isdigit() and len(candidate) == 2 and candidate != division:
            continue
        kept.append(item)
    return kept


# RV4-E-FIX 4287.2 — comment une personne nomme chaque secteur dans sa phrase (clé du secteur → radicaux).
_SECTOR_WORDS: dict[str, tuple[str, ...]] = {
    "it": ("informatique", "numérique", "numerique", "logiciel", "tech"),
    "telecom": ("télécom", "telecom"),
    "finance": ("finance", "banque", "assurance", "bancaire"),
    "energy": ("énergie", "energie", "energy"),
    "industry": ("industri", "manufactur"),
    "health": ("santé", "sante", "health", "hôpital", "hopital"),
    "retail": ("commerce", "retail", "distribution"),
    "transport": ("transport", "logisti"),
    "construction": ("construction", "btp"),
    "public": ("public", "administration"),
}


async def _suggest_account_alternatives(
    tool_input: dict[str, Any], *, user_id: str, profile_data: dict | None
) -> dict[str, Any]:
    """#3181.1 (LAU-FINAL-187) — 3 à 5 comptes alternatifs, réellement plus
    accessibles que le compte visé, dont le verdict n'est pas AGIR MAINTENANT.

    Le compte est lu comme `get_account_briefing` (même ownership, même
    `_account_named_verdict`) ; la recherche relâchée réutilise
    `_run_account_search` — le MÊME moteur que `run_account_search`, jamais un
    second calcul (GA-26)."""
    from fastapi import HTTPException

    from app.services.ownership import fetch_owned_account
    from app.services.supabase_client import get_supabase

    account_id = str(tool_input.get("account_id") or "").strip()
    # #3247.r40 — un groupe ABSENT du portefeuille (« alternatives à Safran ? ») n'a ni
    # `account_id` ni verdict : l'outil cherche quand même, sur le nom et le secteur donnés.
    # Aucun verdict n'est inventé (`source_account_verdict` reste None, la note le DIT).
    outside_name = str(tool_input.get("company_name") or "").strip()
    outside_portfolio = not account_id and bool(outside_name)
    if not account_id and not outside_name:
        return {"error": "Un identifiant de compte (ou le nom du groupe visé) est requis pour chercher des alternatives."}
    if outside_portfolio:
        account: dict[str, Any] = {"company_name": outside_name, "siren": str(tool_input.get("siren") or "").strip()}
        verdict: str | None = "HORS PORTEFEUILLE"
    else:
        try:
            account = await fetch_owned_account(get_supabase(), account_id, user_id)
        except HTTPException:
            return {"error": "Compte introuvable dans votre portefeuille."}

        verdict = _account_named_verdict(account, has_objective=_profile_has_objective(profile_data))
        if verdict is None:
            # #3181.1 (recette 29/09) — le verdict lu par Laura est souvent celui de
            # `get_account_suitability_verdict` (vocabulaire WATCH / NO_GO_NOW) : un
            # compte sans `plan.evaluation.verdict` mais déjà jugé par lui n'est pas
            # « sans verdict ».
            suitability_verdict = compute_account_suitability(
                account.get("raw_analysis") if isinstance(account.get("raw_analysis"), dict) else {},
                profile_data or {},
                company=account.get("company_name"),
                sector=account.get("sector"),
            ).get("verdict")
            if suitability_verdict in _ALTERNATIVES_TRIGGER_VERDICTS:
                verdict = str(suitability_verdict)
            elif suitability_verdict == "GO_NOW":
                verdict = "AGIR MAINTENANT"
        if verdict is None:
            return {
                "error": (
                    "Ce compte n'a pas encore de verdict : lance d'abord l'analyse de fond avant de "
                    "chercher des alternatives."
                )
            }
        if verdict == "AGIR MAINTENANT":
            return {
                "error": (
                    "Ce compte est déjà en AGIR MAINTENANT : pas d'alternative à proposer, l'action est d'avancer dessus."
                )
            }

    sectors = _pick_known(tool_input.get("sectors"), _DISCOVER_SECTORS)
    if not sectors and not outside_portfolio:
        return {
            "error": (
                "Il me faut au moins le secteur du compte visé pour chercher des comptes "
                "comparables — je ne devine pas une activité."
            )
        }
    original_department = str(tool_input.get("department") or "").strip().upper()
    original_headcount = str(tool_input.get("headcount") or "").strip()
    if original_headcount not in _HEADCOUNT_BOUNDS:
        original_headcount = ""

    raw_excluded = tool_input.get("excluded_sirens")
    excluded_sirens = (
        [str(v).strip() for v in raw_excluded if isinstance(v, str) and str(v).strip()]
        if isinstance(raw_excluded, list)
        else []
    )
    account_siren = str(account.get("siren") or "").strip()
    # #3247.2 (18/10) — le secteur d'un groupe HORS portefeuille se lit au registre (nom → SIREN → NAF),
    # jamais du seul profil de l'ESN : « alternatives à Michelin » ne propose pas des boulangeries.
    target_naf = str(account.get("naf_code") or "").strip()
    if outside_portfolio and not account_siren:
        try:
            from app.services import pappers as _pappers

            hit = await _pappers.search_company(outside_name)
            account_siren = str(hit.siren or "").strip()
            target_naf = target_naf or str(hit.naf_code or "").strip()
        except Exception:  # noqa: BLE001 — best-effort : un groupe non résolu garde le secteur donné
            pass
    registry_profile: Any = None
    if outside_portfolio and account_siren:
        # #4289.3/.4 — le groupe hors portefeuille n'a ni département ni effectif en base : la BASE de comparaison
        # (« plus accessible que… ») se lit au registre public, jamais devinée. Sans elle, aucun fait comparatif ne
        # se calcule et toute alternative était écartée — « aucune alternative mesurablement plus accessible ».
        try:
            from app.services import pappers as _pappers_profile

            registry_profile = await _pappers_profile.get_company(account_siren)
        except Exception:  # noqa: BLE001 — best-effort : sans registre, la base reste inconnue
            registry_profile = None
        if registry_profile is not None:
            # RV4-E-FIX 4287.2 — la BASE d'un groupe hors portefeuille est celle du registre ; le département
            # ou l'effectif recopié d'une question précédente ne la remplace que si le registre ne la donne pas.
            original_department = (
                str(getattr(getattr(registry_profile, "headquarters", None), "department", None) or "").strip().upper()
                or original_department
            )
            headcount_min = getattr(registry_profile, "headcount_min", None)
            if isinstance(headcount_min, int) and not isinstance(headcount_min, bool):
                fitting = [
                    key for key, (low, _high) in _HEADCOUNT_BOUNDS.items() if isinstance(low, int) and low <= headcount_min
                ]
                original_headcount = fitting[-1] if fitting else original_headcount
            target_naf = target_naf or str(getattr(registry_profile, "naf_code", None) or "").strip()
    if not sectors:
        # #4289.3 — un groupe HORS portefeuille dont le modèle n'a pas donné le secteur : il se lit au registre
        # public (NAF résolu ci-dessus), jamais une erreur ni une activité devinée.
        from app.services.naf_sections import SECTOR_TO_NAF_SECTION, naf_section_of

        section = naf_section_of(target_naf)
        sectors = [key for key, value in SECTOR_TO_NAF_SECTION.items() if section and value == section][:1]
        if not sectors:
            return {
                "error": (
                    f"Je n'ai pas retrouvé le secteur de {outside_name} au registre public : donne-moi son secteur "
                    "(par exemple industrie, finance, énergie) et je cherche des comptes comparables — "
                    "je ne devine pas une activité."
                )
            }
    # RV4-E-FIX 4287.2 — le secteur d'une alternative se lit sur le compte VISÉ, jamais sur le filtre d'une question
    # précédente que le modèle a recopié dans l'appel : un secteur d'une AUTRE section NAF que la cible, que le message
    # du tour ne nomme pas, est remplacé par celui de la cible — et la réponse le DIT.
    sector_replaced: list[str] = []
    from app.services.naf_sections import SECTOR_TO_NAF_SECTION as _SECTOR_SECTIONS
    from app.services.naf_sections import naf_section_of as _section_of

    target_section = _section_of(target_naf)
    if sectors and target_section and not any(_SECTOR_SECTIONS.get(key) == target_section for key in sectors):
        turn = current_turn_thread()
        message = (turn[0] if turn else "").casefold()
        if not any(word in message for key in sectors for word in _SECTOR_WORDS.get(key, (key,))):
            fitting_sectors = [key for key, value in _SECTOR_SECTIONS.items() if value == target_section][:1]
            if fitting_sectors:
                sector_replaced, sectors = list(sectors), fitting_sectors
    if account_siren:
        excluded_sirens.append(account_siren)

    search_input: dict[str, Any] = {
        "sectors": sectors,
        "excluded_sirens": excluded_sirens,
        "limit": _ALTERNATIVES_POOL_SIZE,
    }
    relaxed_headcount = _relaxed_headcount(original_headcount)
    if relaxed_headcount:
        search_input["headcount"] = relaxed_headcount
    # Le département n'est JAMAIS transmis : c'est la relaxation elle-même
    # (recherche nationale), pas un oubli.
    result = await _run_account_search(search_input, profile_data=profile_data)
    if result.get("error"):
        return result

    pool = result.get("items") or []
    target_profile: Any = registry_profile
    if account_siren and target_profile is None:
        from app.services import pappers

        try:
            target_profile = await pappers.get_company(account_siren)
        except Exception:  # noqa: BLE001 — best-effort, jamais bloquant
            target_profile = None
    target_naf = target_naf or str(getattr(target_profile, "naf_code", None) or "").strip()
    pool = _pool_in_target_sector(pool, target_naf)
    # #3181.2/.3 (épopée #3247) — croise CHAQUE candidat du pool (borné à
    # `_ALTERNATIVES_POOL_SIZE`, comme la recherche elle-même) avec la
    # mémoire marché ET le CRM branché, EN PARALLÈLE — un aller-retour réseau
    # par candidat et par source, jamais seize tours successifs.
    # `return_exceptions` — best-effort, jamais bloquant.
    market_memory_signals, crm_relation_signals = await asyncio.gather(
        asyncio.gather(*(_pool_market_memory_signal(user_id, item) for item in pool), return_exceptions=True),
        asyncio.gather(*(_pool_crm_relation_signal(user_id, item) for item in pool), return_exceptions=True),
    )
    # #4289.4 — la cartographie du compte visé (lue plus haut) dit s'il est la tête de son groupe.
    target_group_head = getattr(getattr(target_profile, "group_affiliation", None), "role", None) == "groupe"

    # #3247 / #3181.2 (décision Louis 10/10) — « filiale plus autonome du même
    # groupe » : on lit D'ABORD le groupe du compte visé (un appel, cache 30 j) ;
    # s'il est inconnu, aucun candidat n'est interrogé (zéro appel Pappers
    # dépensé pour un fait qu'on ne pourrait pas établir). Le seuil d'alerte de
    # consommation par run est à 16 (`pappers/budget.py`), cible + 8 candidats.
    group_signals: list[Any] = [None] * len(pool)
    if target_profile is not None and _group_head_siren(target_profile, account_siren) is not None:
        group_signals = list(
            await asyncio.gather(
                *(
                    _pool_group_autonomy_signal(item, target_siren=account_siren, target=target_profile)
                    for item in pool
                ),
                return_exceptions=True,
            )
        )
    group_known = target_profile is not None and _group_head_siren(target_profile, account_siren) is not None

    # #3181.4 (épopée #3247) — le lien SIREN partenaire↔client, lu UNE fois pour tout le pool.
    from app.services import bellum_api

    try:
        access_by_siren = await bellum_api.access_by_siren(
            user_id, sirens=[str(item.get("siren") or "").strip() for item in pool]
        )
    except Exception:  # noqa: BLE001 — best-effort, une alternative ne tombe jamais pour ce signal
        access_by_siren = None
    # #3247 (15/10) — l'accès à un compte HORS portefeuille : le verrou communautaire par SIREN, lu UNE fois.
    try:
        community_by_siren = await bellum_api.community_access_by_siren(
            user_id, sirens=[str(item.get("siren") or "").strip() for item in pool]
        )
    except Exception:  # noqa: BLE001 — best-effort, une alternative ne tombe jamais pour ce signal
        community_by_siren = None
    # #4289.12 — le STADE de relation (compte visé + pool), lu UNE fois sur le moteur de l'API (`relationStageOf`,
    # le même que les cas similaires) : « même stade » n'est plus « tous deux vus dans le CRM » (un prospect et un
    # client actif y sortaient au même stade). Lecture en échec ou stade inconnu d'un côté = rien n'est déclaré.
    try:
        stages_by_siren = await bellum_api.relation_stages_by_siren(
            user_id, sirens=[account_siren, *(str(item.get("siren") or "").strip() for item in pool)]
        )
    except Exception:  # noqa: BLE001 — best-effort, une alternative ne tombe jamais pour ce signal
        stages_by_siren = None
    from app.services.sales_context import RELATION_STAGE_LABELS

    target_stage = ((stages_by_siren or {}).get(account_siren) or {}).get("relationStage") if account_siren else None
    set_aside_partners: list[str] = []
    set_aside: list[dict[str, str]] = []
    try:
        proof_groups_read = await bellum_api.proof_sector_groups(user_id)
    except Exception:  # noqa: BLE001 — best-effort
        proof_groups_read = None
    proof_groups = {str(g) for g in (proof_groups_read or {}).get("groups") or []}

    alternatives: list[dict[str, Any]] = []
    neighbours: list[dict[str, Any]] = []
    source_label = outside_name or str(account.get("company_name") or "").strip() or "le compte visé"
    for item, mm_signal, crm_signal, group_signal in zip(
        pool, market_memory_signals, crm_relation_signals, group_signals, strict=True
    ):
        if isinstance(group_signal, BaseException) or not isinstance(group_signal, dict):
            group_signal = None
        if isinstance(mm_signal, BaseException) or not isinstance(mm_signal, dict):
            mm_signal = None
        if isinstance(crm_signal, BaseException) or not isinstance(crm_signal, dict):
            crm_signal = None
        access_entry = (access_by_siren or {}).get(str(item.get("siren") or "").strip())
        if not isinstance(access_entry, dict):
            access_entry = None
        # Clients et partenaires ne se mélangent pas : un partenaire de l'espace n'est pas une cible.
        workspace_partner = access_entry.get("is_workspace_partner") if access_entry else None
        if isinstance(workspace_partner, dict) and workspace_partner.get("name"):
            set_aside_partners.append(str(workspace_partner["name"]))
            # #4289.4 — l'écart se NOMME avec sa raison, jamais un candidat qui disparaît sans un mot.
            set_aside.append(
                {
                    "name": str(workspace_partner["name"]),
                    "reason": "partenaire déclaré de ton espace — un partenaire n'est pas un client à prospecter",
                }
            )
            continue
        access_paths = [p for p in (access_entry or {}).get("paths") or [] if isinstance(p, dict) and p.get("partner_name")]
        community_entry = (community_by_siren or {}).get(str(item.get("siren") or "").strip())
        community = community_entry.get("community") if isinstance(community_entry, dict) else None
        community_confirmed = (
            isinstance(community, dict)
            and not community_entry.get("owned")
            and community.get("isCommunity") is True
            and not community.get("conflict")
        )
        community_open_sources = (
            int(community.get("sourcesCount") or 0)
            if community_confirmed and community.get("value") in ("ouvert", "semi_ouvert")
            else 0
        )
        community_locked = bool(community_confirmed and community.get("value") == "verrouille")
        ex_esn_observed = bool(mm_signal and mm_signal.get("ex_esn_observed"))
        crm_relation_matched = bool(crm_signal and crm_signal.get("matched"))
        facts = _alternative_easier_facts(
            item,
            original_department=original_department,
            original_headcount=original_headcount,
            market_memory_ex_esn_observed=ex_esn_observed,
            crm_relation_matched=crm_relation_matched,
            original_registry_country=str(account.get("registry_country") or "").strip(),
            autonomous_subsidiary=bool(group_signal and group_signal.get("autonomous")),
            partner_access_names=[str(p["partner_name"]) for p in access_paths],
            proof_sector_match=bool(proof_groups & set(application_groups_of_naf(item.get("naf_code")))),
            community_open_sources=community_open_sources,
            target_group_head=target_group_head,
        )
        # #4289.5 — à défaut de partenaire, le chemin DIT pourquoi il n'y en a pas, jamais `null`.
        no_path = (
            "aucun partenaire déclaré sur ce compte"
            if access_entry is not None
            else "non vérifié — la lecture des partenaires n'a pas répondu"
            if access_by_siren is None
            else "non vérifié — compte hors de ton portefeuille"
        )
        # #4289.12 — « même stade de relation » : deux stades CONNUS et ÉGAUX (liste fermée), jamais deux présences CRM.
        candidate_stage = ((stages_by_siren or {}).get(str(item.get("siren") or "").strip()) or {}).get("relationStage")
        same_relation_stage = target_stage is not None and candidate_stage == target_stage
        stage_phrase = f" ; même stade de relation que {source_label} ({RELATION_STAGE_LABELS.get(str(target_stage), target_stage)})"
        if not facts:
            # #4289.4 — jamais « plus accessible » sans fait : le candidat reste un VOISIN (secteur, taille), nommé tel.
            if len(neighbours) < _ALTERNATIVES_MAX:
                neighbour: dict[str, Any] = {
                    "account": {
                        key: item[key]
                        for key in ("name", "siren", "city", "department", "activity", "headcount")
                        if key in item
                    },
                    "why_similar": "Même secteur ciblé : " + _sector_labels(sectors),
                    "first_move": "Lancer l'analyse de fond sur ce compte",
                    "first_move_tool": "start_account_analysis",
                    "access_path": no_path,
                }
                if same_relation_stage:
                    neighbour["same_relation_stage"] = True
                    neighbour["why_similar"] += stage_phrase
                neighbours.append(neighbour)
            continue
        alt: dict[str, Any] = {
            "account": {
                key: item[key]
                for key in ("name", "siren", "city", "department", "activity", "headcount")
                if key in item
            },
            "why_similar": "Même secteur ciblé : " + _sector_labels(sectors),
            "why_easier": " ; ".join(facts[:2]),
            "first_move": "Lancer l'analyse de fond sur ce compte",
            "first_move_tool": "start_account_analysis",
            # #3181.4 / #3247 (décision Louis 14/10, ÉLARGI) — le CHEMIN d'accès
            # vient de `bellum_api.access_by_siren` (ci-dessus, lu UNE fois pour
            # tout le pool) : un chemin existe quand CE candidat (ou la filiale
            # POSSÉDÉE dont il est la tête de groupe, `via_group`) porte une ESN
            # rang 2/partenaire DÉCLARÉE — jamais un chemin deviné (SOURCES-28-09,
            # « un contrat d'API non vérifiable ne se devine pas »).
            "access_path": no_path,
        }
        if same_relation_stage:
            alt["same_relation_stage"] = True
            alt["why_similar"] += stage_phrase
        if access_paths:
            alt["access_path"] = " ; ".join(
                f"via {p['partner_name']} ({'rang 2' if p.get('rank') == 'rank2' else 'partenaire'}, "
                f"{'déclaré' if p.get('source') == 'declared' else 'détecté'}"
                f"{', via une filiale du groupe' if p.get('via_group') else ''})"
                for p in access_paths[:3]
            )
        # #3247.r40 — les trois lectures PAR CANDIDAT se disent toujours : une lecture réussie mais
        # vide s'écrit « aucune », une lecture en échec reste dans `missing_check` (GA-18/GA-19).
        checked: list[str] = []
        if crm_signal is not None:
            checked.append("relation CRM : " + ("existante dans ton espace" if crm_relation_matched else "aucune trouvée"))
        if mm_signal is not None:
            checked.append(
                "présence marché : " + ("externes observés sur ce compte" if ex_esn_observed else "aucun externe observé")
            )
        in_proof_sector = bool(proof_groups & set(application_groups_of_naf(item.get("naf_code"))))
        checked.append(
            "preuve dans ce secteur : " + ("ton espace en possède une" if in_proof_sector else "aucune dans ton espace")
        )
        alt["checked"] = checked
        if item.get("why"):
            # #3247.3 (18/10) — une phrase lisible, doublons retirés : jamais la liste Python brute.
            why_parts = item["why"] if isinstance(item["why"], list) else [item["why"]]
            alt["evidence"] = " ; ".join(dict.fromkeys(str(w).strip() for w in why_parts if str(w).strip()))
        if item.get("signals_searched") and item.get("signals"):
            first_signal = item["signals"][0]
            alt["current_signal"] = (
                str(first_signal.get("label") or "").strip() if isinstance(first_signal, dict) else first_signal
            )
        missing = list(item.get("not_evaluated") or [])
        if community_locked:
            missing.append("accès : verrouillé selon la communauté (confirmé par plusieurs espaces)")
        if not access_paths:
            missing.append(
                "chemin d'accès (partenaire) — aucun partenaire déclaré sur ce compte"
                if access_entry is not None
                else "chemin d'accès (partenaire) — non vérifié : compte hors de ton portefeuille"
            )
        # #3181.2/.3 — la mémoire marché ET la relation CRM sont désormais
        # CROISÉES PAR CANDIDAT (voir plus haut) : nommées en inconnue
        # UNIQUEMENT quand la lecture précise a échoué pour CE candidat,
        # jamais quand elle a répondu « rien vu » (GA-18/GA-19 : une lecture
        # réussie mais vide n'est pas une inconnue).
        if mm_signal is None:
            missing.append("observation du marché (externes déjà observés) — non mesurable pour ce candidat")
        if crm_signal is None:
            missing.append("relation CRM existante — non mesurable pour ce candidat")
        # #3247 — nommée UNIQUEMENT quand le groupe du compte visé est connu et que
        # la lecture de CE candidat a échoué (une lecture réussie « non autonome »
        # n'est pas une inconnue).
        if group_known and group_signal is None:
            missing.append("autonomie vis-à-vis du groupe (SIREN et dirigeant propres) — non mesurable pour ce candidat")
        alt["missing_check"] = missing[:6]
        if item.get("verdict"):
            alt["registry_verdict"] = item["verdict"]
        alternatives.append(alt)
        if len(alternatives) >= _ALTERNATIVES_MAX:
            break

    out: dict[str, Any] = {
        "source_account_verdict": None if outside_portfolio else verdict,
        "alternatives": alternatives,
        "cost_credits": 0,
    }
    source_name = outside_name or str(account.get("company_name") or "").strip()
    if source_name:
        out["source_account_name"] = source_name
    if outside_portfolio:
        out["source_account_note"] = (
            f"{outside_name} n'est pas dans ton portefeuille : aucun verdict à rendre sur ce groupe, "
            "seulement les alternatives mesurées ci-dessous."
        )
    if set_aside_partners:
        out["set_aside_partners"] = set_aside_partners
        out["set_aside"] = set_aside
    if sector_replaced:
        out["sector_note"] = (
            f"Secteur lu sur {source_name or 'le compte visé'} (pas sur le filtre « {', '.join(sector_replaced)} » "
            "d'une question précédente) : redonne ce secteur si tu veux le restreindre."
        )
    stage_group = [a["account"]["name"] for a in alternatives if a.get("same_relation_stage") and a["account"].get("name")]
    if stage_group:
        out["relation_stage_group"] = stage_group  # #4289.2 — regroupés « même stade de relation »
    if alternatives:
        out["criteria_relaxed"] = {
            "department_dropped": bool(original_department),
            "headcount_lowered_to": relaxed_headcount or None,
        }
    else:
        note = (
            "Aucune alternative mesurablement plus accessible trouvée dans ce secteur, hors "
            "département et sur une tranche d'effectif inférieure. Élargir le secteur ou revoir "
            "les critères vaut la peine avant de conclure que rien n'existe."
        )
        # #4289.4 — le vide se DÉTAILLE : les partenaires écartés (jamais une cible) et la preuve dans ce secteur.
        if set_aside_partners:
            note += (
                f" {len(set_aside_partners)} partenaire(s) de ton espace ont été écartés du résultat (un partenaire "
                "n'est pas un client à prospecter) : " + ", ".join(dict.fromkeys(set_aside_partners[:5])) + "."
            )
        target_groups = set(application_groups_of_naf(target_naf))
        note += " Et la preuve dans ce secteur : " + (
            "ton espace en possède une." if proof_groups & target_groups else "aucune dans ton espace."
        )
        out["no_alternative_note"] = note
        if neighbours:
            # #4289.4 — le vide ne laisse pas la carte vide : les comptes voisins, SANS prétendre qu'ils sont plus accessibles.
            out["neighbours"] = neighbours
            out["neighbours_note"] = (
                "Aucun n'a de fait d'accessibilité mesuré supérieur : voici des comptes voisins (même secteur, hors "
                "département, effectif inférieur), à qualifier — pas des comptes « plus accessibles »."
            )
            out["relation_stage_group"] = [
                n["account"]["name"] for n in neighbours if n.get("same_relation_stage") and n["account"].get("name")
            ] or None
            if out["relation_stage_group"] is None:
                del out["relation_stage_group"]
    return out


async def _find_accounts_count(tool_input: dict[str, Any], *, profile_data: dict | None) -> int | None:
    """#1933.10 / #1903.24 — combien de comptes CE filtre ramènerait, avant que
    `find_accounts` propose le lien Découvrir. `find_accounts` ne consulte
    aucune donnée par conception (« Aucune lecture »), contrairement à
    `propose_guided_action` qui compte déjà avant de proposer un lien filtré
    (`_deep_link_count`, 15/09/2026) — c'était le trou que le registre nommait
    (1903.24). Même borne à trois issues :
      > 0        → la proposition est gardée telle quelle ;
      = 0 MESURÉ → la proposition est refusée, une erreur le dit ;
      non mesuré → la proposition est gardée telle quelle, comme avant.

    ⚠️ Une liste vide ne prouve pas un zéro. `discover_registry` inscrit une
    entrée dans `degraded` aussi bien pour une source qui a RÉPONDU « rien ne
    correspond » (`kind` posé — `company_filters.degrade_kind`) que pour une
    source en PANNE ou SANS CLÉ (`kind` absent : « ceci est cassé », selon la
    doc même de `degraded_entry`). Seule une recherche où CHAQUE entrée porte
    un `kind` mesure un zéro digne de confiance ; une seule entrée sans `kind`
    retombe sur « non mesuré », jamais sur zéro.
    """
    from app.services import kill_switch

    if kill_switch.disabled(kill_switch.DEEP_LINK_COUNT_KILL_SWITCH):
        return None
    try:
        result = await asyncio.wait_for(
            _run_account_search({**tool_input, "limit": 1}, profile_data=profile_data),
            timeout=_deep_link_count_budget_s(),
        )
    except Exception:
        # Dépassement de budget, erreur inattendue : dégradation NORMALE — le
        # lien continue de se proposer sans compte (même doctrine que
        # `_deep_link_count`).
        return None
    if not isinstance(result, dict) or result.get("error"):
        return None
    degraded = result.get("degraded")
    if isinstance(degraded, list) and any(not isinstance(entry, dict) or not entry.get("kind") for entry in degraded):
        return None
    items = result.get("items")
    return len(items) if isinstance(items, list) else None


def _search_axes(
    sectors: list[str],
    department: str,
    headcount: str,
    keywords: str,
    region: list[str] | None = None,
    *,
    city: str = "",
    offer: str = "",
) -> list[str]:
    """Les critères qui ORDONNENT la liste, en clair. Jamais vide : sans axe, la
    carte `account_ranking` est refusée par le contrat, et un rang sans axes est
    un score nu."""
    # #2547 / #2533 — jamais un code INSEE brut (« Région : 27 ») : son libellé.
    from app.services.geo_labels import department_label, region_label

    axes: list[str] = []
    if sectors:
        axes.append("Secteur d'activité visé : " + _sector_labels(sectors))
    if offer:
        # #3866 — la lentille qui juge chaque compte (« À qualifier » / « Recommandé ») reste NOMMÉE en tête de
        # carte, y compris après un « affine » : sans elle, l'en-tête ne dit plus à quoi l'adéquation se mesure.
        axes.append(f"Offre visée : {offer}")
    if department:
        axes.append(f"Département : {department_label(department)}")
    if city:
        # #3876.5 — la commune elle-même, jamais « Département » à sa place.
        axes.append(f"Ville : {city}")
    if region:
        axes.append("Région : " + ", ".join(region_label(code) for code in region))
    if headcount:
        axes.append(f"Effectif : {headcount}")
    if keywords:
        axes.append(f"Raison sociale : {keywords}")
    axes.append("Établissement actif au registre")
    return axes[:6]


_OUT_OF_SCOPE_MAX = 5


async def _widen_department_to_region(
    response: Any,
    *,
    department: str,
    filter_groups: list[Any],
    registry_args: tuple[Any, Any],
    fetch_limit: int,
    search_profile: dict | None,
    only_sources: tuple[str, ...],
    space_key: str | None,
    strict: bool,
) -> Any:
    """#4408.1 (recette prod 28/10) — un département qui rend trop peu de comptes monte à sa RÉGION, dans le tour, et le
    DIT : Laura AGIT (c126, #4438), elle n'écrit plus « le palier régional n'a pas été lancé ». ⚠️ c144 (Louis 27/10 au
    soir) : l'automatique PLAFONNE à la région — aucune requête France ne part d'ici, la France reste un geste explicite.
    Le seuil est celui de l'échelle de zone (``needs_zone_widening``, GA-26) ; les exacts gardent leur place en tête et
    un compte ajouté porte son palier (``zone``). Une région déjà entière n'a pas de palier plus large : rien ne part."""
    from app.services.geo_labels import department_name
    from app.services.zone_palier import widen_zone_to_region
    from app.services.zone_tiers import needs_zone_widening

    exact = [row for row in (getattr(response, "candidates", None) or []) if isinstance(row, Mapping)]
    if getattr(response, "zoneWidening", None) or not needs_zone_widening(len(exact)):
        return response
    region = widen_zone_to_region([department])
    if region is None:
        return response
    label, wide = region
    discover_registry, request_cls = registry_args
    wider = [
        group.model_copy(update={"department": None, "departments": wide, "regions": None}) for group in filter_groups
    ]
    try:
        widened = await asyncio.wait_for(
            _registry_for_groups(
                discover_registry,
                request_cls,
                wider,
                fetch_limit,
                search_profile,
                only_sources,
                space_key=None,
                strict=strict,
            ),
            timeout=_account_search_budget_s(),
        )
    except Exception as exc:  # noqa: BLE001 — l'élargissement ne casse jamais la première lecture, déjà rendue
        logger.info("#4408.1 — palier régional en échec: %s", type(exc).__name__)
        return response
    seen = {row.get("siren") for row in exact}
    added: list[dict[str, Any]] = []
    for row in getattr(widened, "candidates", None) or []:
        if not isinstance(row, Mapping) or row.get("siren") in seen:
            continue
        seen.add(row.get("siren"))
        added.append({**row, "zone": {"tier": "region", **({"area": a} if (a := department_name(str(row.get("department") or ""))) else {})}})

    class _Widened:
        candidates = exact + added
        # La même source en échec aux deux lectures reste UNE ligne : le compte de couverture ne double pas.
        degraded = [
            *(getattr(response, "degraded", None) or []),
            *(d for d in (getattr(widened, "degraded", None) or []) if d not in (getattr(response, "degraded", None) or [])),
        ]
        query = getattr(response, "query", None)
        zoneWidening = {  # noqa: N815
            "place": department_name(department) or department,
            "tier": "region",
            "steps": ["region"],
            "exactCount": len(exact),
            "widenedCount": len(added),
            "area": label,
            **({} if added else {"autoCapReached": True}),
        }

    return _Widened()


async def _registry_for_groups(
    discover_registry: Any,
    request_cls: Any,
    filter_groups: list[Any],
    limit: int,
    profile_data: dict | None,
    only_sources: tuple[str, ...] = (),
    *,
    space_key: str | None = None,
    strict: bool = False,
) -> Any:
    """#3705 — une sous-recherche par groupe de filtres, en parallèle, fusionnées.

    Un seul groupe (le cas d'avant) : la réponse du registre est rendue TELLE QUELLE.
    #4430 — une réponse = UN plafond d'offres fraîches : seul le premier groupe porte l'espace.
    """
    responses = await asyncio.gather(
        *(
            discover_registry(
                request_cls(
                    filters=group,
                    limit=limit,
                    profile_data=profile_data or {},
                    **({"onlySources": list(only_sources)} if only_sources else {}),
                    **({"spaceKey": space_key} if space_key and index == 0 else {}),
                    **({"strictCriteria": True} if strict else {}),
                )
            )
            for index, group in enumerate(filter_groups)
        )
    )
    if len(responses) == 1:
        return responses[0]

    class _Merged:
        candidates = [row for response in responses for row in (getattr(response, "candidates", None) or [])]
        degraded = [entry for response in responses for entry in (getattr(response, "degraded", None) or [])]
        # #4429.3 — le palier de zone du registre voyage aussi avec plusieurs groupes (même zone pour tous).
        zoneWidening = next(  # noqa: N815
            (getattr(r, "zoneWidening") for r in responses if getattr(r, "zoneWidening", None)), None  # noqa: B009
        )

    return _Merged()


def _split_redirected_holdings(
    candidates: list[Mapping[str, Any]],
) -> tuple[list[Mapping[str, Any]], list[dict[str, Any]], dict[str, str]]:
    """#3983 (reste) — retire les holdings écartées au profit d'une filiale dans la zone
    (`holding_subsidiary.HOLDING_CODE`) ; rend aussi `{siren filiale: nom holding}`."""
    from app.services.holding_subsidiary import HOLDING_CODE

    kept: list[Mapping[str, Any]] = []
    redirected: list[dict[str, Any]] = []
    subsidiary_of: dict[str, str] = {}
    for row in candidates:
        qualification = row.get("qualification")
        if not (isinstance(qualification, Mapping) and qualification.get("code") == HOLDING_CODE):
            kept.append(row)
            continue
        holding = str(row.get("name") or "").strip()
        subsidiaries = [s for s in qualification.get("subsidiaries") or [] if isinstance(s, Mapping)]
        redirected.append({"holding": holding, "subsidiaries": [str(s.get("name") or "") for s in subsidiaries]})
        for sub in subsidiaries:
            sub_siren = str(sub.get("siren") or "").strip()
            if sub_siren and holding:
                subsidiary_of.setdefault(sub_siren, holding)
    return kept, redirected, subsidiary_of


def _drop_excluded_sectors(
    candidates: list[Mapping[str, Any]], exclude_sectors: list[str]
) -> tuple[list[Mapping[str, Any]], int]:
    """#3706 — retire les candidats dont l'activité tombe dans un secteur EXCLU.
    NAF absent ou illisible = gardé (ni preuve d'adéquation, ni d'exclusion)."""
    if not exclude_sectors:
        return candidates, 0
    from app.services.application_sector_naf import naf_prefixes_for_sectors
    from app.services.naf_sections import SECTOR_TO_NAF_SECTION, naf_section_of

    sections = {SECTOR_TO_NAF_SECTION[s] for s in exclude_sectors if s in SECTOR_TO_NAF_SECTION}
    prefixes = set(naf_prefixes_for_sectors([s for s in exclude_sectors if s in _SEARCH_NAF_SECTORS]))
    kept: list[Mapping[str, Any]] = []
    dropped = 0
    for row in candidates:
        code = str(row.get("nafCode") or "")
        digits = "".join(ch for ch in code if ch.isdigit())
        if len(digits) >= 2 and (naf_section_of(code) in sections or digits[:4] in prefixes):
            dropped += 1
            continue
        kept.append(row)
    return kept, dropped


def _drop_known_esn(candidates: list[Mapping[str, Any]]) -> tuple[list[Mapping[str, Any]], int]:
    """#4055.1 (recette prod 14/10) — retire les candidats qui RENCONTRENT STRICTEMENT le
    référentiel des ESN connues (``company_archetype.is_known_esn_name``, même index et même
    règle de préfixe-de-jetons que l'écran Territoire, GA-26 : aucun second nom codé ici).

    Une ESN du registre public est un partenaire potentiel (co-traitance, sous-traitance),
    jamais une cible de ce tour d'horizon — avant ce lot, seule `commercial_fit_note` le
    demandait au MODÈLE, en texte ; « CAPGEMINI TECHNOLOGY SERVICES » sortait quand même dans
    la carte « Cartographie ». Un nom qui ne rencontre PAS le référentiel est gardé (l'absence
    de preuve n'est jamais une exclusion)."""
    kept: list[Mapping[str, Any]] = []
    dropped = 0
    for row in candidates:
        name = str(row.get("name") or "")
        if name and is_known_esn_name(name):
            dropped += 1
            continue
        kept.append(row)
    return kept, dropped


def _split_by_dated_offer(
    candidates: list[Mapping[str, Any]],
) -> tuple[list[Mapping[str, Any]], list[dict[str, str]]]:
    """#4421.3 / #4408.1 — ``(comptes avec une offre datée, comptes sans)``. L'offre vient du moteur compétence
    (``skillEvidence.latestOffer``) ou d'un signal de recrutement DATÉ du compte ; une offre sans date ne se cite
    pas, donc ne justifie pas. Rien n'est inventé : sans offre lue, le compte sort de la liste principale."""
    kept: list[Mapping[str, Any]] = []
    aside: list[dict[str, str]] = []
    for row in candidates:
        dated_signal = any(
            isinstance(sig, Mapping)
            and sig.get("type") == "hiring"
            and re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(sig.get("date") or "").strip()[:10])
            for sig in row.get("signals") or []
        )
        if dated_signal or _skill_evidence_signal(row.get("skillEvidence")) is not None:
            kept.append(row)
            continue
        siren = str(row.get("siren") or "").strip()
        name = str(row.get("name") or "").strip()
        if siren and name and all(entry["siren"] != siren for entry in aside):
            aside.append({"name": name, "siren": siren, "reason": "aucune offre datée correspondant à la demande"})
    return kept, aside


def _split_by_scope(
    candidates: list[Mapping[str, Any]], *, sectors: list[str], headcount: str
) -> tuple[list[Mapping[str, Any]], list[dict[str, str]], int, int]:
    """#3705 — sépare la SÉLECTION de ce qui sort de la demande.

    ``(retenus, hors_demande, activité_non_vérifiée, effectif_non_vérifié)``.
    Un code NAF ou un effectif ABSENT n'est pas une preuve d'adéquation, ni
    d'inadéquation : la ligne reste, comptée comme non vérifiée.
    """
    from app.services.application_sector_naf import naf_prefixes_for_sectors
    from app.services.naf_sections import SECTOR_TO_NAF_SECTION, naf_section_of

    wanted_sections = {SECTOR_TO_NAF_SECTION[s] for s in sectors if s in SECTOR_TO_NAF_SECTION}
    prefixes = set(naf_prefixes_for_sectors([s for s in sectors if s in _SEARCH_NAF_SECTORS]))
    bounds = _HEADCOUNT_BOUNDS.get(headcount) if headcount else None

    kept: list[Mapping[str, Any]] = []
    out_of_scope: list[dict[str, str]] = []
    activity_unverified = 0
    headcount_unverified = 0
    for row in candidates:
        reason = ""
        # #4421.3 / #4408.1 — un voisin ÉTIQUETÉ par le moteur (`widenedBy`) est ce que « Laura élargit seule » a
        # produit : il porte son palier et reste dans la liste. L'étiquette ne sauve que l'axe qu'elle nomme —
        # une ligne élargie en taille reste soumise au secteur demandé, et inversement.
        widened_axis = (row.get("widenedBy") or {}).get("axis") if isinstance(row.get("widenedBy"), Mapping) else None
        if (wanted_sections or prefixes) and widened_axis != "sector":
            code = str(row.get("nafCode") or "")
            digits = "".join(ch for ch in code if ch.isdigit())
            if len(digits) < 2:
                activity_unverified += 1
            elif naf_section_of(code) not in wanted_sections and digits[:4] not in prefixes:
                reason = "activité hors du secteur demandé"
        if not reason and bounds is not None and widened_axis != "size":
            count = row.get("headcount")
            if isinstance(count, int) and not isinstance(count, bool):
                low, high = bounds
                if (low is not None and count < low) or (high is not None and count > high):
                    reason = "effectif hors de la tranche demandée"
            else:
                headcount_unverified += 1
        if not reason:
            kept.append(row)
            continue
        siren = str(row.get("siren") or "").strip()
        name = str(row.get("name") or "").strip()
        if siren and name:
            entry = {"name": name, "siren": siren, "reason": reason}
            activity = str(row.get("nafLabel") or "").strip()
            if activity:
                entry["activity"] = activity
            out_of_scope.append(entry)
    return kept, out_of_scope, activity_unverified, headcount_unverified


_WIDENING_LABELS = (
    ("department", "le département « {value} » → sa région entière"),
    ("headcount", "la tranche d'effectif « {value} » → la tranche voisine au-dessus"),
    ("region", "la région → une région voisine"),
    ("sectors", "le secteur « {value} » → un secteur voisin, que je te nommerai"),
)


def _no_retained_reason(
    out_of_scope: Sequence[Mapping[str, str]], *, esn_excluded: int = 0, excluded_by_sector: int = 0
) -> str:
    """#3905.4 — UNE phrase : combien le registre a rendu, et le critère qui les a TOUS écartés
    (ou, à défaut d'un critère unique, la ventilation). Jamais d'invention : des comptes mesurés."""
    reasons: dict[str, int] = {}
    for entry in out_of_scope:
        reason = str(entry.get("reason") or "").strip()
        if reason:
            reasons[reason] = reasons.get(reason, 0) + 1
    if esn_excluded:
        reasons["entreprise de services du numérique (pas une cible de ce tour)"] = esn_excluded
    if excluded_by_sector:
        reasons["secteur que tu as exclu"] = excluded_by_sector
    total = sum(reasons.values())
    if not total:
        return ""
    if len(reasons) == 1:
        return f"Les {total} entreprises rendues par le registre ont toutes été écartées : {next(iter(reasons))}."
    detail = ", ".join(f"{count} : {reason}" for reason, count in reasons.items())
    return f"Les {total} entreprises rendues par le registre ont été écartées ({detail})."


_SIZE_CLASS_LABELS = (("GE", "grand groupe", "grands groupes"), ("ETI", "ETI", "ETI"), ("PME", "PME", "PME"), ("TPE", "TPE", "TPE"))


def _size_line(candidates: Sequence[Any], shown: set[str]) -> str:
    """#4408.1 — « Taille des comptes rendus : 8 PME, 2 ETI ». Seules les tailles PRÉSENTES s'écrivent (jamais « 0
    grand groupe » : une absence ne fait aucune ligne) ; les comptes sans taille lisible sont nommés à part, jamais
    rangés dans une taille devinée. Vide si aucune taille n'est lisible."""
    counts: dict[str, int] = {}
    unknown = 0
    for row in candidates:
        if not isinstance(row, Mapping) or str(row.get("siren") or "") not in shown:
            continue
        size = str(row.get("sizeClass") or "").strip().upper()
        if size in {code for code, _, _ in _SIZE_CLASS_LABELS}:
            counts[size] = counts.get(size, 0) + 1
        else:
            unknown += 1
    parts = [
        f"{counts[code]} {one if counts[code] == 1 else many}" for code, one, many in _SIZE_CLASS_LABELS if code in counts
    ]
    if not parts:
        return ""
    if unknown:
        parts.append(f"{unknown} sans taille renseignée")
    return "Taille des comptes rendus : " + ", ".join(parts)


def _widening_proposal(criteria: Mapping[str, Any]) -> str:
    """#3704 / #4408.1 — ce qui reste hors de l'échelle AUTOMATIQUE, dit comme un FAIT et jamais comme un palier
    « pas lancé » : le département est déjà monté à sa région dans ce tour (`_widen_department_to_region`), et
    c144 (Louis 27/10 au soir) plafonne l'automatique à la région. Laura n'écrit jamais qu'un palier « n'a pas été
    lancé » ni « tu veux élargir ? » : elle nomme le palier ATTEINT ; la France entière est un geste explicite."""
    del criteria
    return (
        "L'élargissement automatique est allé jusqu'à son plafond (la région) : nomme le palier atteint. La France "
        "entière n'est pas un palier automatique — elle ne se cherche que si la personne la demande ; ne commente "
        "aucun palier non parcouru et ne demande pas la permission d'élargir."
    )


def _pick_known(raw: Any, allowed: tuple[str, ...]) -> list[str]:
    """Ne garde que les valeurs du vocabulaire de l'écran, dédupliquées, dans
    l'ordre canonique. Une valeur inventée par le modèle est écartée — pas
    transmise à un filtre qui l'ignorerait silencieusement."""
    wanted = {str(v).strip().lower() for v in (raw if isinstance(raw, list) else []) if str(v).strip()}
    return [value for value in allowed if value in wanted]


async def _resolve_city_department(city: str) -> str | None:
    """#3762 — RÉFUTÉ EN PRODUCTION le 06/10/2026 : « ouvre mon périmètre à
    Montpellier et périphérie » (département 34, Hérault) rendait un classement
    filtré sur le département 76 (Seine-Maritime). Cause : `find_accounts` et
    `run_account_search` ne demandaient au modèle QUE le code département,
    jamais la ville — le modèle devait donc le DEVINER de mémoire, et s'est
    trompé. Même défaut que celui documenté dans
    `discover_request_reading.py` pour Découvrir : « une VILLE n'est jamais
    devinée [...] c'est l'appelant qui le fait résoudre par la source
    officielle ».

    Résout désormais ``city`` par la même source officielle que Découvrir et
    le vivier (`geo-communes`, `data_sources/geo_communes.py`). Rend ``None``
    si la source est muette ou si aucune commune ne correspond EXACTEMENT —
    jamais un département deviné pour compenser ; l'appelant le NOMME alors
    (`city_not_resolved`) plutôt que de le taire.
    """
    from app.services.data_sources.geo_communes import resolve_commune_by_name

    cleaned = str(city or "").strip()
    if not cleaned:
        return None
    commune = await resolve_commune_by_name(cleaned)
    department = commune.get("department") if commune else None
    return str(department).strip().upper() if department else None


def _cv_experience(entry: Any) -> dict[str, Any]:
    """#3889.3 (lot M13, 09/10) — une expérience lue dans un CV autorisé, champ par
    champ : le projet décrit (`project`) garde sa période, sa source (l'extrait du CV)
    et sa NATURE — celle du chemin, une expérience déclarée (`cv_experience`), jamais
    une mission ni un objet Projet. Ce qui n'est pas écrit reste ``None``."""
    row = entry if isinstance(entry, Mapping) else {}

    def _text(key: str) -> str | None:
        value = row.get(key)
        return value.strip() or None if isinstance(value, str) else None

    return {
        "client": _text("client"),
        "role": _text("role"),
        "from": _text("from"),
        "to": _text("to"),
        "project": _text("project"),
        "nature": "cv_experience",
        "source": _text("source"),
    }


def _distinct_words(raw: Any) -> list[str]:
    """KEVIN-FIX K.6 — les mots dits, nettoyés, sans doublon (insensible à la casse)."""
    out: list[str] = []
    for value in raw if isinstance(raw, list) else []:
        text = " ".join(str(value).split())
        if text and text.casefold() not in {w.casefold() for w in out}:
            out.append(text)
    return out


_REMOTE_ZONE_WORDS = frozenset({"remote", "full remote", "télétravail", "teletravail", "distanciel", "à distance"})


async def _request_zones(said: list[str]) -> tuple[list[str], list[str]]:
    """KEVIN-FIX K.6 — (départements lus, limites à NOMMER). Une ville est résolue par la source
    officielle (jamais devinée) ; « remote » n'est pas un territoire ; une zone illisible se NOMME."""
    departments: list[str] = []
    limits: list[str] = []
    for zone in said:
        if zone.casefold() in _REMOTE_ZONE_WORDS:
            limits.append(
                f"« {zone} » n'est pas un territoire relevé : la veille lit les offres par département, pas le télétravail."
            )
            continue
        is_code = re.fullmatch(r"(?:\d{2,3}|2[AB])", zone.strip(), flags=re.IGNORECASE)
        department = zone.strip().upper() if is_code else await _resolve_city_department(zone)
        if department:
            if department not in departments:
                departments.append(department)
        else:
            limits.append(f"Zone « {zone} » non reliée à un département : je ne la devine pas.")
    return departments, limits


