def _talent_offer_profile(profile: dict[str, Any] | None) -> dict[str, Any]:
    """#4421.4 — placer UN consultant : c'est SA compétence qui trie les offres (l'offre doit la citer), pas les
    métiers déclarés de l'ESN. Toute offre qui la cite — freelance, CDI, recrutement — est un besoin : le tri métier
    du vendeur est levé (``recruitsForClients``), son pack d'offres reste."""
    return {**(profile or {}), "recruitsForClients": True}


async def _talent_fresh_accounts(
    skills: list[str], zone: list[str], profile: dict[str, Any], *, space_key: str, limit: int, budget_s: float
) -> list[dict[str, Any]]:
    """#4421.8 (Louis 24/10, ``c125``) — la MÊME collecte que Découvrir (compétences × zone, ``spaceKey`` : offres
    fraîches, sources payantes sous les plafonds du jour de ``fresh_jobs``), lancée seule quand le cache ne suffit
    pas. Seul un compte dont une offre LUE cite la compétence est rendu ; jamais un chiffre de crédits."""
    from app.routers.discover import DiscoverFilters, DiscoverRegistryRequest, discover_registry
    from app.services.compilers.talent_accounts import accounts_from_skill_search

    request = DiscoverRegistryRequest(
        filters=DiscoverFilters(departments=list(zone), technologiesObserved=list(skills)),
        limit=limit,
        profile_data=profile,
        # Le placement d'un consultant ne lit pas la cible sectorielle de l'ESN (même lecture que le moteur gratuit).
        includeOutOfTarget=True,
        spaceKey=space_key,
    )
    try:
        response = await asyncio.wait_for(discover_registry(request), timeout=budget_s)
    except Exception as exc:  # noqa: BLE001 — une collecte muette ne casse jamais la réponse déjà tenue
        logger.info("#4421.8 — collecte fraîche indisponible : %s", type(exc).__name__)
        return []
    rows = [dict(row) for row in (getattr(response, "candidates", None) or []) if isinstance(row, Mapping)]
    return accounts_from_skill_search(rows, departments=zone)


async def _talent_skill_accounts(
    all_skills: list[str],
    zone: list[str],
    profile: dict[str, Any],
    *,
    max_accounts: int,
    space_key: str | None = None,
) -> tuple[list[dict[str, Any]], list[str]]:
    """Louis 01/11/2026 — UN budget de crédits TheirStack pour tout le tour de recherche (revient sur #5095)."""
    from app.services import discover_skill_offers

    with discover_skill_offers.request_credit_budget():
        return await _talent_skill_accounts_budgeted(
            all_skills, zone, profile, max_accounts=max_accounts, space_key=space_key
        )


async def _talent_skill_accounts_budgeted(
    all_skills: list[str],
    zone: list[str],
    profile: dict[str, Any],
    *,
    max_accounts: int,
    space_key: str | None = None,
) -> tuple[list[dict[str, Any]], list[str]]:
    """#4421.3 / c126 — les comptes du moteur de Découvrir pour un talent, JUSQU'AU volume demandé.

    Palier 0 : les deux premières compétences sur la zone (ce que la recette a lu : 3 comptes). Tant que le volume
    n'est pas tenu : (1) les compétences suivantes de la fiche, (2) la région de la zone, (3) les compétences
    VOISINES de la première (référentiel partagé). Les exacts restent en tête ; chaque palier qui a ajouté un compte
    est NOMMÉ (``widening``) — jamais « moins » sans l'avoir tenté, jamais un élargissement muet."""
    from app.services import discover_skill_offers
    from app.services.compilers.talent_accounts import accounts_from_skill_search, merge_unique_accounts
    from app.services.criteria_referential import skill_widening_tiers
    from app.services.zone_palier import widen_zone_to_region

    profile = _talent_offer_profile(profile)
    step = discover_skill_offers.SKILL_MAX_TERMS
    started = time.monotonic()
    deadline = started + _TALENT_ENGINE_BUDGET_S
    accounts: list[dict[str, Any]] = []
    notes: list[str] = []

    async def _read(terms: list[str], where: list[str]) -> list[dict[str, Any]]:
        if not terms or time.monotonic() >= deadline:
            return []
        try:
            found = await discover_skill_offers.find_skill_accounts(terms, where, profile, deadline=deadline)
        except Exception as exc:  # noqa: BLE001 — le moteur d'offres ne casse jamais la lecture de la veille
            logger.info("KEVIN-FIX K.6 — moteur de Découvrir indisponible : %s", type(exc).__name__)
            return []
        return accounts_from_skill_search(found.accounts, departments=where)

    def _fill(rows: list[dict[str, Any]], note: str) -> None:
        nonlocal accounts
        merged = merge_unique_accounts(accounts, rows)
        if len(merged) > len(accounts):
            notes.append(note)
        accounts = merged

    accounts = await _read(all_skills[:step], zone)
    if len(accounts) >= max_accounts:
        return accounts, notes
    for start in range(step, len(all_skills), step):
        chunk = all_skills[start : start + step]
        _fill(await _read(chunk, zone), "autres compétences de la fiche (" + ", ".join(chunk) + ")")
        if len(accounts) >= max_accounts:
            return accounts, notes
    where = zone
    region = widen_zone_to_region(zone)
    if region is not None:
        label, wide = region
        where = wide
        for start in range(0, len(all_skills), step):
            _fill(await _read(all_skills[start : start + step], wide), f"région {label}")
            if len(accounts) >= max_accounts:
                return accounts, notes
    for _tier, items in skill_widening_tiers(all_skills[0]) if all_skills else []:
        near = [term for _code, term in items][:step]
        _fill(await _read(near, where), "compétences voisines (" + ", ".join(near) + ")")
        if len(accounts) >= max_accounts:
            return accounts, notes
    if space_key and all_skills:
        # #4421.8 — les paliers gratuits n'ont pas tenu le volume : la collecte fraîche part, sans demander.
        left = _TALENT_OFFERS_BUDGET_S - (time.monotonic() - started)
        fresh = await _talent_fresh_accounts(
            all_skills[:step],
            zone,
            profile,
            space_key=space_key,
            limit=max_accounts,
            budget_s=min(_TALENT_FRESH_MAX_S, max(_TALENT_FRESH_MIN_S, left)),
        )
        _fill(fresh, _TALENT_FRESH_NOTE)
    return accounts, notes


def _company_key(name: object) -> str:
    """#4421.3 — le nom d'une entreprise pour la RETROUVER : casse, accents, ponctuation et formes juridiques
    pliés (« ALTEN SAS » = « Alten »). Jamais une inclusion : « Altenia » n'est pas « Alten »."""
    import unicodedata

    text = unicodedata.normalize("NFD", str(name or ""))
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn").casefold()
    words = re.findall(r"[a-z0-9]+", text)
    legal = {"sas", "sasu", "sa", "sarl", "eurl", "snc", "se", "groupe", "group", "france"}
    return " ".join(w for w in words if w not in legal) or " ".join(words)


#: #4421.10 (Louis, QCM 24/10 : « Chercher dans le même tour ») — un compte proposé hors de l'espace reçoit ses
#: personnes à contacter DANS ce tour : trois comptes au plus (les mieux classés), chacun sous un budget qui vit
#: DANS celui des contacts (le tour reste sous 90 s), et au plus `_TALENT_PEOPLE_MAX_PER_SPACE_DAY` recherches par
#: espace et par jour de Paris (même compteur que la collecte fraîche de Découvrir, `fresh_jobs`).
_TALENT_PEOPLE_MAX_ACCOUNTS = 3
_TALENT_PEOPLE_MAX_PER_ACCOUNT = 3
_TALENT_PEOPLE_BUDGET_S = 15.0
_TALENT_PEOPLE_MAX_PER_SPACE_DAY = 60  # #4421.14 — 60/j, décision Louis 25/10
_TALENT_PEOPLE_COUNTER = "people_fresh"
#: Les fonctions cherchées : le recrutement et les décideurs techniques, à qui l'on propose un consultant.
_TALENT_PEOPLE_TITLES = (
    "Responsable recrutement",
    "Chargé de recrutement",
    "Talent Acquisition",
    "DRH",
    "Directeur technique",
    "CTO",
    "DSI",
    "Responsable d'agence",
)
_TALENT_FOUND_OUTSIDE = (
    "Pas encore dans ton espace — personnes trouvées à vérifier (rattachement, fonction), pas encore des contacts."
)
_TALENT_PEOPLE_NO_SPACE = (
    "Recherche de personnes non lancée : je ne retrouve pas ton espace de travail actif — les contacts arrivent "
    "avec l'analyse."
)
_TALENT_PEOPLE_CAPPED = (
    "Recherche de personnes du jour déjà faite pour ton espace — les contacts arrivent avec l'analyse."
)


def _talent_outside_person(hit: Any) -> dict[str, Any] | None:
    """#4421.10 — une personne trouvée hors de l'espace, telle que la source la publie : prénom et nom (masqué si
    la source le masque), fonction, profil public. Jamais une photo, une ville ni rien qui pèserait dans son rang
    (aucun critère protégé) ; jamais un `contact_id` : ce n'est pas encore un contact de l'espace."""
    first = " ".join(str(getattr(hit, "first_name", "") or "").split())
    last = " ".join(str(getattr(hit, "last_name", "") or getattr(hit, "last_name_obfuscated", "") or "").split())
    if not first:
        return None
    person = {
        "name": f"{first} {last}".strip(),
        "first_name": first,
        "title": " ".join(str(getattr(hit, "title", "") or "").split()) or None,
        "linkedin_url": str(getattr(hit, "linkedin_url", "") or "") or None,
        # #4421.15 — la référence OPAQUE de la personne chez la source : le bouton « Obtenir l'e-mail » la renvoie
        # à l'enrichissement existant. Jamais affichée, jamais un nom de fournisseur.
        "person_ref": str(getattr(hit, "id", "") or "").strip() or None,
        "to_verify": True,
    }
    return {key: value for key, value in person.items() if value}


def _talent_prepared_message(person: dict[str, Any], account: dict[str, Any], talent: dict[str, Any]) -> dict[str, Any]:
    """#4421.10b — le mail PRÉPARÉ pour la première personne trouvée : il ne cite que des faits lus (l'offre datée
    du compte, les compétences et la disponibilité retenues de la fiche), jamais le nom du consultant, jamais un
    chiffre inventé. Rien ne part : le commercial le relit et l'envoie (doctrine, le copilote n'envoie jamais)."""
    skills = [str(s) for s in talent.get("skills") or [] if str(s).strip()][:3]
    zones = [str(z) for z in talent.get("zones") or [] if str(z).strip()]
    need = next((n for n in account.get("needs") or [] if isinstance(n, dict) and n.get("title")), None)
    lines = [f"Bonjour {person['first_name']},", ""]
    if need is not None:
        dated = f" publiée le {need['date']}" if need.get("date") else ""
        lines.append(f"J'ai vu votre offre « {need['title']} »{dated}.")
    profile = "Je vous propose un consultant" + (f" {', '.join(skills)}" if skills else "")
    if talent.get("available_from"):
        profile += f", disponible à partir du {talent['available_from']}"
    if zones:
        profile += f", zone {', '.join(zones)}"
    lines += [profile + ".", "", "Seriez-vous disponible pour un échange de 15 minutes cette semaine ?"]
    lines += ["", "Bien à vous"]
    subject = f"Consultant {' / '.join(skills)}" if skills else f"Un consultant pour {account.get('name')}"
    return {
        "status": "prepared",
        "sends_email": False,
        "channel": "email",
        "to": {key: person[key] for key in ("name", "title", "person_ref") if person.get(key)},
        "subject": subject,
        "body": "\n".join(lines),
    }


async def _talent_outside_people(account: dict[str, Any], *, space_key: str | None, talent: dict[str, Any]) -> None:
    """#4421.10 — les personnes à contacter d'UN compte hors espace, et le mail préparé pour la première. Toute
    issue autre qu'un résultat lu (pas d'espace, plafond, délai, erreur, source muette) garde la ligne d'avant ou
    nomme le refus : jamais une personne inventée, jamais un échec du tour."""
    from app.services import apollo, fresh_jobs

    if not space_key:
        account["contacts_note"] = _TALENT_PEOPLE_NO_SPACE
        account["people_search"] = "no_space"
        return
    if not await fresh_jobs.take_space_day(_TALENT_PEOPLE_COUNTER, space_key, _TALENT_PEOPLE_MAX_PER_SPACE_DAY):
        account["contacts_note"] = _TALENT_PEOPLE_CAPPED
        account["people_search"] = "capped"
        return
    name = str(account.get("name") or "").strip()
    try:
        hits, status, _total = await asyncio.wait_for(
            apollo.search_people_with_status(company_name=name, person_titles=list(_TALENT_PEOPLE_TITLES), max_pages=1),
            timeout=_TALENT_PEOPLE_BUDGET_S,
        )
    except Exception as exc:  # noqa: BLE001 — une recherche muette ne casse jamais le tour
        logger.info("#4421.10 — personnes hors espace non lues : %s", type(exc).__name__)
        return
    if status != apollo.ApolloSearchStatus.OK:
        logger.info("#4421.10 — personnes hors espace : %s", getattr(status, "value", status))
        return
    # Un homonyme d'une AUTRE entreprise n'est pas une personne de ce compte.
    people = [
        person
        for hit in hits or []
        if not str(getattr(hit, "organization_name", "") or "").strip()
        or _company_key(getattr(hit, "organization_name", "")) == _company_key(name)
        if (person := _talent_outside_person(hit)) is not None
    ]
    # Le recruteur / le manager passe devant ; seule la FONCTION classe, l'ordre de la source est gardé dedans.
    people.sort(key=lambda p: 0 if _TALENT_REACH_TITLE.search(str(p.get("title") or "")) else 1)
    people = people[:_TALENT_PEOPLE_MAX_PER_ACCOUNT]
    if not people:
        return
    account["prepared_message"] = _talent_prepared_message(people[0], account, talent)
    account["contacts"] = [{key: value for key, value in p.items() if key != "first_name"} for p in people]
    account["contacts_state"] = "found_outside"
    account["contacts_note"] = _TALENT_FOUND_OUTSIDE


async def _talent_account_contacts(
    user_id: str,
    accounts: list[dict[str, Any]],
    *,
    space_key: str | None = None,
    talent: dict[str, Any] | None = None,
) -> None:
    """#4421.3 — les contacts À JOINDRE de chaque compte rendu, posés sur la ligne du compte. Réutilise les
    deux ponts existants (GA-26) : la fiche du portefeuille par son NOM exact (`workspace_accounts`), puis le
    MÊME classement que l'onglet Contacts (`account_contacts`, jusqu'à dix). Rien d'inventé : un compte absent de
    l'espace ou sans contact le DIT (`contacts_note`) ; un pont muet laisse la ligne sans clé (jamais « 0 »).

    #4421.10 — avec ``talent`` (ce que l'outil a retenu du profil), les trois premiers comptes ABSENTS de l'espace
    reçoivent leurs personnes à contacter dans ce même tour, EN PARALLÈLE de la lecture des contacts connus."""
    from app.services import bellum_api
    from app.services.compilers.talent_accounts import TALENT_CONTACTS_MAX

    gate = asyncio.Semaphore(4)

    async def _locate(account: dict[str, Any]) -> None:
        name = str(account.get("name") or "").strip()
        async with gate:
            found = await bellum_api.workspace_accounts(user_id, query=name, sector=None, limit=5)
        if not isinstance(found, dict):
            account["contacts_state"] = "unread"
            return
        rows = [r for r in (found.get("accounts") or []) if isinstance(r, dict) and r.get("account_id")]
        match = next((r for r in rows if _company_key(r.get("company_name")) == _company_key(name)), None)
        if match is None:
            # #4421.3 — jamais analysé dans l'espace : ce n'est PAS « aucun contact connu ».
            account["contacts"] = []
            account["contacts_state"] = "not_in_workspace"
            account["contacts_note"] = _TALENT_NOT_IN_WORKSPACE
            return
        account["account_id"] = str(match["account_id"])

    async def _known(account: dict[str, Any]) -> None:
        async with gate:
            result = await bellum_api.account_contacts(user_id, account["account_id"], limit=TALENT_CONTACTS_MAX)
        if not isinstance(result, dict) or result.get("error"):
            account["contacts_state"] = "unread"
            return
        contacts = [
            {
                key: value
                for key, value in (
                    ("contact_id", row.get("contact_id")),
                    ("name", " ".join(str(row.get("full_name") or "").split())),
                    ("title", row.get("title")),
                    ("email", row.get("email")),
                    ("phone", row.get("phone")),
                )
                if value
            }
            for row in (result.get("contacts") or [])
            if isinstance(row, dict) and row.get("contact_id") and str(row.get("full_name") or "").strip()
        ]
        # Le recruteur / le manager passe devant ; l'ordre du classement est gardé à l'intérieur de chaque groupe.
        contacts.sort(key=lambda c: 0 if _TALENT_REACH_TITLE.search(str(c.get("title") or "")) else 1)
        account["contacts"] = contacts[:TALENT_CONTACTS_MAX]
        if not contacts:
            account["contacts_state"] = "none_known"
            account["contacts_note"] = _TALENT_NO_CONTACT

    async def _all() -> None:
        await asyncio.gather(*(_locate(a) for a in accounts))
        outside = [a for a in accounts if a.get("contacts_state") == "not_in_workspace"]
        first = outside[:_TALENT_PEOPLE_MAX_ACCOUNTS] if talent is not None else []
        searches = [_talent_outside_people(a, space_key=space_key, talent=talent or {}) for a in first]
        await asyncio.gather(*(_known(a) for a in accounts if a.get("account_id")), *searches)

    try:
        await asyncio.wait_for(_all(), timeout=_TALENT_CONTACTS_BUDGET_S)
    except TimeoutError:
        logger.info("#4421.3 — contacts des comptes du talent : lecture coupée à %.0f s", _TALENT_CONTACTS_BUDGET_S)
    # Un compte que la lecture n'a pas atteint le DIT (« non lus »), jamais un silence qui se lirait « rien ».
    for account in accounts:
        if "contacts" not in account and "contacts_state" not in account:
            account["contacts_state"] = "unread"


async def _resolve_city_commune_name(city: str, note_out: dict[str, Any] | None = None) -> str | None:
    """#3876.5 (lot M13, 09/10) — même résolution exacte que
    :func:`_resolve_city_department` (source officielle, jamais devinée), mais
    rend le NOM CANONIQUE de la commune, pas son département.

    `find_accounts` et `run_account_search` changeaient « Marseille » en
    département 13 : chercher à Marseille devenait, en silence, chercher dans
    tout le département — alors que le champ « Ville » de Découvrir borne à la
    commune (`commune_code`, #2490.11). Une ville reste une ville, chez Laura
    comme dans Découvrir (test croisé `tests/test_3876_5_geo_laura_decouvrir.py`).
    `get_territory_overview`, lui, est une vue DÉPARTEMENTALE par conception et
    garde :func:`_resolve_city_department`.

    #4429.6 — une ville mal orthographiée est corrigée par proximité, un homonyme
    prend la plus peuplée : la note (``corrected`` / ``homonym``) est écrite dans
    ``note_out`` pour que Laura la DISE. Jamais un repli muet.
    """
    from app.services.data_sources.geo_communes import resolve_commune_by_name, resolve_commune_noted

    cleaned = str(city or "").strip()
    if not cleaned:
        return None
    commune = await resolve_commune_by_name(cleaned)
    note = commune.get("resolution") if commune else None
    if commune is None:
        commune, note = await resolve_commune_noted(cleaned, fuzzy=True)
    if note and commune and note_out is not None:
        note_out.update(note)
    name = str(commune.get("name") or "").strip() if commune else ""
    return name or None


# #3707 (R2 07/10) — technologies qui ne sont JAMAIS une raison sociale : si le modèle les envoie dans
# `keywords`, elles sont reprises comme techno (le registre les lirait comme un nom et rendrait 0).
_TECHNOLOGY_TERMS = frozenset(
    {
        "java", "python", "javascript", "typescript", "node", "nodejs", "react", "angular", "vue", ".net", "dotnet",
        "c#", "c++", "php", "ruby", "golang", "rust", "scala", "kotlin", "cobol", "sap", "abap", "salesforce",
        "servicenow", "sql", "nosql", "mongodb", "postgres", "postgresql", "kafka", "spark", "hadoop",
        "snowflake", "databricks", "docker", "kubernetes", "k8s", "terraform", "ansible", "aws", "azure", "gcp",
        "devops", "mainframe", "powerbi", "talend", "informatica", "django", "flask",
    }
)  # fmt: skip


# LUDB.9 — des MÉTIERS (et « freelance ») que Laura glisse dans `keywords` : le registre lit ce champ comme
# une RAISON SOCIALE, donc « méthodes qualité » + région AURA rendait 0 compte. Ce sont des besoins de
# recrutement, jamais un nom ; « freelance » n'est jamais une cible d'un espace d'ESN.
_JOB_TERMS = frozenset(
    {
        "méthodes", "methodes", "qualité", "qualite", "maintenance", "production", "automatisme",
        "automatismes", "chaudronnerie", "soudure", "usinage", "logistique", "hse", "be", "recrutent",
        "recrute", "recrutement", "freelance", "freelances", "indépendant", "indépendants",
        "independant", "independants", "et", "ou", "/",
    }
)  # fmt: skip
_NEVER_TARGET_TERMS = frozenset({"freelance", "freelances"})


def _is_referential_skill(word: str) -> bool:
    from app.services.criteria_referential import canonical_skill

    return canonical_skill(word.strip("()/,;")) is not None


def _split_technologies(
    raw_technologies: Any, keywords: str, *, reclassify: bool, hiring: bool = False
) -> tuple[list[str], str]:
    """#3707 — (technologies demandées, mots-clés RESTANTS). Les technologies viennent du champ dédié ;
    des `keywords` qui ne sont QUE des technologies y sont repris et vidés. Une vraie raison sociale
    (« Crédit Agricole », « Sopra ») reste un filtre de nom.

    #4438.1 — ``hiring`` : la demande est « qui RECRUTENT en X ». X est alors une compétence ou une famille
    (« data », « cloud »), lue dans les OFFRES — jamais une raison sociale : « data » rendait 8 comptes dont le
    NOM contenait « data ». Les mots de remplissage (« recrutent », « et ») tombent, le reste devient technologie."""
    techs: list[str] = []
    for value in raw_technologies if isinstance(raw_technologies, list) else []:
        text = str(value).strip()
        if text and text.lower() not in {t.lower() for t in techs}:
            techs.append(text)
    words = [w for w in keywords.replace(",", " ").split() if w]
    if hiring and words:
        for word in words:
            if word.lower().strip("()/,;") in _JOB_TERMS or word.lower() in {t.lower() for t in techs}:
                continue
            techs.append(word)
        return techs, ""
    # `reclassify` : seulement quand un secteur ou une zone cadre la recherche — SANS cadre, « SAP » peut
    # être la société qu'on cherche par son nom.
    # #4433.3 — « des comptes qui cherchent du Clojure à Toulouse » : une compétence du RÉFÉRENTIEL (Clojure,
    # Elixir, Haskell…) est une techno au même titre que la liste ci-dessus (GA-26 : le référentiel partagé, pas
    # une seconde liste) — sinon elle partait comme raison sociale et seule la ZONE s'élargissait.
    if reclassify and words and all(w.lower().strip("()") in _TECHNOLOGY_TERMS or _is_referential_skill(w) for w in words):
        for word in words:
            if word.lower() not in {t.lower() for t in techs}:
                techs.append(word)
        keywords = ""
    # LUDB.9 — cadré par un secteur ou une zone, des mots de MÉTIER ne sont pas un nom d'entreprise.
    elif reclassify and words:
        lowered = [w.lower().strip("()/,;") for w in words]
        if all(w in _JOB_TERMS or not w for w in lowered) or any(w in _NEVER_TARGET_TERMS for w in lowered):
            keywords = ""
    return techs, keywords


async def _account_name_for(account_id: Any, user_id: str) -> str:
    """Nom canonique du COMPTE possédé — l'ancre org propre de l'enrichissement.
    "" quand on ne sait pas : mieux vaut pas d'ancre qu'un libellé inventé."""
    dossiers = await _owned_account_dossiers([str(account_id or "")], user_id)
    return str(dossiers[0].get("company_name") or "").strip() if dossiers else ""


# #3195.1-.4 (rouvert, recette prod 29/09, « Zorbatek Consulting ») — « pas parmi
# les comptes analysés de ton espace… je n'ai pas interrogé de source publique »
# puis rien : l'inconnu était NOMMÉ mais sans geste. Le refus « introuvable »
# des outils de compte porte donc le geste suivant, là où le modèle le lit.
_UNKNOWN_ENTITY_NEXT_STEP = (
    "« Introuvable dans le portefeuille » n'est pas la preuve que l'entité n'existe pas. Nomme ce qui "
    "manque, puis fais le geste suivant TOI-MÊME dans ce tour : `web_search` sur le nom (lecture "
    "gratuite, source publique) pour dire ce que tu en apprends. Puis, si l'analyser répond à la "
    # #3859 (recette prod 09/10) — cette ligne disait « jamais lancé sans accord », qui
    # contredit c84 (« une analyse, une recherche ou un enrichissement demandés en langage
    # naturel partent DIRECTEMENT ») : Laura s'appuyait sur ce texte pour PROPOSER une analyse
    # (confirmation) au lieu de la lancer elle-même, dans le même tour.
    "demande, lance-la toi-même (`plan_account_analysis` puis `start_account_analysis`, c84 : "
    "aucune carte à valider) — ou une alternative — jamais une impasse, jamais un renvoi vers un "
    "site à consulter."
)


def _with_unknown_next_step(result: Any) -> Any:
    if isinstance(result, dict) and "introuvable dans votre portefeuille" in str(result.get("error") or ""):
        return {**result, "next_step": _UNKNOWN_ENTITY_NEXT_STEP}
    return result


async def execute_chat_tool(
    name: str,
    tool_input: dict[str, Any],
    *,
    user_id: str,
    profile_data: dict | None,
    crm_connected: bool = False,
    crm_provider: str = "",
    person_timezone: str | None = None,
    workspace_timezone: str | None = None,
    context_mode: str | None = None,
    excluded_families: list[str] | None = None,
    exclude_workspace_data: bool = False,
) -> dict[str, Any]:
    """Point d'entrée public — audite CHAQUE dispatch (#2438.3) avant de rendre
    la main à `_execute_chat_tool_dispatch`.

    `excluded_families` (#3708, recette prod 09/10) — les sources que la
    personne a décochées pour CE fil (« Outils et sources »). Ne change pas
    quels outils sont OFFERTS (ça, c'est `tools_for`/`missing_capabilities`,
    en amont) : sert aux outils GÉNÉRALISTES (comme `get_account_preflight`,
    qui couvre contacts/comité/CRM dans le même appel) à ne pas faire fuiter
    une section exclue dans leur résultat — jamais un second filtre, juste la
    donnée que ``chat_orchestrator`` a déjà.

    `exclude_workspace_data` (#3853, recette prod 09/10) : la portée « Sans les
    données de l'espace » (`req.exclude_workspace_data`, `context_mode.py`).
    Retire déjà `search_workspace_accounts` et consorts du catalogue ; ce
    drapeau couvre le reste — `run_account_search`, qui N'EST PAS un outil de
    portefeuille mais dont le rapprochement par SIREN (`_attach_owned_account_ids`)
    lisait quand même la table `accounts`. `False` (le défaut) : comportement
    byte-identique.

    `context_mode` (#2454.4/.5/.9) : le mode de contexte RÉSOLU du tour
    (`my_activity` / `one_off_mission` / `neutral`, `laura-context-mode.ts`),
    tel que `chat.py` l'a déjà lu (`req.context_mode`). Ne sert QU'à `find_accounts`
    — la carte qui ouvre Découvrir emporte le mode pour que le clic ne le perde
    pas. `None` (le défaut de tous les appelants d'avant ce lot) : comportement
    byte-identique, aucune clé `context_mode` sur la proposition.

    L'audit englobe aussi l'outil inconnu : un appel qui échapperait à la
    journalisation serait exactement le trou que ce lot referme. Le
    `workspace_id` écrit vient de `record_tool_call` → `resolve_workspace_id`,
    jamais d'un paramètre libre.

    Le résultat passe aussi par `sanitize_tool_result` (#2438.6) avant de
    revenir à l'appelant : aucun secret ni identifiant d'un autre workspace ne
    doit atteindre le modèle ou l'utilisateur, quel que soit l'outil.

    #1956.21 — puis par `guard_shared_corpus_pii_reporting_leak` : les outils
    dont le corpus est PARTAGÉ entre espaces (mémoire marché, partenaires,
    territoire) ne promettent AUCUNE identité de personne ; un e-mail ou un
    téléphone qui s'y glisserait serait un bug, jamais une donnée légitime —
    contrairement aux outils qui lisent le portefeuille de l'appelant
    (`get_account_contacts`…), que cette garde ne touche jamais.

    #2879 (#2442.15, lot V36) — une fuite RÉELLEMENT détectée (pas seulement
    corrigée en silence) s'écrit dans `security_events.kind = 'leak_detected'`
    (`record_leak_detected`), la onzième condition d'alerte de LAU-FINAL-156.
    Fail-soft : cette écriture ne doit jamais empêcher de rendre le résultat
    déjà nettoyé à l'appelant.
    """
    try:
        result = await _execute_chat_tool_dispatch(
            name,
            tool_input,
            user_id=user_id,
            profile_data=profile_data,
            crm_connected=crm_connected,
            crm_provider=crm_provider,
            person_timezone=person_timezone,
            workspace_timezone=workspace_timezone,
            context_mode=context_mode,
            excluded_families=excluded_families,
            exclude_workspace_data=exclude_workspace_data,
        )
        # #4288.1 (#3905.5) — chaque compte rendu porte son origine en clair (espace / registre / web).
        from app.services import chat_accounts_cascade

        result = chat_accounts_cascade.tag_origin(name, result)
        status = "error" if isinstance(result, dict) and result.get("error") else "done"
        # #2879 (#2442.14) — deux soupçons lus AVANT la purge (qui retire la clé
        # d'espace) : identifiant d'espace présent, consigne d'injection. Des
        # booléens seulement ; jamais le contenu détecté.
        cross_tenant = detect_cross_tenant_key(result)
        injection = detect_prompt_injection(result)
        cleaned, leaked = guard_shared_corpus_pii_reporting_leak(name, sanitize_tool_result(result))
        # #4183 — ni personne d'un autre espace, ni espace contributeur, ni fournisseur.
        cleaned, identity_leaked = redact_foreign_identity(name, cleaned)
        # #3769.7 — une seule casse pour la ville du siège, quelle que soit la source du registre.
        cleaned = normalize_cities(cleaned)
        leaked = leaked or identity_leaked
        if leaked:
            await record_leak_detected(name, user_id=user_id)
        if cross_tenant:
            await record_cross_tenant_suspected(name, user_id=user_id)
        if injection:
            await record_injection_suspected(name, user_id=user_id)
        # #2445.6 (#2442.16, épopée #2766) — le producteur de donnée du bac à
        # sable de rejeu : `turn_id` posé par `chat.py` (`chat_turn_context`),
        # jamais deviné. Hors d'un tour de chat réel (tests, autres
        # appelants), `current_turn_id()` rend `None` : comportement
        # byte-identique, aucune écriture.
        turn_id = current_turn_id()
        if turn_id and name not in _BODY_BEARING_TOOLS:
            await record_tool_call_snapshot(turn_id, name, cleaned, user_id=user_id)
        return _with_unknown_next_step(cleaned)
    except Exception:
        status = "error"
        raise
    finally:
        await record_tool_call(name, user_id=user_id, status=status)


