async def _prepare_message_audience(
    contact_ids: list[str],
    tool_input: dict[str, Any],
    *,
    channel: str,
    user_id: str,
    profile_data: dict | None,
) -> dict[str, Any]:
    """#3894.3 — une audience de 2 à 10 destinataires NOMMÉS par l'utilisateur.

    Pas de second moteur : chaque contact passe par le MÊME chemin unitaire
    (`prepare_message_for_contact` : appartenance, opt-out, relance identique,
    collision de collègue). Un refus se NOMME dans `skipped`, il ne coupe pas les
    autres ni ne disparaît en silence. Moins de deux survivants → on retombe sur la
    proposition unitaire (jamais une « audience » d'une personne). Rien n'est écrit."""
    if len(contact_ids) > _MESSAGE_AUDIENCE_MAX_RECIPIENTS:
        return {
            "error": (
                f"{len(contact_ids)} destinataires : au plus {_MESSAGE_AUDIENCE_MAX_RECIPIENTS} à la "
                "fois, pour que chaque message reste relu. Demande lesquels garder."
            )
        }
    recipients: list[dict[str, Any]] = []
    proposals: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for contact_id in contact_ids:
        contact = await _resolve_owned_contact(contact_id, user_id)
        if not contact:
            skipped.append({"contact_name": None, "reason": "Contact introuvable dans votre portefeuille."})
            continue
        single = await _execute_chat_tool_dispatch(
            "prepare_message_for_contact",
            {
                "contact_id": contact_id,
                "channel": channel,
                "angle": tool_input.get("angle"),
            },
            user_id=user_id,
            profile_data=profile_data,
        )
        proposal = single.get("proposal") if isinstance(single, dict) else None
        if not proposal:
            reason = str(single.get("error") or "Préparation impossible pour ce contact.")[:400]
            skipped.append({"contact_name": contact.get("full_name"), "reason": reason})
            continue
        proposals.append(proposal)
        recipients.append(
            {
                "contact_id": proposal.get("contact_id"),
                "contact_name": proposal.get("contact_name"),
                "contact_title": proposal.get("contact_title"),
                "account_id": proposal.get("account_id"),
            }
        )
    if not recipients:
        names = ", ".join(str(s.get("contact_name") or "contact inconnu") for s in skipped)
        return {"error": f"Aucun message préparé ({names}) : " + " ; ".join(s["reason"] for s in skipped)}
    if len(recipients) == 1:
        return {**_proposal(proposals[0]), "skipped": skipped}
    payload: dict[str, Any] = {
        "action": "prepare_message_audience",
        "explicit_multi_contact": True,
        "channel": channel,
        "angle": str(tool_input.get("angle") or "").strip(),
        "recipients": recipients,
        "cost_credits": 0,
        "sends_email": False,
    }
    if skipped:
        payload["skipped"] = skipped
    depends_on = _declared_depends_on(tool_input)
    if depends_on is not None:
        payload["depends_on"] = depends_on
    # #3894 (recette prod R15) — deux brouillons recopiés dans UNE bulle : chaque destinataire a SA
    # carte à valider (dépliée côté écran). Le texte ne les recopie pas.
    return {
        **_proposal(payload),
        "presentation_directive": (
            "Chaque brouillon vit dans SA carte, une par destinataire, avec ses propres actions : "
            "ne recopie PAS les messages dans ta réponse — dis seulement combien de cartes sont "
            "prêtes, pour qui, et que rien n'est envoyé."
        ),
    }


async def _every_recipient_email_known(tool_input: dict[str, Any], user_id: str) -> bool:
    """#3894 — vrai quand CHAQUE destinataire demandé (`contact_id` ou `contact_ids`) porte un e-mail."""
    raw_ids = tool_input.get("contact_ids")
    ids = [str(raw).strip() for raw in raw_ids if str(raw).strip()] if isinstance(raw_ids, list) else []
    single = str(tool_input.get("contact_id") or "").strip()
    if single:
        ids.append(single)
    ids = list(dict.fromkeys(ids))
    if not ids:
        return False
    for contact_id in ids:
        contact = await _resolve_owned_contact(contact_id, user_id)
        if not contact or not str(contact.get("email") or "").strip():
            return False
    return True


async def _execute_chat_tool_dispatch(
    name: str,
    tool_input: dict[str, Any],
    *,
    user_id: str,
    profile_data: dict | None,
    crm_connected: bool = False,
    crm_provider: str = "",
    person_timezone: str | None = None,
    workspace_timezone: str | None = None,
    context_mode: str | None = None,
    excluded_families: list[str] | None = None,
    exclude_workspace_data: bool = False,
) -> dict[str, Any]:
    """Exécute l'outil `name` avec ses arguments, scopé à `user_id`.

    Renvoie le résultat brut de l'action (dict) — ou `{"error": ...}` si l'action
    échoue ou est inconnue. L'ownership est appliqué par la logique métier appelée.

    `crm_connected` / `crm_provider` = l'état d'intégration RÉEL, résolu
    server-side par le chat-context NestJS. Défaut = le pire cas honnête (aucun
    CRM), pour qu'un appelant qui les omet ne puisse jamais proposer un export
    vers une connexion qui n'existe pas.

    `person_timezone` / `workspace_timezone` (#1958.2/.3) = les deux marches de
    l'escalier que `schedule_reminder_for_contact` ne connaît pas déjà par le
    contact lui-même (`resolve_applicable_timezone`, `app/prompts/current_time.py`).
    Défaut `None` = ancien appelant : comportement byte-identique.
    """
    if name == "list_records":
        # #4065 (lot LISTINGS, 12/10) — « liste-moi… » depuis n'importe quelle source branchée :
        # chaque source relit le pont EXISTANT, les sources décochées sont NOMMÉES absentes.
        from app.services import record_listing

        return await record_listing.run_list_records(
            user_id,
            tool_input,
            excluded_families=excluded_families,
            exclude_workspace_data=exclude_workspace_data,
        )

    if name == "compile_day_closure":
        # #2392 — la clôture se compile côté NestJS ; ici, on la RELAIE en carte.
        from app.services import bellum_api

        if not bellum_api.is_configured():
            return {"error": "Je n'ai pas accès à tes tâches depuis ici : la clôture ne peut pas être compilée."}
        closure = await bellum_api.day_closure(user_id, time_zone=person_timezone)
        if closure is None:
            # Jamais une clôture vide : elle se lirait « journée bouclée ».
            return {"error": "Tes tâches n'ont pas répondu : je ne peux pas clôturer ta journée maintenant."}
        return _proposal({"action": "day_closure", "cost_credits": 0, "closure": closure})

    if name == "compare_accounts":
        # Import local : évite un cycle (routers → services → routers) au chargement.
        from app.routers.compare import CompareRequest, compare_accounts

        account_ids = [str(x) for x in (tool_input.get("account_ids") or []) if x]
        if len(account_ids) < 2:
            return {"error": "Il faut au moins deux comptes à comparer."}
        # Fraîcheur des dossiers comparés : le router de comparaison ne renvoie
        # que le verdict du modèle. Sans cette lecture, le copilote comparerait
        # un dossier de mars et un dossier d'hier sans jamais le dire.
        dossiers = await _owned_account_dossiers(account_ids, user_id)
        result = await compare_accounts(
            CompareRequest(account_ids=account_ids, user_id=user_id, profile_data=profile_data)
        )
        # `compare_accounts` renvoie {"success": True, "data": {...}} — on remonte la donnée.
        data = result.get("data", result) if isinstance(result, dict) else {"result": result}
        if dossiers and isinstance(data, dict):
            data = {**data, "dossiers": dossiers}
        return data

    # LOT (15/10) DATA-B — trois lectures du dossier déjà collecté, jamais un appel externe.
    if name in LAURA_DOSSIER_TOOL_NAMES:
        if name == "get_company_public_facts":
            return await execute_get_company_public_facts(tool_input, user_id)
        if name == "get_account_firmographics":
            return await execute_get_account_firmographics(tool_input, user_id)
        return await execute_get_account_org_chart(tool_input, user_id)

    # #4282.9 / #4281.1 (19/10) — deux LECTURES de la base commune, aucun crédit.
    if name in RADAR_TOOL_NAMES:
        if name == "technology_radar":
            return await execute_technology_radar(tool_input)
        return await execute_search_historical_needs(tool_input, user_id)

    # #4055.4/.6 (17/10) — deux LECTURES agrégées : ce qui manque sur un compte, les comptes par secteur.
    if name in COMPLETION_TOOL_NAMES:
        if name == "complete_account":
            return await execute_complete_account(tool_input, user_id)
        if name == "dismiss_completion_person":
            return await execute_dismiss_completion_person(tool_input, user_id)
        return await execute_get_portfolio_sectors(tool_input, user_id)

    if name == "get_account_briefing":
        # #2852.6-53 (lot V22, suite) — même enveloppe canonique que les
        # outils précédents, sur une lecture à UN seul enregistrement (pas de
        # liste, pas de `total`/`truncated`).
        from fastapi import HTTPException

        from app.models.tool_result_envelope import ToolResultEnvelope, ToolResultStatus, error_envelope
        from app.services.ownership import fetch_owned_account
        from app.services.supabase_client import get_supabase

        account_id = str(tool_input.get("account_id") or "").strip()
        if not account_id:
            return {
                "error": "Un identifiant de compte est requis.",
                **error_envelope(
                    status=ToolResultStatus.INVALID_INPUT,
                    result_type="account_briefing",
                    error_code="missing_account_id",
                    suggested_next_step="Précise l'identifiant du compte, puis relance.",
                ).to_wire(),
            }
        try:
            account = await fetch_owned_account(get_supabase(), account_id, user_id)
        except HTTPException:
            # Ownership/404 → surface a clean error, never another user's data.
            # Même décision que #2852.34 : `empty`, jamais un statut distinct
            # qui révélerait qu'un compte étranger existe.
            return {
                "error": "Compte introuvable dans votre portefeuille.",
                **ToolResultEnvelope(
                    status=ToolResultStatus.EMPTY,
                    result_type="account_briefing",
                    sources_consulted=["bellum_workspace"],
                    sources_succeeded=["bellum_workspace"],
                ).to_wire(),
            }
        # #3212.3(b) (épopée #3235) — `versioning`/`verdict_revision` vivent sur
        # `analysis_runs` côté NestJS (aucune RLS, jamais lu directement par
        # Supabase depuis l'IA — voir `CopilotAccountVersioningController`).
        # `None` = pont éteint, réseau en échec, ou aucun run : pas de clé
        # plutôt qu'une version ou une révision inventée.
        from app.services import bellum_api

        versioning_payload = await bellum_api.account_versioning(user_id, account_id)
        extra: dict[str, Any] = {}
        if isinstance(versioning_payload, dict):
            if versioning_payload.get("versioning"):
                extra["versioning"] = versioning_payload["versioning"]
            # #3235 (14/10) — les verdicts de la comparaison sont NOMMÉS comme ceux de la fiche.
            comparison_has_objective = (
                True if profile_data is _PROFILE_DATA_UNSET else _profile_has_objective(profile_data)
            )
            if versioning_payload.get("verdictRevision"):
                extra["verdict_revision"] = _named_verdict_payload(
                    versioning_payload["verdictRevision"], has_objective=comparison_has_objective
                )
            # #3235 (recette 13/10, Thales) — la COMPARAISON des deux dernières analyses, rendue même quand
            # le verdict est identique ou qu'une analyse n'a pas conservé le sien (`status`).
            if isinstance(versioning_payload.get("verdictComparison"), dict):
                extra["verdict_comparison"] = _named_verdict_payload(
                    versioning_payload["verdictComparison"], has_objective=comparison_has_objective
                )
        # #3758 (reste du lot J14) — le dernier compte rendu RÉELLEMENT
        # enregistré pour ce compte, pour la carte `post_meeting_summary`
        # (`known_shape_gate.meeting_recap_block_from_account_briefing`).
        # Additif, best-effort : absent sans compte rendu, jamais une clé vide.
        last_meeting_recap = await _last_meeting_recap(account_id, user_id)
        if last_meeting_recap:
            extra["last_meeting_recap"] = last_meeting_recap
        # LOT (15/10) DATA-B.1 — le briefing ne s'arrête plus au verdict, au plan et aux douleurs : technos,
        # ESN en place, signaux budgétaires, hypothèses qualifiées, réglementations, programmes, sites et
        # implications IT, tels que le dossier les porte (bornés, datés, sourcés en interne). La hiérarchie de
        # confiance vient de la façade NestJS ; `None` (pont éteint) ⇒ seul ce que le dossier porte est relayé.
        from app.services.laura_dossier_reads import intelligence_block

        # Fusion par décompactage, pas par écriture de dict : le dispatcher du copilote ne porte
        # aucun verbe d'écriture (gardes `test_copilote_security_eval`, `test_chat_second_market_tools`).
        intelligence = intelligence_block(
            account.get("raw_analysis") if isinstance(account.get("raw_analysis"), dict) else None,
            await bellum_api.account_intelligence_context(user_id, account_id),
        )
        return {
            **build_account_briefing(account, profile_data=profile_data),
            **extra,
            **intelligence,
            **ToolResultEnvelope(
                status=ToolResultStatus.SUCCESS,
                result_type="account_briefing",
                sources_consulted=["bellum_workspace"],
                sources_succeeded=["bellum_workspace"],
            ).to_wire(),
        }

    if name == "resolve_account_territory":
        from fastapi import HTTPException

        from app.services.ownership import fetch_owned_account
        from app.services.supabase_client import get_supabase

        account_id = str(tool_input.get("account_id") or "").strip()
        if not account_id:
            return {"error": "Un identifiant de compte est requis."}
        sector = str(tool_input.get("sector") or "").strip() or None
        if sector is not None and sector not in SECTOR_TERRITORY_PREFERENCE:
            # Un secteur inventé par le modèle ne doit jamais orienter le
            # classement en silence — même contrat que les critères Découvrir.
            sector = None
        try:
            account = await fetch_owned_account(get_supabase(), account_id, user_id)
        except HTTPException:
            return {"error": "Compte introuvable dans votre portefeuille."}
        raw = account.get("raw_analysis") if isinstance(account.get("raw_analysis"), dict) else {}
        # Même repli que partout ailleurs dans le produit (contact-score.ts,
        # coverage.service.ts, account-access.service.ts) : snake_case d'abord,
        # camelCase en repli — jamais un second parseur du même champ (GA-26).
        entities = raw.get("entities_exhaustive") or raw.get("entitiesExhaustive") or []
        if not isinstance(entities, list):
            entities = []
        # #2302.26/.53/.55 — déjà collecté et déjà groupé par entité acheteuse
        # (phase1_research.py:1629, purchasing_thread.py) : une simple lecture,
        # jamais un second calcul des marchés DECP attribués.
        purchasing_thread = raw.get("purchasingThread") if isinstance(raw.get("purchasingThread"), dict) else {}
        by_buyer = purchasing_thread.get("byBuyer")
        if not isinstance(by_buyer, list):
            by_buyer = []
        # #2302.18 — la géographie visée par l'ESN, déjà déclarée à
        # l'onboarding (`ideal_client_territory`, answers-client-ideal.ts) :
        # une simple lecture, jamais un second champ de préférence.
        preferred_regions = (profile_data or {}).get("ideal_client_territory")
        if not isinstance(preferred_regions, list):
            preferred_regions = None
        # #2302.21 — même repli snake_case/camelCase que `confidence.py`
        # (`has_signals`) : une simple lecture, jamais un second calcul.
        recent_signals = raw.get("recentSignals") or raw.get("recent_signals")
        if not isinstance(recent_signals, list):
            recent_signals = None
        else:
            # #4044 — une offre de stage n'est jamais un signal (signaux déjà stockés compris).
            from app.services.internship_posting import drop_internship_signal_rows

            recent_signals = drop_internship_signal_rows(recent_signals)
        # #2302.28 (épopée #2961) — les comptes de référence NOMMÉS, déclarés
        # à l'onboarding (`reference_accounts`, structuré depuis #2961) : une
        # simple lecture, jamais un second calcul ni un rapprochement par nom.
        # #3476 — le profil du chat est en camelCase (`esnAnswersToProfileData`) : on lit les
        # deux formes, sinon `references_comparables` restait vide en production.
        reference_accounts = (profile_data or {}).get("referenceAccounts") or (profile_data or {}).get(
            "reference_accounts"
        )
        if not isinstance(reference_accounts, list):
            reference_accounts = None
        return resolve_commercial_territory(
            entities,
            sector=sector,
            purchasing_by_buyer=by_buyer,
            preferred_regions=preferred_regions,
            recent_signals=recent_signals,
            reference_accounts=reference_accounts,
        )

    if name == "evaluate_account_qualification_filters":
        from fastapi import HTTPException

        from app.services.ownership import fetch_owned_account
        from app.services.supabase_client import get_supabase

        account_id = str(tool_input.get("account_id") or "").strip()
        if not account_id:
            return {"error": "Un identifiant de compte est requis."}
        try:
            account = await fetch_owned_account(get_supabase(), account_id, user_id)
        except HTTPException:
            return {"error": "Compte introuvable dans votre portefeuille."}
        raw = account.get("raw_analysis") if isinstance(account.get("raw_analysis"), dict) else {}
        evaluation = raw.get("evaluation") if isinstance(raw.get("evaluation"), dict) else {}
        score_breakdown = evaluation.get("scoreBreakdown") or evaluation.get("score_breakdown")
        if not isinstance(score_breakdown, list):
            score_breakdown = None
        # Même lecture que `resolve_account_territory` — un seul calcul des
        # marchés DECP déjà attribués, jamais un second parseur (GA-26).
        purchasing_thread = raw.get("purchasingThread") if isinstance(raw.get("purchasingThread"), dict) else {}
        by_buyer = purchasing_thread.get("byBuyer")
        if not isinstance(by_buyer, list):
            by_buyer = None
        return evaluate_qualification_filters(score_breakdown, purchasing_by_buyer=by_buyer)

    if name == "get_account_timeline":
        # #2852.6-53 (lot V22, suite) — même enveloppe canonique que les
        # quatre outils déjà câblés. Cet outil utilise déjà
        # `tool_error_taxonomy` pour ses deux échecs pont : `error_code`/
        # `retryable` restent CEUX-LÀ (contrat actif lu par
        # `tool_resilience.execute_chat_tool_resilient`), on ADDITIONNE
        # seulement `status`/`result_type`/`suggested_next_step` par-dessus —
        # deux vocabulaires d'erreur pour la même situation romprait
        # « un réglage vit à un seul endroit » (GA-26).
        from app.models.tool_result_envelope import (
            ToolResultEnvelope,
            ToolResultStatus,
            db_read_envelope,
            error_envelope,
        )
        from app.services import bellum_api

        account_id = str(tool_input.get("account_id") or "").strip()
        if not account_id:
            return {
                "error": "Un identifiant de compte est requis.",
                **error_envelope(
                    status=ToolResultStatus.INVALID_INPUT,
                    result_type="account_timeline",
                    error_code="missing_account_id",
                    suggested_next_step="Précise l'identifiant du compte, puis relance.",
                ).to_wire(),
            }
        if not bellum_api.is_configured():
            # Même règle que la messagerie et le vivier : on DIT qu'on n'a pas
            # accès, jamais une liste vide qui se lirait « rien ne s'est passé ».
            # #2283.10 (épopée #2983) — la source n'est PAS branchée ici, ce
            # n'est ni une panne (retryable) ni une permission refusée.
            return {
                **tool_error_payload(
                    ToolErrorCode.SOURCE_NOT_COVERED, "Je n'ai pas accès à l'historique de ce compte depuis ici."
                ),
                "status": ToolResultStatus.NOT_COVERED.value,
                "result_type": "account_timeline",
                "suggested_next_step": "Ouvre la fiche du compte pour consulter l'historique directement.",
            }
        result = await bellum_api.account_timeline(user_id, account_id)
        if result is None:
            # #2283.11 (épopée #2983) — pas de réponse du fournisseur interne :
            # retryable, contrairement à la ligne juste au-dessus.
            return {
                **tool_error_payload(
                    ToolErrorCode.TEMPORARILY_UNAVAILABLE, "L'historique de ce compte n'a pas répondu."
                ),
                "status": ToolResultStatus.PROVIDER_ERROR.value,
                "result_type": "account_timeline",
                "suggested_next_step": "Réessaie dans un instant : l'historique n'a pas répondu à temps.",
            }
        if result.get("error"):
            # `account_not_found` couvre « n'existe pas » ET « pas à toi » —
            # même contrat que `_resolve_owned_contact` : un id inventé par le
            # modèle ne donne jamais lieu à une carte. Même décision que
            # #2852.34 : `empty`, jamais un statut distinct qui révélerait
            # qu'un compte étranger existe.
            return {
                "error": "Compte introuvable dans votre portefeuille.",
                **ToolResultEnvelope(
                    status=ToolResultStatus.EMPTY,
                    result_type="account_timeline",
                    sources_consulted=["bellum_workspace"],
                    sources_succeeded=["bellum_workspace"],
                ).to_wire(),
            }
        # GA-318 — `AccountTimelineService` peut rendre jusqu'à 200 événements
        # (`TIMELINE_MAX`) ; on ne relaie jamais ça tel quel au modèle sans le
        # dire. Même plafond que le reste du catalogue (`_LIST_TOOL_CAP`).
        events, truncated = _capped(result.get("events") or [])
        return {
            "events": events,
            "truncated": truncated,
            **db_read_envelope(
                result_type="account_timeline",
                items_count=len(events),
                total_found=None,
                truncated=truncated,
                source="bellum_workspace",
            ).to_wire(),
        }

    if name == "get_account_contacts":
        # #2852.6-53 (lot V22, suite) — même enveloppe canonique que
        # search_workspace_contacts/search_workspace_accounts/get_accounts_by_owner,
        # câblée sur un quatrième outil réel.
        from app.knowledge.buying_committee import sector_committee_seats
        from app.models.tool_result_envelope import (
            ToolResultEnvelope,
            ToolResultStatus,
            db_read_envelope,
            error_envelope,
        )
        from app.services import bellum_api
        from app.services.count_contract import build_count_contract

        account_id = str(tool_input.get("account_id") or "").strip()
        if not account_id:
            return {
                "error": "Un identifiant de compte est requis.",
                **error_envelope(
                    status=ToolResultStatus.INVALID_INPUT,
                    result_type="contact_list",
                    error_code="missing_account_id",
                    suggested_next_step="Précise l'identifiant du compte, puis relance la recherche.",
                ).to_wire(),
            }
        if not bellum_api.is_configured():
            return {
                "error": "Je n'ai pas accès aux contacts de ce compte depuis ici.",
                **error_envelope(
                    status=ToolResultStatus.NOT_COVERED,
                    result_type="contact_list",
                    error_code="bridge_not_configured",
                    suggested_next_step="Ouvre l'écran Contacts de ce compte pour consulter directement.",
                ).to_wire(),
            }
        # #2533 / #2547 — la fonction demandée et « N personnes par entreprise ».
        requested_function = str(tool_input.get("function") or "").strip()[:120]
        bridge_kwargs: dict[str, Any] = {}
        if requested_function:
            bridge_kwargs["title_query"] = requested_function
        raw_limit = tool_input.get("limit")
        if isinstance(raw_limit, int) and not isinstance(raw_limit, bool) and raw_limit > 0:
            bridge_kwargs["limit"] = min(raw_limit, 10)
        result = await bellum_api.account_contacts(user_id, account_id, **bridge_kwargs)
        if result is None:
            return {
                "error": "Les contacts de ce compte n'ont pas répondu.",
                **error_envelope(
                    status=ToolResultStatus.PROVIDER_ERROR,
                    result_type="contact_list",
                    error_code="bridge_unavailable",
                    suggested_next_step="Réessaie dans un instant : le pont Contacts n'a pas répondu à temps.",
                ).to_wire(),
            }
        if result.get("error"):
            # Même contrat que get_account_timeline / get_account_briefing : un
            # id inventé ou hors portefeuille ne donne jamais lieu à une liste.
            # Même décision que #2852.34 : `empty`, jamais un statut distinct
            # qui révélerait qu'un compte étranger existe (anti-énumération).
            return {
                "error": "Compte introuvable dans votre portefeuille.",
                **ToolResultEnvelope(
                    status=ToolResultStatus.EMPTY,
                    result_type="contact_list",
                    sources_consulted=["bellum_workspace"],
                    sources_succeeded=["bellum_workspace"],
                ).to_wire(),
            }
        # #2791 (recette écran 28/09/2026, ROCHE/Pharma) — le lot précédent avait
        # posé `sector_committee_seats` dans `get_account_preflight`, jamais ici :
        # c'est POURTANT cet outil-ci que Laura appelle pour « le comité d'achat
        # de X ». Même fonction partagée (GA-26), même contrat que
        # `_sector_buying_roles_section` (`account_preflight.py`) : un FAIT
        # toujours présent, `named_seats` vide quand le secteur n'a pas de pack
        # connu — jamais un contact deviné.
        account_sector = result.get("account_sector")
        seats = sector_committee_seats(account_sector if isinstance(account_sector, str) else None)
        sector_buying_roles: dict[str, Any] = {"known": True, "named_seats": list(seats)}
        if seats:
            sector_buying_roles["sector"] = account_sector
        # Déjà plafonné à cinq côté API (`CopilotBridgeController.accountContacts`) —
        # relayé tel quel, comme `truncated`.
        # #3231 (#219.8) — la relation déclarée et sa preuve exigée, ligne par ligne.
        contacts = [with_relation_proof(row) for row in (result.get("contacts") or [])]
        # #3894 — relance dans contact_list (Louis 16/10)
        contacts = await _with_follow_ups(contacts, user_id)
        # #AM.54 (#4058) — la fonction demandée est jugée contre le PÉRIMÈTRE : un responsable fiscal n'est jamais
        # rendu comme le bon interlocuteur cyber/GRC ; un voisin autorisé (RSSI, conformité) est proposé comme tel,
        # ou la limite exacte est dite. Fonction hors périmètre connu ⇒ rien ne change.
        from app.services.perimeter_neighbours import read_perimeter

        perimeter = read_perimeter(requested_function, contacts) if requested_function else None
        if perimeter is not None:
            contacts = perimeter.kept
        # Un total illisible reste `None` — « non mesuré » n'est jamais 0.
        total = result.get("total") if isinstance(result.get("total"), int) else None
        truncated = bool(result.get("truncated"))
        payload: dict[str, Any] = {
            "contacts": contacts,
            "total": total,
            "truncated": truncated,
            # #3229 — UNE source pour le nombre annoncé et les cartes : annonce
            # `presented_count` (les lignes ci-dessus), jamais un autre chiffre ;
            # `total` se nomme à part (« 3 sur 37 »).
            "presented_count": len(contacts),
            "sector_buying_roles": sector_buying_roles,
            **db_read_envelope(
                result_type="contact_list",
                items_count=len(contacts),
                total_found=total,
                truncated=truncated,
                source="bellum_workspace",
            ).to_wire(),
        }
        if perimeter is not None and perimeter.limit:
            payload["perimeter_limit"] = perimeter.limit
        # #2533 — la fonction cherchée est NOMMÉE ; introuvable, c'est dit tel
        # quel (jamais un contact approchant), avec le geste qui la cherche.
        if requested_function:
            payload["requested_function"] = requested_function
            if not contacts:
                payload["function_not_found"] = (
                    f"Aucun contact « {requested_function} » n'est connu sur ce compte "
                    f"(parmi {total} contacts)."
                    if total is not None
                    else f"Aucun contact « {requested_function} » n'est connu sur ce compte."
                )
                # #4057 — la fonction cherchée n'est pas connue : la CARTE, jamais un texte seul.
                payload["people_search_directive"] = _PEOPLE_SEARCH_DIRECTIVE
        # #3229 (recette prod 01/10) — la lecture d'UN compte porte aussi son
        # rapport de couverture (même famille « liste de contacts ») : sans lui,
        # « Périmètre de recherche » manquait sous la réponse. Liste plafonnée
        # → seul « détecté » est posé, les autres paliers restent non mesurés.
        from app.services.search_universe import coverage_report_from_contact_list

        # Les lignes d'un compte ne portent pas `decision_role` (champ `group`) :
        # on les déclare tronquées pour que seul « détecté » soit posé — un
        # « 0 classé » serait une absence de colonne lue comme une mesure.
        account_coverage = coverage_report_from_contact_list({**payload, "truncated": True})
        if account_coverage is not None:
            payload["coverage_report"] = account_coverage.to_wire()
        # #3243 (recette prod 03/10, CAPGEMINI, 3e fois) — le challenge « partenaire
        # potentiel » se jouait dans le PROMPT, donc seulement fiche ouverte. Ici le compte
        # est NOMMÉ par l'utilisateur sans fiche : le pont relaie son profil d'acteur (NAF,
        # type) et le MÊME détecteur (GA-26) l'évalue. Sans profil, ou sans type d'acteur
        # établi : aucune clé — jamais un challenge deviné du nom.
        profile = result.get("account_profile")
        if isinstance(profile, dict):
            from app.services.commercial_challenge import detect_partner_prospected_as_client

            challenge = detect_partner_prospected_as_client(profile, company=profile.get("company_name") or None)
            if challenge is not None:
                payload["commercial_challenges"] = [challenge]
        # #213.2/#213.4 (#3207, épopée #3228) — DÉJÀ LÀ : `total` compte des
        # lignes `contacts` déjà déduplipliquées par identité résolue à
        # CHAQUE écriture (`contactIdentityKeys`,
        # apps/api/src/modules/contacts/contacts.service.ts:4438 —
        # `bulkInsert` — et :4785 — `createFromCrmPresence`, les deux SEULES
        # portes d'écriture de cette table) : « une personne dans trois
        # sources ne devient pas trois consultants » est déjà vrai ICI, pour
        # UN compte. `raw_count == deduplicated_count` le DIT plutôt que de
        # le taire — jamais recopié en silence, un caveat nomme la raison.
        # `resolved_count` reste `None` : cette déduplication est PAR COMPTE,
        # jamais inter-comptes (groupe/filiale, personne sur deux comptes) —
        # #213.5, hors de ce lot.
        if total is not None:
            payload["count_contract"] = build_count_contract(
                metric_name="contacts_du_compte",
                object_type="contact",
                unique_key=f"account_contacts:{account_id}",
                scope="compte",
                entity_scope=account_id,
                current_or_historical="current",
                source_layers=["bellum_workspace"],
                raw_count=total,
                deduplicated_count=total,
                caveats=[
                    "Déjà dédupliqué par identité résolue (nom, e-mail, profil) à l'écriture — une "
                    "personne présente dans plusieurs sources ne compte qu'une fois sur CE compte. "
                    "Cette déduplication reste PAR COMPTE : une même personne visible sur un autre "
                    "compte du même groupe ou d'une filiale n'est pas fusionnée ici."
                ],
            ).to_wire()
        return payload

    if name == "search_workspace_contacts":
        # #2294 — une personne à travers TOUS les comptes de l'espace.
        # #2852.6-53 — enveloppe canonique de résultat d'outil (statut, sources,
        # prochain geste) : premier outil câblé, un seul geste à la fois.
        from app.models.tool_result_envelope import ToolResultStatus, db_read_envelope, error_envelope
        from app.services import bellum_api
        from app.services.count_contract import build_count_contract

        query = str(tool_input.get("query") or "").strip() or None
        company = str(tool_input.get("company") or "").strip() or None
        raw_role = str(tool_input.get("role") or "").strip()
        role = raw_role if raw_role in _CONTACT_DECISION_ROLES else None
        # #2294.2 — le secteur/groupe-filiale/fraîcheur du COMPTE. Un critère
        # aussi légitime que `company` : un secteur SEUL borne la recherche
        # tout autant, il ne doit pas être rejeté par la garde « sans critère »
        # juste en dessous.
        sector = str(tool_input.get("sector") or "").strip() or None
        raw_group_role = str(tool_input.get("group_role") or "").strip()
        group_role = raw_group_role if raw_group_role in ("groupe", "filiale") else None
        raw_fresh = tool_input.get("contacts_fresh_within_months")
        contacts_fresh_within_months = (
            int(raw_fresh) if isinstance(raw_fresh, int) and not isinstance(raw_fresh, bool) and raw_fresh > 0 else None
        )
        # #2367 (LAU-FINAL-035, entrée « territoire ») — un critère aussi
        # légitime que `sector` : sans lui dans la garde ci-dessous, une
        # recherche pourtant bornée à une ville serait rejetée à tort.
        location = str(tool_input.get("location") or "").strip() or None
        # #4287.11 — « les N derniers contacts » : le tri par dernière interaction datée est un critère à lui seul.
        recent_first = tool_input.get("recent_first") is True
        sort_by_zone = str(tool_input.get("sort_by") or "").strip() == "zone"
        by_zone = tool_input.get("by_zone") is True
        if not (
            by_zone
            or query
            or company
            or role
            or sector
            or group_role
            or contacts_fresh_within_months
            or location
            or recent_first
            or sort_by_zone
        ):
            # Sans critère, la liste rendrait les derniers contacts CRÉÉS : une
            # liste qui a l'air d'une réponse et n'en est pas une.
            return {
                "error": "Précise un nom, une fonction, une entreprise, un rôle, un secteur, un territoire ou une fraîcheur.",
                **error_envelope(
                    status=ToolResultStatus.INVALID_INPUT,
                    result_type="contact_list",
                    error_code="missing_search_criteria",
                    suggested_next_step=(
                        "Ajoute un nom, une fonction, une entreprise, un rôle, un secteur, un territoire ou une "
                        "fraîcheur, puis relance la recherche."
                    ),
                ).to_wire(),
            }
        if not bellum_api.is_configured():
            # Une liste vide se lirait « on ne connaît personne chez X ».
            return {
                "error": "Je n'ai pas accès aux contacts de l'espace depuis ici.",
                **error_envelope(
                    status=ToolResultStatus.NOT_COVERED,
                    result_type="contact_list",
                    error_code="bridge_not_configured",
                    suggested_next_step="Ouvre l'écran Contacts pour chercher directement.",
                ).to_wire(),
            }
        raw_limit = tool_input.get("limit")
        limit = (
            min(int(raw_limit), _WORKSPACE_CONTACTS_MAX)
            if isinstance(raw_limit, int) and not isinstance(raw_limit, bool) and raw_limit > 0
            else None
        )
        if by_zone:
            # #4982.3 — la répartition par zone : des comptes sur TOUT le portefeuille (même zone que « Trier par zone »).
            breakdown = await bellum_api.workspace_contacts(
                user_id,
                query=query,
                company=company,
                role=role,
                limit=None,
                sector=sector,
                group_role=group_role,
                contacts_fresh_within_months=contacts_fresh_within_months,
                location=location,
                by_zone=True,
            )
            zones = breakdown.get("zones") if isinstance(breakdown, dict) else None
            unknown = breakdown.get("unknown_zone") if isinstance(breakdown, dict) else None
            if not isinstance(zones, list) or not isinstance(unknown, int):
                return {
                    "error": "La répartition par zone n'a pas répondu.",
                    **error_envelope(
                        status=ToolResultStatus.PROVIDER_ERROR,
                        result_type="contact_zone_breakdown",
                        error_code="bridge_unavailable",
                        suggested_next_step="Réessaie dans un instant, ou ouvre l'écran Contacts et clique « Trier par zone ».",
                    ).to_wire(),
                }
            zone_total = breakdown.get("total") if isinstance(breakdown.get("total"), int) else None
            regions = _zone_rows_by_region(zones)
            unknown_label = _french_count(unknown)
            return {
                "zones": zones,
                "regions": regions,
                "region_table": _zone_region_table(regions, unknown),
                "unknown_zone": unknown,
                "total": zone_total,
                "zone_breakdown_directive": (
                    "Rends cette répartition telle quelle : la carte `file_export` de `region_table` (colonnes "
                    "Région, Contacts — une ligne par région, départements sommés, dernière ligne « Lieu inconnu »). "
                    "JAMAIS une carte `contact_list` : elle n'a pas de colonne nombre et le compte disparaîtrait. "
                    f"C'est TOUT le portefeuille ({zone_total} contacts). Les contacts sans lieu connu se COMPTENT à "
                    f"part et se nomment : « lieu inconnu : {unknown_label} » — jamais « 0 » s'il y en a, jamais "
                    "rangés dans une zone, jamais devinés. Ne dis pas que la répartition est inexploitable : ce sont "
                    "des comptes complets, pas un échantillon. Les départements de chaque région sont dans "
                    "`regions` si la personne les demande ; une ligne dont `department` est null a sa région lue dans le "
                    "lieu écrit : « département non dit », jamais un département inventé, et elle compte dans sa région."
                ),
                **db_read_envelope(
                    result_type="contact_zone_breakdown",
                    items_count=len(zones),
                    total_found=zone_total,
                    truncated=False,
                    source="bellum_workspace",
                    scope={"by_zone": True},
                ).to_wire(),
            }
        result = await bellum_api.workspace_contacts(
            user_id,
            query=query,
            company=company,
            role=role,
            limit=limit,
            sector=sector,
            group_role=group_role,
            contacts_fresh_within_months=contacts_fresh_within_months,
            location=location,
            **({"recent_first": True} if recent_first else {}),
            **({"sort": "zone"} if sort_by_zone else {}),
        )
        if result is None:
            return {
                "error": "La recherche de contacts n'a pas répondu.",
                **error_envelope(
                    status=ToolResultStatus.PROVIDER_ERROR,
                    result_type="contact_list",
                    error_code="bridge_unavailable",
                    suggested_next_step="Réessaie dans un instant : le pont Contacts n'a pas répondu à temps.",
                ).to_wire(),
            }
        contacts = result.get("contacts")
        # #3231 (#219.8) — la relation personne↔entreprise DÉCLARÉE et la preuve qu'elle exige.
        items = [with_relation_proof(row) for row in contacts] if isinstance(contacts, list) else []
        # Un total illisible reste `None` — « non mesuré » n'est jamais 0.
        total = result.get("total") if isinstance(result.get("total"), int) else None
        truncated = bool(result.get("truncated"))
        # #2852.12 — la portée EFFECTIVEMENT appliquée, jamais un résumé.
        scope: dict[str, Any] = {}
        if query:
            scope["query"] = query
        if company:
            scope["company"] = company
        if role:
            scope["role"] = role
        if sector:
            scope["sector"] = sector
        if group_role:
            scope["group_role"] = group_role
        if contacts_fresh_within_months:
            scope["contacts_fresh_within_months"] = contacts_fresh_within_months
        if location:
            scope["location"] = location
        if recent_first:
            scope["recent_first"] = True
        if sort_by_zone:
            scope["sort_by"] = "zone"
        payload: dict[str, Any] = {
            "contacts": items,
            "total": total,
            "truncated": truncated,
            # #3229 (Y3 02/10) — même source que get_account_contacts : le nombre annoncé = les lignes rendues.
            "presented_count": len(items),
            **db_read_envelope(
                result_type="contact_list",
                items_count=len(items),
                total_found=total,
                truncated=truncated,
                source="bellum_workspace",
                scope=scope or None,
            ).to_wire(),
        }
        # #3229 (#214.2/.3) — le rapport de couverture de CETTE liste, construit
        # sur la sortie réelle (paliers non mesurables = absents, jamais 0).
        from app.services.search_universe import coverage_report_from_contact_list

        coverage_report = coverage_report_from_contact_list({**payload, "scope": scope})
        if coverage_report is not None:
            payload["coverage_report"] = coverage_report.to_wire()
        if not items and recent_first:
            # #4287.11 — aucune interaction datée dans l'espace : le vide se DIT et propose l'action suivante,
            # il ne s'habille jamais en contacts « récents » non datés.
            payload["recent_empty_directive"] = (
                "Aucune interaction datée (message envoyé, geste du journal) n'est enregistrée dans l'espace : dis-le "
                "en une phrase, SANS inventer de « derniers contacts » ni prendre les premiers d'une liste, puis "
                "propose d'indiquer les contacts à relancer (nom ou entreprise) ou d'ouvrir l'écran Contacts."
            )
        elif not items:
            # #3343 — zéro résultat : la consigne « relance toi-même » voyage AVEC
            # le résultat vide, là où le modèle rédige, jamais seulement dans le prompt.
            payload["second_pass_directive"] = second_pass_directive(scope)
            # #4057 — « les interlocuteurs cyber de X » sans personne dans l'espace : la
            # réponse est LA CARTE de recherche de personnes, jamais un texte « aucun
            # interlocuteur ». La consigne voyage AVEC le résultat vide, là où le modèle rédige.
            if scope.get("company") or scope.get("query"):
                payload["people_search_directive"] = _PEOPLE_SEARCH_DIRECTIVE
        # #213.2/#213.4 (#3207, épopée #3228) — troisième outil câblé, après
        # search_market_memory et get_account_contacts. Même garantie que ce
        # dernier : `contactIdentityKeys` déduplique déjà à l'écriture
        # (contacts.service.ts:bulkInsert/createFromCrmPresence), donc
        # `raw_count == deduplicated_count`. Le caveat diffère : cette
        # recherche traverse TOUS les comptes de l'espace, or la dédup à
        # l'écriture ne l'est QUE PAR COMPTE (`existing = repo.find({
        # account_id })`, contacts.service.ts:4596) — une même personne sur
        # deux comptes distincts (deux clients, ou un groupe et sa filiale)
        # compte une fois par compte, jamais fusionnée entre eux.
        # `resolved_count` reste `None` : cette résolution inter-comptes
        # n'existe nulle part (#213.5, hors de ce lot, comme sur
        # get_account_contacts).
        if total is not None:
            criteria = "&".join(f"{k}={v}" for k, v in sorted(scope.items()))
            payload["count_contract"] = build_count_contract(
                metric_name="contacts_de_l_espace",
                object_type="contact",
                unique_key=f"workspace_contacts:{criteria}",
                scope="espace",
                entity_scope=criteria,
                current_or_historical="current",
                source_layers=["bellum_workspace"],
                raw_count=total,
                deduplicated_count=total,
                caveats=[
                    "Déjà dédupliqué par identité résolue (nom, e-mail, profil) à l'écriture, mais "
                    "SEULEMENT DANS chaque compte — une même personne visible sur deux comptes "
                    "distincts (deux clients, ou un groupe et sa filiale) compte une fois par compte, "
                    "jamais fusionnée entre eux."
                ],
            ).to_wire()
        return payload

    if name == "search_workspace_accounts":
        # #2148.4 (#2848) — un compte déjà analysé, à travers TOUT le portefeuille.
        # #2852.6-53 — même enveloppe canonique que search_workspace_contacts.
        from app.models.tool_result_envelope import ToolResultStatus, db_read_envelope, error_envelope
        from app.services import bellum_api

        query = str(tool_input.get("query") or "").strip() or None
        sector = str(tool_input.get("sector") or "").strip() or None
        if not (query or sector):
            return {
                "error": "Précise un nom d'entreprise ou un secteur.",
                **error_envelope(
                    status=ToolResultStatus.INVALID_INPUT,
                    result_type="account_list",
                    error_code="missing_search_criteria",
                    suggested_next_step="Ajoute un nom d'entreprise ou un secteur, puis relance la recherche.",
                ).to_wire(),
            }
        if not bellum_api.is_configured():
            # Une liste vide se lirait « aucun compte ne correspond dans l'espace ».
            return {
                "error": "Je n'ai pas accès aux comptes de l'espace depuis ici.",
                **error_envelope(
                    status=ToolResultStatus.NOT_COVERED,
                    result_type="account_list",
                    error_code="bridge_not_configured",
                    suggested_next_step="Ouvre l'écran Comptes pour chercher directement.",
                ).to_wire(),
            }
        raw_limit = tool_input.get("limit")
        limit = (
            min(int(raw_limit), _WORKSPACE_ACCOUNTS_MAX)
            if isinstance(raw_limit, int) and not isinstance(raw_limit, bool) and raw_limit > 0
            else None
        )
        result = await bellum_api.workspace_accounts(user_id, query=query, sector=sector, limit=limit)
        if result is None:
            return {
                "error": "La recherche de comptes n'a pas répondu.",
                **error_envelope(
                    status=ToolResultStatus.PROVIDER_ERROR,
                    result_type="account_list",
                    error_code="bridge_unavailable",
                    suggested_next_step="Réessaie dans un instant : le pont Comptes n'a pas répondu à temps.",
                ).to_wire(),
            }
        accounts = result.get("accounts")
        items = accounts if isinstance(accounts, list) else []
        # Un total illisible reste `None` — « non mesuré » n'est jamais 0.
        total = result.get("total") if isinstance(result.get("total"), int) else None
        truncated = bool(result.get("truncated"))
        # #2852.12 — la portée EFFECTIVEMENT appliquée, jamais un résumé.
        scope: dict[str, Any] = {}
        if query:
            scope["query"] = query
        if sector:
            scope["sector"] = sector
        absent_next_step: dict[str, Any] = {}
        # #4288.1 (Louis 29/10) — « des comptes dans <secteur> » : l'espace ne rend rien ⇒ le CODE passe au palier
        # voisin du référentiel, le NOMME avant la liste, et ne rend que des comptes dont SON secteur est du palier.
        if sector and not query and not items and result.get("deleted_match") is not True:
            from app.services.compilers.workspace_sector_widening import palier_line, widen_workspace_sector

            async def _fetch_sector_word(word: str) -> list[Mapping[str, Any]]:
                read = await bellum_api.workspace_accounts(user_id, query=None, sector=word, limit=limit)
                rows = read.get("accounts") if isinstance(read, Mapping) else None
                return [row for row in rows if isinstance(row, Mapping)] if isinstance(rows, list) else []

            widening = await widen_workspace_sector(sector, _fetch_sector_word, limit=limit or _WORKSPACE_ACCOUNTS_MAX)
            if widening and widening.get("accounts"):
                items = list(widening["accounts"])
                total = len(items)
                truncated = False
                absent_next_step["widening"] = {"tier": widening["tier"], "sectors": widening["sectors"]}
                absent_next_step["sector_widening_line"] = palier_line(sector, widening)
                absent_next_step["widening_note"] = (
                    "Le palier est choisi par le serveur (référentiel partagé) : dis `sector_widening_line` en une ligne "
                    "AVANT la liste, garde l'étiquette `widened` de chaque compte, ne cite AUCUN autre secteur et ne "
                    "demande jamais s'il faut élargir."
                )
            elif widening and widening.get("tried"):
                absent_next_step["sector_widening_tried"] = widening["tried"]
                absent_next_step["widening_note"] = (
                    "Aucun compte de l'espace non plus sur les secteurs voisins tentés (`sector_widening_tried`) : dis-le "
                    "en une ligne et passe à l'étape suivante (`find_accounts`). N'invente aucun autre secteur."
                )
        if query and not items and result.get("deleted_match") is True:
            # #3670 (RAW2, décision Louis 11/10) — une fiche SUPPRIMÉE ne ressort jamais : on la NOMME,
            # sans contenu et sans proposer de l'ouvrir. Ni « aucune fiche », ni analyse relancée d'office.
            absent_next_step["deleted_notice"] = (
                f"Une fiche {query} a été supprimée. Dis-le tel quel (« Une fiche {query} a été "
                "supprimée »), jamais « aucune fiche » ; n'en donne aucun contenu et ne propose pas de "
                "l'ouvrir."
            )
        elif query and not items:
            # #3859 (recette prod 10/10, conv 4f1264f3) — « aucune fiche Lactalis… l'analyse reste à
            # lancer » puis rien : trois lots n'avaient touché que des consignes, alors que CE résultat
            # est ce que le modèle lit en répondant. La liste vide d'une recherche PAR NOM porte le
            # geste suivant (c84 : l'analyse part dans le tour) et la vraie raison si elle échoue.
            absent_next_step["next_step"] = (
                "Aucun compte de ce nom dans l'espace : ce n'est pas une impasse. Si la demande "
                "implique cette entreprise (analyse, contacts, décideurs), lance-la TOI-MÊME dans ce "
                "tour — `plan_account_analysis` puis `start_account_analysis` (c84, aucune carte à "
                "valider) ; "
                # #4462.1 — une LISTE de noms : un seul appel, toute la liste, jamais « aucun compte ».
                "plusieurs noms cités, `analyze_named_companies` avec toute la liste. Si le lancement "
                "échoue, donne la VRAIE raison rendue par l'outil (rôle, service "
                "indisponible, frein doux — sans chiffre) — jamais « vérification interne » ni « l'analyse reste à "
                "lancer » sans l'avoir tentée, ni « dès que l'outil sera disponible »."
            )
        return {
            "accounts": items,
            "total": total,
            "truncated": truncated,
            **absent_next_step,
            **db_read_envelope(
                result_type="account_list",
                items_count=len(items),
                total_found=total,
                truncated=truncated,
                source="bellum_workspace",
                scope=scope or None,
            ).to_wire(),
        }

    if name == "get_accounts_by_owner":
        # #3094 — l'inverse de search_workspace_accounts : on part du MEMBRE.
        # #2852.6-53 — enveloppe canonique, avec un statut `ambiguous` PROPRE :
        # « personne ne correspond » et « plusieurs collègues partagent ce
        # prénom » ne se confondent jamais (le NO-GO de #2282).
        from app.models.tool_result_envelope import ToolResultEnvelope, ToolResultStatus, error_envelope
        from app.services import bellum_api

        owner_name = str(tool_input.get("owner_name") or "").strip()
        if not owner_name:
            return {
                "error": "Précise le nom du membre.",
                **error_envelope(
                    status=ToolResultStatus.INVALID_INPUT,
                    result_type="account_list",
                    error_code="missing_owner_name",
                    suggested_next_step="Précise le nom du membre, puis relance la recherche.",
                ).to_wire(),
            }
        if not bellum_api.is_configured():
            return {
                "error": "Je n'ai pas accès au portefeuille de l'espace depuis ici.",
                **error_envelope(
                    status=ToolResultStatus.NOT_COVERED,
                    result_type="account_list",
                    error_code="bridge_not_configured",
                    suggested_next_step="Ouvre l'écran Comptes pour chercher directement.",
                ).to_wire(),
            }
        raw_limit = tool_input.get("limit")
        limit = (
            min(int(raw_limit), _WORKSPACE_ACCOUNTS_MAX)
            if isinstance(raw_limit, int) and not isinstance(raw_limit, bool) and raw_limit > 0
            else None
        )
        result = await bellum_api.workspace_accounts_by_owner(user_id, owner_name=owner_name, limit=limit)
        if result is None:
            return {
                "error": "La recherche par membre n'a pas répondu.",
                **error_envelope(
                    status=ToolResultStatus.PROVIDER_ERROR,
                    result_type="account_list",
                    error_code="bridge_unavailable",
                    suggested_next_step="Réessaie dans un instant : le pont Comptes n'a pas répondu à temps.",
                ).to_wire(),
            }
        member_found = bool(result.get("memberFound"))
        if not member_found:
            candidates = result.get("ambiguousCandidates")
            has_candidates = isinstance(candidates, list) and bool(candidates)
            envelope = ToolResultEnvelope(
                status=ToolResultStatus.AMBIGUOUS if has_candidates else ToolResultStatus.EMPTY,
                result_type="account_list",
                sources_consulted=["bellum_workspace"],
                sources_succeeded=["bellum_workspace"],
                # #2852.12 — la portée EFFECTIVEMENT appliquée : le nom tel
                # que demandé, aucun nom résolu tant que `memberFound` est faux.
                scope={"owner_name": owner_name},
            )
            return {
                "member_found": False,
                "accounts": [],
                **({"ambiguous_candidates": candidates} if has_candidates else {}),
                **envelope.to_wire(),
            }
        accounts = result.get("accounts")
        resolved_owner_name = result.get("ownerName")
        return {
            "member_found": True,
            "owner_name": resolved_owner_name,
            "accounts": accounts if isinstance(accounts, list) else [],
            **ToolResultEnvelope(
                status=ToolResultStatus.SUCCESS,
                result_type="account_list",
                sources_consulted=["bellum_workspace"],
                sources_succeeded=["bellum_workspace"],
                # #2852.12 — le nom RÉSOLU, pas celui tel que demandé : c'est
                # lui que le pont a effectivement retenu.
                scope={"owner_name": resolved_owner_name} if resolved_owner_name else {"owner_name": owner_name},
            ).to_wire(),
        }

    if name == "declare_known_contact":
        # #2313 — RELATION-FIRST ACCOUNT ENTRY. Pur relais vers
        # `relation_first_entry` : aucune logique dupliquée ici (GA-26). Sans
        # I/O — rien n'est persisté, la preuve d'autorisation reste
        # journalisée côté serveur par l'utilisateur (#2373.9).
        from app.services import relation_first_entry as rfe

        entry_kind = str(tool_input.get("entry_kind") or "").strip()
        if entry_kind not in rfe.KNOWN_CONTACT_ENTRY_KINDS:
            return {"error": "Précise comment tu connais cette personne (entry_kind)."}

        requester_user_id = user_id
        owner_user_id = str(tool_input.get("owner_user_id") or "").strip() or None
        owner_permission_granted = bool(tool_input.get("owner_permission_granted"))

        # #2313.2 — "owner" du checklist == QUI porte la relation, transmis
        # EXPLICITEMENT (même pour sa propre relation) : jamais deviné, comme
        # les neuf autres champs.
        known = {field: tool_input.get(field) for field in rfe.VERIFICATION_FIELDS if field != "owner"}
        known["owner"] = owner_user_id
        verification = rfe.verify_before_recommend(known)
        team_network = rfe.team_network_permission_gate(
            owner_user_id=owner_user_id,
            requester_user_id=requester_user_id,
            owner_permission_granted=owner_permission_granted,
        )

        claimed_capability = str(tool_input.get("claimed_capability") or "").strip() or None
        referrer_confirmed = bool(tool_input.get("referrer_confirmed"))
        capability = rfe.relational_capability(verified=verification["ready"], claimed=claimed_capability)
        can_introduce = rfe.can_introduce(capability=capability, referrer_confirmed=referrer_confirmed)

        raw_done_steps = tool_input.get("done_steps") if isinstance(tool_input.get("done_steps"), list) else []
        done_steps = {step for step in raw_done_steps if step in rfe.RELATION_FIRST_SEQUENCE}
        next_step = rfe.next_relation_first_step(done_steps)

        draft_message = tool_input.get("draft_message")
        message_guard: dict[str, Any] | None = None
        if isinstance(draft_message, str) and draft_message.strip():
            message_guard = rfe.no_go_guard(
                message=draft_message,
                capability=capability,
                referrer_confirmed=referrer_confirmed,
                owner_user_id=owner_user_id,
                requester_user_id=requester_user_id,
                owner_permission_granted=owner_permission_granted,
            )

        # #2313.9 — CONTACT PARTI : l'exclusion #2313.8 (`former_employee`,
        # `contact-eligibility.ts`) ne menait nulle part avant cette
        # branche — la personne disparaissait, jamais reclassée comme
        # relation réseau. `departed_from_account` n'est jamais deviné :
        # c'est l'appelant (qui a lu l'exclusion du classement) qui le dit.
        departed_contact: dict[str, Any] | None = None
        if bool(tool_input.get("departed_from_account")):
            departed_contact = rfe.departed_contact_reclassification(
                exclusion_reason=rfe.DEPARTED_CONTACT_EXCLUSION_REASON,
                capability=capability,
            )

        return {
            "entry_kind": entry_kind,
            "verification": verification,
            "capability": capability,
            "can_introduce": can_introduce,
            "team_network": team_network,
            "sequence": {
                "steps": list(rfe.RELATION_FIRST_SEQUENCE),
                "done": sorted(done_steps, key=rfe.RELATION_FIRST_SEQUENCE.index),
                "next_step": next_step,
            },
            "message_guard": message_guard,
            "departed_contact": departed_contact,
        }

    if name == "plan_talent_territory":
        from app.services import bellum_api
        from app.services.compilers.territory_planner import compile_territory_plan

        raw_talents = tool_input.get("talents") if isinstance(tool_input.get("talents"), list) else []
        talent_inputs = [t for t in raw_talents if isinstance(t, dict)]
        consultant_ids: list[str] = []
        for entry in talent_inputs:
            consultant_id = str(entry.get("consultant_id") or "").strip()
            if consultant_id and consultant_id not in consultant_ids:
                consultant_ids.append(consultant_id)
        if len(consultant_ids) < 2:
            return {
                "error": "Il me faut au moins deux talents du vivier — cherche leurs identifiants avec "
                "search_talents. Pour un seul talent, son marché inversé répond déjà."
            }
        if len(consultant_ids) > 4:
            return {"error": "Quatre talents au plus : au-delà, ce n'est plus un terrain de jeu commun."}
        if not bellum_api.is_configured():
            return {"error": "Je n'ai pas accès au vivier depuis ici."}
        facts = await bellum_api.talent_territory_facts(user_id, consultant_ids=consultant_ids)
        if facts is None:
            return {"error": "Le terrain de jeu n'a pas pu être construit : le matching n'a pas répondu."}
        return compile_territory_plan(facts, talent_inputs=talent_inputs, capacity=tool_input.get("capacity"))

    if name == "find_accounts_for_talent":
        # #3816.1 — le marché inversé d'UN talent, en comptes justifiés, dans le fil.
        from app.services import bellum_api
        from app.services.compilers.talent_accounts import (
            TALENT_ACCOUNTS_LIMIT,
            TALENT_ACCOUNTS_MAX,
            compile_talent_accounts,
            talent_zone_departments,
        )

        asked = " ".join(str(tool_input.get("consultant") or "").split())
        # KEVIN-FIX K.6 — ce que la DEMANDE dit (compétences, zone) gagne sur la fiche du vivier.
        said_skills = _distinct_words(tool_input.get("skills"))
        said_zones = _distinct_words(tool_input.get("zones"))
        if not asked and not said_skills:
            return {
                "error": "Dis-moi quel consultant du vivier : son nom suffit — ou décris le profil (compétences et zone)."
            }
        if not bellum_api.is_configured():
            return {"error": "Je n'ai pas accès au vivier depuis ici."}
        request_zones, zone_limits = await _request_zones(said_zones)
        is_id = re.fullmatch(r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}", asked)
        consultant_id, consultant_name = (asked.lower(), asked) if is_id else ("", asked)
        # #4421.3 — la fiche lue (dispo, zones) quand le vivier l'a rendue ; un identifiant seul n'en a pas.
        talent_row: dict[str, Any] = {}
        raw_limit = tool_input.get("limit")
        max_accounts = (
            min(int(raw_limit), TALENT_ACCOUNTS_LIMIT)
            if isinstance(raw_limit, int) and not isinstance(raw_limit, bool) and raw_limit > 0
            else TALENT_ACCOUNTS_MAX
        )
        if asked and not consultant_id:
            found = await bellum_api.search_talents(user_id, query=asked)
            if found is None:
                return {"error": "Le vivier n'a pas répondu."}
            rows = [r for r in (found.get("items") or []) if isinstance(r, dict) and r.get("id")]
            exact = [r for r in rows if " ".join(str(r.get("fullName") or "").split()).casefold() == asked.casefold()]
            picked = exact if exact else rows
            if not picked:
                return {
                    "status": "not_found",
                    "message": f"Je ne trouve aucun consultant « {asked} » dans le vivier de cet espace.",
                }
            if len(picked) > 1:
                return {
                    "status": "ambiguous",
                    "message": f"Plusieurs consultants répondent à « {asked} » : lequel ?",
                    "homonyms": [
                        {
                            "id": r.get("id"),
                            "full_name": r.get("fullName"),
                            "title": r.get("title"),
                            "zones": r.get("zones") or [],
                        }
                        for r in picked[:6]
                    ],
                }
            consultant_id = str(picked[0]["id"])
            consultant_name = " ".join(str(picked[0].get("fullName") or asked).split())
            talent_row = picked[0]
        # #3816.3 — aucune lecture du portefeuille ni du CRM : le marché inversé lit la veille
        # territoriale, donc un espace NEUF (aucun compte suivi) reçoit la même liste.
        said: dict[str, Any] = {}
        if said_skills:
            said["skills"] = said_skills
        if request_zones:
            said["zones"] = request_zones
        if consultant_id and not said:
            reply = await bellum_api.talent_reverse_market(user_id, consultant_id=consultant_id)
        else:
            reply = await bellum_api.talent_reverse_market(user_id, consultant_id=consultant_id or None, **said)
        if reply is None:
            return {"error": "Le marché inversé n'a pas répondu : je ne peux pas lister ses comptes pour l'instant."}
        if not reply.get("found") or not isinstance(reply.get("market"), dict):
            return {
                "status": "not_found",
                "message": f"Je ne trouve pas « {asked} » dans le vivier de cet espace.",
            }
        market = reply["market"]
        # #4421.6 — les besoins déjà ouverts de l'espace, lus EN MÊME TEMPS que les offres (jamais avant elles).
        open_needs = asyncio.ensure_future(_talent_open_needs(user_id, consultant_id)) if consultant_id else None
        # KEVIN-FIX K.6 — même moteur que Découvrir : compétences → offres → employeurs, sur les départements
        # de la zone (dite, ou de la fiche ; une ville connue se rattache à son département sans demander).
        from app.services import discover_skill_offers

        zone = talent_zone_departments(market)
        all_skills = discover_skill_offers.skill_terms([], market.get("skillTerms") or [], limit=None)
        skills = all_skills[: discover_skill_offers.SKILL_MAX_TERMS]
        skill_accounts: list[dict[str, Any]] = []
        widening: list[str] = []
        from app.services import workspace_scope

        # #4421.8 / #4421.10 — l'espace de la personne : seul sésame des offres fraîches et de la recherche de
        # personnes (plafonds du jour, comme Découvrir).
        space_key = await workspace_scope.resolve_workspace_id(user_id)
        if skills and zone:
            skill_accounts, widening = await _talent_skill_accounts(
                all_skills,
                zone,
                profile_data or {},
                max_accounts=max_accounts,
                space_key=space_key,
            )
        compiled = compile_talent_accounts(
            market,
            consultant_id=consultant_id,
            consultant_name=consultant_name or "ce profil",
            skill_accounts=skill_accounts,
            skill_zone=zone if skills else (),
            max_accounts=max_accounts,
        )
        if zone_limits and isinstance(compiled.get("limits"), list):
            compiled["limits"].extend(zone_limits)
        if compiled.get("status") != "ok":
            if open_needs is not None and (workspace_needs := await open_needs):
                compiled["workspace_needs"] = workspace_needs
            return compiled
        # #4421.3 — ce que Laura a RETENU de la fiche, annoncé en une ligne ; une valeur absente n'a pas de clé.
        retained_skills = [str(t) for t in (market.get("skillTerms") or []) if str(t).strip()] or said_skills
        retained = {
            "skills": retained_skills,
            "zones": list(zone) or request_zones,
            "availability": talent_row.get("availability"),
            "available_from": str(talent_row.get("availableFrom") or "")[:10] or None,
        }
        compiled["retained"] = {key: value for key, value in retained.items() if value}
        if widening:
            # #4421.3 — jamais élargi en silence : chaque palier tenté pour tenir le volume se DIT.
            compiled["widening"] = widening
        accounts = compiled.get("accounts")
        if isinstance(accounts, list) and accounts:
            # #4421.10 — les comptes hors espace reçoivent leurs personnes DANS ce tour (même porte, mêmes plafonds).
            await _talent_account_contacts(user_id, accounts, space_key=space_key, talent=compiled["retained"])
            compiled["next_steps"] = _TALENT_NEXT_STEPS
        workspace_needs = await open_needs if open_needs is not None else []
        if workspace_needs:
            compiled["workspace_needs"] = workspace_needs
            compiled["next_steps"] = str(compiled.get("next_steps") or "").strip() + _TALENT_OPEN_NEEDS_STEP
        return compiled

    if name == "find_needs_for_talent":
        # #3865.2 — le matching INVERSE d'UN talent (« à quels besoins répond-il ? »), en
        # besoins justifiés, dans le fil. Même résolveur nom → identifiant que
        # `find_accounts_for_talent` juste au-dessus.
        from app.services import bellum_api

        asked = " ".join(str(tool_input.get("consultant") or "").split())
        if not asked:
            return {"error": "Dis-moi quel consultant du vivier : son nom suffit."}
        if not bellum_api.is_configured():
            return {"error": "Je n'ai pas accès au vivier depuis ici."}
        is_id = re.fullmatch(r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}", asked)
        consultant_id, consultant_name = (asked.lower(), asked) if is_id else ("", asked)
        if not consultant_id:
            found = await bellum_api.search_talents(user_id, query=asked)
            if found is None:
                return {"error": "Le vivier n'a pas répondu."}
            rows = [r for r in (found.get("items") or []) if isinstance(r, dict) and r.get("id")]
            exact = [r for r in rows if " ".join(str(r.get("fullName") or "").split()).casefold() == asked.casefold()]
            picked = exact if exact else rows
            if not picked:
                return {
                    "status": "not_found",
                    "message": f"Je ne trouve aucun consultant « {asked} » dans le vivier de cet espace.",
                }
            if len(picked) > 1:
                return {
                    "status": "ambiguous",
                    "message": f"Plusieurs consultants répondent à « {asked} » : lequel ?",
                    "homonyms": [
                        {
                            "id": r.get("id"),
                            "full_name": r.get("fullName"),
                            "title": r.get("title"),
                            "zones": r.get("zones") or [],
                        }
                        for r in picked[:6]
                    ],
                }
            consultant_id = str(picked[0]["id"])
            consultant_name = " ".join(str(picked[0].get("fullName") or asked).split())
        mine_only = bool(tool_input.get("mine_only"))
        run = await bellum_api.talent_needs_match(user_id, consultant_id=consultant_id, mine_only=mine_only)
        if run is None:
            return {"error": "Le matching inverse n'a pas répondu : je ne peux pas lister ses besoins pour l'instant."}
        if run.get("error") == "consultant_not_found":
            return {
                "status": "not_found",
                "message": f"Je ne trouve pas « {asked} » dans le vivier de cet espace.",
            }
        if run.get("error") == "records_write_forbidden":
            return {"error": "Ton siège ne porte pas le droit d'écrire ce classement."}
        entries = [e for e in (run.get("needs") or []) if isinstance(e, dict)]
        if not entries:
            # Aucun besoin OUVERT dans l'espace — un fait, pas une panne.
            # #4421.2 — et plus une fin : le résultat POUSSE le marché (`c124`, renverse #3865.2).
            return {
                "status": "ok",
                "consultant": {"id": consultant_id, "name": consultant_name},
                "needs_evaluated": run.get("evaluatedCount") or 0,
                "buckets": {"recommended": [], "borderline": [], "excluded": [], "notEvaluable": []},
                "next": "find_accounts_for_talent",
                "next_input": {"consultant": consultant_id},
                "message": (
                    f"Aucun besoin ouvert dans cet espace n'a pu être classé contre {consultant_name} pour "
                    "l'instant — ce n'est pas que ses compétences ne correspondent à rien, c'est qu'aucun besoin "
                    "n'est ouvert à évaluer. Enchaîne find_accounts_for_talent dans ce même tour (le marché : "
                    "comptes, offres relevées, contacts), sans rien demander."
                ),
            }

        def _need_row(entry: dict[str, Any]) -> dict[str, Any] | None:
            need = entry.get("need") if isinstance(entry.get("need"), dict) else None
            result = entry.get("result") if isinstance(entry.get("result"), dict) else None
            if not need or not result:
                return None
            return {
                "need_id": need.get("needId"),
                "role": need.get("role"),
                "account_name": need.get("accountName"),
                "bucket": result.get("bucket"),
                "correspondence_score": result.get("correspondenceScore"),
                "pushable_score": result.get("pushableScore"),
                "axes": result.get("axes") or [],
                "exclusions": result.get("exclusions") or [],
                "gaps": result.get("gaps") or [],
            }

        rows = [row for row in (_need_row(e) for e in entries) if row is not None]
        buckets: dict[str, list[dict[str, Any]]] = {
            "recommended": [],
            "borderline": [],
            "excluded": [],
            "notEvaluable": [],
        }
        bucket_key = {
            "recommended": "recommended",
            "borderline": "borderline",
            "excluded": "excluded",
            "not_evaluable": "notEvaluable",
        }
        for row in rows:
            key = bucket_key.get(str(row.get("bucket") or ""), "borderline")
            buckets[key].append(row)
        truncated = False
        for key, items in buckets.items():
            capped, was_truncated = _capped(items)
            buckets[key] = capped
            truncated = truncated or was_truncated
        return {
            "status": "ok",
            "consultant": {"id": consultant_id, "name": consultant_name},
            "needs_evaluated": run.get("evaluatedCount") or len(rows),
            "buckets": buckets,
            "truncated": truncated,
        }

