    if name == "get_crm_presence":
        # #2852.6-53 (lot t02-29-09, suite) — même enveloppe canonique que
        # get_account_briefing, sur le pont CRM plutôt que sur
        # `bellum_workspace` : `permission_denied` (droit manquant, jamais un
        # `empty` qui suggérerait une recherche vide) distinct d'`empty`
        # (compte étranger — jamais un code de permission qui le révélerait).
        from app.models.tool_result_envelope import ToolResultEnvelope, ToolResultStatus, error_envelope
        from app.services import bellum_api
        from app.services.count_contract import build_count_contract

        account_id = str(tool_input.get("account_id") or "").strip()
        if not account_id:
            return {
                "error": "Un identifiant de compte est requis pour lire le CRM branché.",
                **error_envelope(
                    status=ToolResultStatus.INVALID_INPUT,
                    result_type="crm_presence",
                    error_code="missing_account_id",
                    suggested_next_step="Précise l'identifiant du compte, puis relance.",
                ).to_wire(),
            }
        result = await bellum_api.crm_presence(user_id, account_id)
        if result is None:
            return {
                "error": "Le CRM branché n'a pas répondu.",
                **error_envelope(
                    status=ToolResultStatus.PROVIDER_ERROR,
                    result_type="crm_presence",
                    error_code="provider_error",
                    suggested_next_step="Réessaie dans un instant : le CRM branché n'a pas répondu à temps.",
                ).to_wire(),
            }
        # `CopilotBridgeController.crmPresence` rend `{error: ...}` sur un
        # droit manquant ou un compte étranger — jamais deviné, traduit tel
        # quel plutôt qu'affiché en JSON brut.
        if result.get("error") == "crm_read_forbidden":
            return {
                "error": "Tu n'as pas le droit de lire le CRM branché.",
                **error_envelope(
                    status=ToolResultStatus.PERMISSION_DENIED,
                    result_type="crm_presence",
                    error_code="crm_read_forbidden",
                    suggested_next_step="Demande l'accès en lecture au CRM branché, ou continue sans lui.",
                ).to_wire(),
            }
        if result.get("error") == "account_not_found":
            return {
                "error": "Ce compte est introuvable dans cet espace.",
                **ToolResultEnvelope(
                    status=ToolResultStatus.EMPTY,
                    result_type="crm_presence",
                    sources_consulted=["crm_bridge"],
                    sources_succeeded=["crm_bridge"],
                ).to_wire(),
            }
        # #3228 (épopée #213.2, recette prod 30/09/2026) — « combien de
        # contacts chez X, et par quelle méthode » appelle CET outil À CÔTÉ de
        # `get_account_contacts` : sans son PROPRE `count_contract`, le modèle
        # n'avait qu'un chiffre structuré sur deux et retombait en prose pour
        # les DEUX (voir la carte manquante en prod). `contacts_count` est déjà
        # le total rendu par le CRM connecté — jamais recompté, jamais comparé
        # ici au compte Bellum (deux périmètres de collecte distincts).
        contacts_count = result.get("contacts_count")
        count_contract = (
            build_count_contract(
                metric_name="contacts_crm_du_compte",
                object_type="contact",
                unique_key=f"crm_presence:{account_id}",
                scope="compte",
                entity_scope=account_id,
                current_or_historical="current",
                source_layers=["crm_bridge"],
                raw_count=contacts_count,
                caveats=[
                    "Compte tel que le CRM connecté de l'espace le rend — jamais le nom du "
                    "fournisseur. Périmètre de collecte distinct du compte Bellum "
                    "(`contacts_du_compte`) : les deux ne s'additionnent ni ne se comparent ici."
                ],
            ).to_wire()
            if isinstance(contacts_count, int)
            else None
        )
        return {
            **result,
            **({"count_contract": count_contract} if count_contract else {}),
            **ToolResultEnvelope(
                status=ToolResultStatus.SUCCESS,
                result_type="crm_presence",
                sources_consulted=["crm_bridge"],
                sources_succeeded=["crm_bridge"],
            ).to_wire(),
        }

